static size_t ptn_var_dump_object_visible_property_count(PtnObject *object) {
    if (object == NULL) {
        return 0;
    }
    if (object->lazy_is_proxy &&
        ptn_value_deref(object->lazy_proxy_instance).type == PTN_OBJECT) {
        return 1;
    }
    return ptn_object_initialized_property_dump_count(object);
}

static void ptn_var_dump_object_header(
    PtnObject *object,
    size_t property_count,
    int debug
) {
    size_t class_name_len = ptn_class_name_dump_len(object->class_name);
    int display_lazy = object->lazy_uninitialized && !object->lazy_initializing;
    const char *prefix = display_lazy
        ? (object->lazy_is_proxy ? "lazy proxy object" : "lazy ghost object")
        : (object->lazy_is_proxy ? "lazy proxy object" : "object");
    if (debug) {
        printf(
            "%s(%.*s)#%zu (%zu) refcount(%zu){\n",
            prefix,
            (int)class_name_len,
            object->class_name,
            object->object_id,
            property_count,
            object->refcount
        );
    } else {
        printf(
            "%s(%.*s)#%zu (%zu) {\n",
            prefix,
            (int)class_name_len,
            object->class_name,
            object->object_id,
            property_count
        );
    }
}

static int ptn_var_dump_spl_fixed_array_object(
    PtnObject *object,
    size_t indent,
    PtnDumpSeenArrays *seen,
    int debug
) {
    if (object == NULL || !ptn_internal_class_name_is_spl_fixed_array(object->class_name)) {
        return 0;
    }
    PtnSplFixedArrayData *data = object->native_data == NULL
        ? NULL
        : (PtnSplFixedArrayData *)object->native_data;
    PtnValue array = ptn_spl_fixed_array_storage_to_array(data);
    PtnValue resolved_array = ptn_value_deref(array);
    PtnArray *entries = resolved_array.type == PTN_ARRAY ? resolved_array.as.array : NULL;
    ptn_var_dump_object_header(object, entries == NULL ? 0 : entries->len, debug);
    ptn_dump_seen_objects_push(seen, object);
    if (entries != NULL) {
        for (size_t i = 0; i < entries->len; i++) {
            ptn_var_dump_indent(indent + 1);
            ptn_var_dump_array_key(entries->entries[i].key);
            if (debug) {
                ptn_debug_zval_dump_value_indented(entries->entries[i].value, indent + 1, seen);
            } else {
                ptn_var_dump_value_indented(entries->entries[i].value, indent + 1, seen);
            }
        }
    }
    ptn_dump_seen_objects_pop(seen);
    ptn_var_dump_indent(indent);
    fputs("}\n", stdout);
    ptn_value_destroy(&array);
    return 1;
}

static int ptn_var_dump_object_proxy_instance(
    PtnObject *object,
    size_t indent,
    PtnDumpSeenArrays *seen,
    int debug
) {
    if (object == NULL || !object->lazy_is_proxy || object->lazy_uninitialized) {
        return 0;
    }
    PtnValue instance = ptn_value_deref(object->lazy_proxy_instance);
    if (instance.type != PTN_OBJECT) {
        return 0;
    }
    ptn_var_dump_indent(indent + 1);
    fputs("[\"instance\"]=>\n", stdout);
    if (debug) {
        if (instance.type == PTN_OBJECT) {
            instance.as.object->refcount++;
        }
        ptn_debug_zval_dump_value_indented(instance, indent + 1, seen);
        if (instance.type == PTN_OBJECT) {
            instance.as.object->refcount--;
        }
    } else {
        ptn_var_dump_value_indented(instance, indent + 1, seen);
    }
    return 1;
}

static int ptn_var_dump_weak_reference_object(
    PtnObject *object,
    size_t indent,
    PtnDumpSeenArrays *seen,
    int debug
) {
    if (object == NULL || !ptn_internal_class_name_is_weak_reference(object->class_name)) {
        return 0;
    }

    PtnObject *referent = ptn_weak_reference_object_referent(object);
    ptn_var_dump_object_header(object, 1, debug);
    ptn_dump_seen_objects_push(seen, object);
    ptn_var_dump_indent(indent + 1);
    fputs("[\"object\"]=>\n", stdout);
    if (referent == NULL) {
        ptn_var_dump_indent(indent + 1);
        fputs("NULL\n", stdout);
    } else {
        PtnValue referent_value = ptn_object(referent);
        referent_value.owned = 0;
        if (debug) {
            referent->refcount++;
            ptn_debug_zval_dump_value_indented(referent_value, indent + 1, seen);
            referent->refcount--;
        } else {
            ptn_var_dump_value_indented(referent_value, indent + 1, seen);
        }
    }
    ptn_dump_seen_objects_pop(seen);
    ptn_var_dump_indent(indent);
    fputs("}\n", stdout);
    return 1;
}

static int ptn_internal_function_parameter_by_ref(const char *name, size_t index) {
    if (name == NULL) {
        return 0;
    }
    if (ptn_ascii_case_equal(name, "array_multisort")) {
        return 1;
    }
    if (index == 1 &&
        (ptn_ascii_case_equal(name, "PDOStatement::bindParam") ||
         ptn_ascii_case_equal(name, "SQLite3Stmt::bindParam"))) {
        return 1;
    }
    if (index == 0 && ptn_internal_function_first_parameter_is_array_reference(name)) {
        return 1;
    }
    if (index == 2 &&
        (ptn_ascii_case_equal(name, "preg_match") ||
            ptn_ascii_case_equal(name, "preg_match_all") ||
            ptn_ascii_case_equal(name, "similar_text"))) {
        return 1;
    }
    if ((index == 2 || index == 3) && ptn_ascii_case_equal(name, "xml_parse_into_struct")) {
        return 1;
    }
    if (index == 1 && ptn_ascii_case_equal(name, "parse_str")) {
        return 1;
    }
    if (index == 1 && ptn_ascii_case_equal(name, "mb_parse_str")) {
        return 1;
    }
    if (index == 2 && ptn_ascii_case_equal(name, "getopt")) {
        return 1;
    }
    if (index == 2 &&
        (ptn_ascii_case_equal(name, "mb_ereg") ||
            ptn_ascii_case_equal(name, "mb_eregi"))) {
        return 1;
    }
    if (index >= 2 && ptn_ascii_case_equal(name, "mb_convert_variables")) {
        return 1;
    }
    if (index == 2 && ptn_ascii_case_equal(name, "is_callable")) {
        return 1;
    }
    if (index == 3 &&
        (ptn_ascii_case_equal(name, "str_replace") ||
            ptn_ascii_case_equal(name, "str_ireplace"))) {
        return 1;
    }
    if (index == 4 &&
        (ptn_ascii_case_equal(name, "preg_filter") ||
            ptn_ascii_case_equal(name, "preg_replace") ||
            ptn_ascii_case_equal(name, "preg_replace_callback"))) {
        return 1;
    }
    if (index == 3 && ptn_ascii_case_equal(name, "preg_replace_callback_array")) {
        return 1;
    }
    if (index >= 2 &&
        (ptn_ascii_case_equal(name, "sscanf") || ptn_ascii_case_equal(name, "fscanf"))) {
        return 1;
    }
    return 0;
}

static int ptn_internal_function_parameter_can_be_passed_by_value(const char *name, size_t index) {
    if (name == NULL) {
        return 1;
    }
    if (ptn_ascii_case_equal(name, "array_multisort")) {
        return 1;
    }
    if (ptn_internal_function_parameter_by_ref(name, index)) {
        return 0;
    }
    return 1;
}

