static PtnValue ptn_internal_substr_count(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand haystack = ptn_internal_expect_string_arg(runtime, "substr_count", 1, "haystack", args[0], line);
    PtnStringOperand needle = ptn_internal_expect_string_arg(runtime, "substr_count", 2, "needle", args[1], line);
    if (needle.len == 0) {
        ptn_string_operand_free(haystack);
        ptn_string_operand_free(needle);
        ptn_throw_exception(
            runtime,
            "ValueError",
            "substr_count(): Argument #2 ($needle) must not be empty"
        );
        return ptn_null();
    }

    int64_t raw_offset = argc >= 3
        ? ptn_internal_expect_integer_arg(runtime, "substr_count", 3, "offset", args[2], line)
        : 0;
    size_t start = 0;
    if (!ptn_normalize_string_offset(runtime, "substr_count", raw_offset, haystack.len, &start)) {
        ptn_string_operand_free(haystack);
        ptn_string_operand_free(needle);
        return ptn_null();
    }

    size_t end = haystack.len;
    if (argc >= 4 && ptn_value_deref(args[3]).type != PTN_NULL) {
        int64_t raw_length = ptn_internal_expect_integer_arg(runtime, "substr_count", 4, "length", args[3], line);
        int valid_length = 1;
        if (raw_length >= 0) {
            valid_length = (uint64_t)raw_length <= (uint64_t)(haystack.len - start);
            if (valid_length) {
                end = start + (size_t)raw_length;
            }
        } else {
            uint64_t trim = raw_length == INT64_MIN
                ? ((uint64_t)INT64_MAX + 1)
                : (uint64_t)(-raw_length);
            valid_length = trim <= (uint64_t)haystack.len && haystack.len - (size_t)trim >= start;
            if (valid_length) {
                end = haystack.len - (size_t)trim;
            }
        }
        if (!valid_length) {
            ptn_string_operand_free(haystack);
            ptn_string_operand_free(needle);
            ptn_throw_exception(
                runtime,
                "ValueError",
                "substr_count(): Argument #4 ($length) must be contained in argument #1 ($haystack)"
            );
            return ptn_null();
        }
    }

    int64_t count = 0;
    size_t offset = start;
    while (offset <= end && needle.len <= end - offset) {
        size_t match = ptn_find_bytes_from(
            haystack.data,
            end,
            needle.data,
            needle.len,
            offset,
            0
        );
        if (match == SIZE_MAX || match + needle.len > end) {
            break;
        }
        count++;
        offset = match + needle.len;
    }

    ptn_string_operand_free(haystack);
    ptn_string_operand_free(needle);
    return ptn_int(count);
}

static PtnValue ptn_internal_strrchr(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand haystack = ptn_internal_expect_string_arg(runtime, "strrchr", 1, "haystack", args[0], line);
    PtnStringOperand needle = ptn_internal_expect_string_arg(runtime, "strrchr", 2, "needle", args[1], line);
    int before_needle = argc >= 3 && ptn_is_truthy(args[2]);
    unsigned char byte = needle.len == 0 ? 0 : (unsigned char)needle.data[0];
    size_t match = haystack.len;
    for (size_t i = haystack.len; i > 0; i--) {
        if ((unsigned char)haystack.data[i - 1] == byte) {
            match = i - 1;
            break;
        }
    }
    ptn_string_operand_free(needle);
    if (match == haystack.len) {
        ptn_string_operand_free(haystack);
        return ptn_bool(0);
    }

    size_t start = before_needle ? 0 : match;
    size_t len = before_needle ? match : haystack.len - match;
    PtnValue result = ptn_owned_string_len(ptn_duplicate_string_len(haystack.data + start, len), len);
    ptn_string_operand_free(haystack);
    return result;
}

static void ptn_string_buffer_append_repeated_pattern(PtnStringBuffer *buffer, PtnStringOperand pattern, size_t len) {
    size_t remaining = len;
    while (remaining > 0) {
        size_t chunk_len = pattern.len < remaining ? pattern.len : remaining;
        ptn_string_buffer_append_len(buffer, pattern.data, chunk_len);
        remaining -= chunk_len;
    }
}

static PtnValue ptn_internal_str_pad(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "str_pad", 1, "string", args[0], line);
    int64_t length = ptn_internal_expect_integer_arg(runtime, "str_pad", 2, "length", args[1], line);
    PtnStringOperand pad_string = argc >= 3
        ? ptn_internal_expect_string_arg(runtime, "str_pad", 3, "pad_string", args[2], line)
        : ptn_string_operand_borrowed(" ");

    if (pad_string.len == 0) {
        ptn_string_operand_free(input);
        ptn_string_operand_free(pad_string);
        ptn_throw_exception(
            runtime,
            "ValueError",
            "str_pad(): Argument #3 ($pad_string) must not be empty"
        );
        return ptn_null();
    }

    int64_t pad_type = argc >= 4
        ? ptn_internal_expect_integer_arg(runtime, "str_pad", 4, "pad_type", args[3], line)
        : PTN_STR_PAD_RIGHT;
    if (pad_type != PTN_STR_PAD_LEFT &&
        pad_type != PTN_STR_PAD_RIGHT &&
        pad_type != PTN_STR_PAD_BOTH) {
        ptn_string_operand_free(input);
        ptn_string_operand_free(pad_string);
        ptn_throw_exception(
            runtime,
            "ValueError",
            "str_pad(): Argument #4 ($pad_type) must be STR_PAD_LEFT, STR_PAD_RIGHT, or STR_PAD_BOTH"
        );
        return ptn_null();
    }

    if (length <= 0 || (uint64_t)length <= (uint64_t)input.len) {
        char *copy = ptn_duplicate_string_len(input.data, input.len);
        size_t copy_len = input.len;
        ptn_string_operand_free(input);
        ptn_string_operand_free(pad_string);
        return ptn_owned_string_len(copy, copy_len);
    }

    uint64_t requested_len = (uint64_t)length;
    if (requested_len > (uint64_t)SIZE_MAX - 1U) {
        ptn_emit_memory_allocation_overflow_error(runtime, (size_t)requested_len, 1, 1, line);
    }

    size_t target_len = (size_t)requested_len;
    size_t allocation_len = target_len + 1;
    size_t memory_limit = 0;
    if (ptn_runtime_memory_limit_bytes(runtime, &memory_limit) &&
        memory_limit != 0 &&
        allocation_len > memory_limit) {
        char message[192];
        int written = snprintf(
            message,
            sizeof(message),
            "Allowed memory size of %zu bytes exhausted (tried to allocate %zu bytes)",
            memory_limit,
            allocation_len
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        if (runtime->diagnostics.display_errors) {
            FILE *stream = runtime->diagnostics.stream == NULL ? stderr : runtime->diagnostics.stream;
            fflush(stdout);
            fputc('\n', stream);
        }
        ptn_emit_fatal_error_at(runtime, message, runtime->source_path, line);
    }

    size_t pad_len = target_len - input.len;
    size_t left_len = 0;
    size_t right_len = 0;
    if (pad_type == PTN_STR_PAD_LEFT) {
        left_len = pad_len;
    } else if (pad_type == PTN_STR_PAD_RIGHT) {
        right_len = pad_len;
    } else {
        left_len = pad_len / 2;
        right_len = pad_len - left_len;
    }

    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    ptn_string_buffer_reserve(&output, target_len);
    ptn_string_buffer_append_repeated_pattern(&output, pad_string, left_len);
    ptn_string_buffer_append_len(&output, input.data, input.len);
    ptn_string_buffer_append_repeated_pattern(&output, pad_string, right_len);

    ptn_string_operand_free(input);
    ptn_string_operand_free(pad_string);
    return ptn_owned_string_len(output.data, output.len);
}

static PtnValue ptn_internal_str_repeat(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "str_repeat", 1, "string", args[0], line);
    int64_t repeat = ptn_value_to_integer(args[1]);
    if (repeat < 0) {
        ptn_string_operand_free(input);
        ptn_throw_exception(
            runtime,
            "ValueError",
            "str_repeat(): Argument #2 ($times) must be greater than or equal to 0"
        );
    }
    if (repeat == 0 || input.len == 0) {
        ptn_string_operand_free(input);
        char *empty = malloc(1);
        if (empty == NULL) {
            ptn_abort_out_of_memory();
        }
        empty[0] = '\0';
        return ptn_owned_string_len(empty, 0);
    }

    size_t times = (size_t)repeat;
    if (input.len > SIZE_MAX / times || input.len * times == SIZE_MAX) {
        ptn_string_operand_free(input);
        ptn_abort_out_of_memory();
    }
    size_t output_len = input.len * times;
    char *output = malloc(output_len + 1);
    if (output == NULL) {
        ptn_abort_out_of_memory();
    }
    for (size_t i = 0; i < times; i++) {
        memcpy(output + (i * input.len), input.data, input.len);
    }
    output[output_len] = '\0';
    ptn_string_operand_free(input);
    return ptn_owned_string_len(output, output_len);
}

static PtnStringOperand ptn_trim_default_charlist(void) {
    static const char bytes[] = { ' ', '\t', '\n', '\r', '\0', '\v', '\f' };
    return ptn_string_operand_borrowed_len(bytes, sizeof(bytes));
}

static void ptn_trim_emit_invalid_range_warning(
    PtnRuntime *runtime,
    const char *function_name,
    const char *reason,
    size_t line
) {
    char message[160];
    int written = snprintf(
        message,
        sizeof(message),
        "%s(): Invalid '..'-range%s",
        function_name,
        reason
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_emit_warning(&runtime->diagnostics, message, line);
}

static void ptn_trim_charlist_table(
    PtnRuntime *runtime,
    const char *function_name,
    PtnStringOperand charlist,
    size_t line,
    unsigned char table[256]
) {
    memset(table, 0, 256);
    for (size_t i = 0; i < charlist.len; i++) {
        unsigned char start = (unsigned char)charlist.data[i];
        if (
            i + 3 < charlist.len &&
            charlist.data[i + 1] == '.' &&
            charlist.data[i + 2] == '.'
        ) {
            unsigned char end = (unsigned char)charlist.data[i + 3];
            if (i + 5 < charlist.len && charlist.data[i + 4] == '.' && charlist.data[i + 5] == '.') {
                ptn_trim_emit_invalid_range_warning(runtime, function_name, "", line);
                table[start] = 1;
                table['.'] = 1;
                table[end] = 1;
                i += 5;
                continue;
            }
            if (start <= end) {
                for (unsigned int byte = start; byte <= end; byte++) {
                    table[byte] = 1;
                }
                i += 3;
                continue;
            }
            ptn_trim_emit_invalid_range_warning(
                runtime,
                function_name,
                ", '..'-range needs to be incrementing",
                line
            );
            table[start] = 1;
            table['.'] = 1;
            table[end] = 1;
            i += 3;
            continue;
        }
        if (start == '.' && i + 1 < charlist.len && charlist.data[i + 1] == '.') {
            const char *reason = i == 0
                ? ", no character to the left of '..'"
                : (i + 2 >= charlist.len ? ", no character to the right of '..'" : "");
            ptn_trim_emit_invalid_range_warning(runtime, function_name, reason, line);
        }
        table[start] = 1;
    }
}

static PtnValue ptn_trim_string_value(
    PtnRuntime *runtime,
    const char *function_name,
    PtnStringOperand input,
    PtnStringOperand charlist,
    size_t line,
    int trim_left,
    int trim_right
) {
    unsigned char table[256];
    ptn_trim_charlist_table(runtime, function_name, charlist, line, table);

    size_t start = 0;
    size_t end = input.len;
    if (trim_left) {
        while (start < end && table[(unsigned char)input.data[start]]) {
            start++;
        }
    }
    if (trim_right) {
        while (end > start && table[(unsigned char)input.data[end - 1]]) {
            end--;
        }
    }

    size_t output_len = end - start;
    char *output = ptn_duplicate_string_len(input.data + start, output_len);
    return ptn_owned_string_len(output, output_len);
}

static PtnValue ptn_internal_trim_named(
    PtnRuntime *runtime,
    const char *function_name,
    size_t argc,
    const PtnValue *args,
    size_t line,
    int trim_left,
    int trim_right
) {
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, function_name, 1, "string", args[0], line);
    PtnStringOperand charlist = argc >= 2
        ? ptn_internal_expect_string_arg(runtime, function_name, 2, "characters", args[1], line)
        : ptn_trim_default_charlist();
    PtnValue result = ptn_trim_string_value(runtime, function_name, input, charlist, line, trim_left, trim_right);
    ptn_string_operand_free(input);
    ptn_string_operand_free(charlist);
    return result;
}

static PtnValue ptn_internal_trim(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    return ptn_internal_trim_named(runtime, "trim", argc, args, line, 1, 1);
}

static PtnValue ptn_internal_ltrim(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    return ptn_internal_trim_named(runtime, "ltrim", argc, args, line, 1, 0);
}

static PtnValue ptn_internal_rtrim(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    return ptn_internal_trim_named(runtime, "rtrim", argc, args, line, 0, 1);
}

static PtnValue ptn_internal_chop(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    return ptn_internal_trim_named(runtime, "chop", argc, args, line, 0, 1);
}

typedef struct {
    PtnStringOperand from;
    PtnStringOperand to;
    size_t order;
} PtnStrtrReplacement;

static PtnStringOperand ptn_array_key_string_operand(PtnArrayKey key) {
    if (key.type == PTN_ARRAY_KEY_STRING) {
        return ptn_string_operand_borrowed(key.as.string);
    }

    char buffer[64];
    int written = snprintf(buffer, sizeof(buffer), "%lld", (long long)key.as.integer);
    if (written < 0 || (size_t)written >= sizeof(buffer)) {
        ptn_abort_out_of_memory();
    }
    return ptn_string_operand_owned_len(
        ptn_duplicate_string_len(buffer, (size_t)written),
        (size_t)written
    );
}

static void ptn_strtr_replacements_free(PtnStrtrReplacement *replacements, size_t count) {
    for (size_t i = 0; i < count; i++) {
        ptn_string_operand_free(replacements[i].from);
        ptn_string_operand_free(replacements[i].to);
    }
    free(replacements);
}

static void ptn_strtr_replacements_sort(PtnStrtrReplacement *replacements, size_t count) {
    for (size_t i = 1; i < count; i++) {
        PtnStrtrReplacement current = replacements[i];
        size_t j = i;
        while (j > 0 &&
            (replacements[j - 1].from.len < current.from.len ||
                (replacements[j - 1].from.len == current.from.len &&
                    replacements[j - 1].order > current.order))) {
            replacements[j] = replacements[j - 1];
            j--;
        }
        replacements[j] = current;
    }
}

static PtnValue ptn_strtr_array(PtnRuntime *runtime, PtnStringOperand input, PtnArray *map, size_t line) {
    if (input.len == 0) {
        return ptn_string("");
    }

    PtnStrtrReplacement *replacements = NULL;
    if (map->len != 0) {
        replacements = malloc(map->len * sizeof(PtnStrtrReplacement));
        if (replacements == NULL) {
            ptn_abort_out_of_memory();
        }
    }

    size_t replacement_count = 0;
    for (size_t i = 0; i < map->len; i++) {
        PtnStringOperand from = ptn_array_key_string_operand(map->entries[i].key);
        if (from.len == 0) {
            ptn_emit_warning(&runtime->diagnostics, "strtr(): Ignoring replacement of empty string", line);
            ptn_string_operand_free(from);
            continue;
        }
        replacements[replacement_count].from = from;
        replacements[replacement_count].to = ptn_value_to_string_operand(map->entries[i].value);
        replacements[replacement_count].order = i;
        replacement_count++;
    }
    ptn_strtr_replacements_sort(replacements, replacement_count);

    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    size_t offset = 0;
    while (offset < input.len) {
        const PtnStrtrReplacement *matched = NULL;
        for (size_t i = 0; i < replacement_count; i++) {
            if (replacements[i].from.len <= input.len - offset &&
                memcmp(input.data + offset, replacements[i].from.data, replacements[i].from.len) == 0) {
                matched = &replacements[i];
                break;
            }
        }

        if (matched != NULL) {
            ptn_string_buffer_append_len(&output, matched->to.data, matched->to.len);
            offset += matched->from.len;
        } else {
            ptn_string_buffer_append_char(&output, input.data[offset]);
            offset++;
        }
    }

    ptn_strtr_replacements_free(replacements, replacement_count);
    return ptn_owned_string_len(output.data, output.len);
}

static PtnValue ptn_strtr_byte_map(PtnStringOperand input, PtnStringOperand from, PtnStringOperand to) {
    unsigned char map[256];
    for (size_t i = 0; i < sizeof(map); i++) {
        map[i] = (unsigned char)i;
    }
    size_t count = from.len < to.len ? from.len : to.len;
    for (size_t i = 0; i < count; i++) {
        map[(unsigned char)from.data[i]] = (unsigned char)to.data[i];
    }

    char *output = malloc(input.len + 1);
    if (output == NULL) {
        ptn_abort_out_of_memory();
    }
    for (size_t i = 0; i < input.len; i++) {
        output[i] = (char)map[(unsigned char)input.data[i]];
    }
    output[input.len] = '\0';
    return ptn_owned_string_len(output, input.len);
}

static PtnStringOperand ptn_internal_expect_str_replace_arg(
    PtnRuntime *runtime,
    const char *function_name,
    size_t position,
    const char *argument_name,
    PtnValue value,
    size_t line
);

static PtnStringOperand ptn_internal_expect_strtr_from_arg(PtnRuntime *runtime, PtnValue value, size_t line) {
    value = ptn_value_deref(value);
    if (value.type == PTN_NULL) {
        ptn_emit_deprecation(
            &runtime->diagnostics,
            "strtr(): Passing null to parameter #2 ($from) of type array|string is deprecated",
            line
        );
        return ptn_value_to_string_operand_with_runtime(runtime, value, line);
    }
    return ptn_internal_expect_string_arg(runtime, "strtr", 2, "from", value, line);
}

static PtnValue ptn_internal_strtr(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "strtr", 1, "string", args[0], line);
    if (argc == 2) {
        PtnValue map_value = ptn_value_deref(args[1]);
        if (map_value.type != PTN_ARRAY) {
            ptn_string_operand_free(input);
            const char *given = map_value.type == PTN_BOOL
                ? (map_value.as.boolean ? "true" : "false")
                : ptn_internal_string_arg_type_name(map_value);
            char message[192];
            int written = snprintf(
                message,
                sizeof(message),
                "strtr(): Argument #2 ($from) must be of type array, %s given",
                given
            );
            if (written < 0 || (size_t)written >= sizeof(message)) {
                ptn_abort_out_of_memory();
            }
            ptn_throw_exception(runtime, "TypeError", message);
            return ptn_null();
        }
        PtnValue result = ptn_strtr_array(runtime, input, map_value.as.array, line);
        ptn_string_operand_free(input);
        return result;
    }

    PtnStringOperand from = ptn_internal_expect_strtr_from_arg(runtime, args[1], line);
    PtnStringOperand to = ptn_internal_expect_string_arg(runtime, "strtr", 3, "to", args[2], line);
    PtnValue result = ptn_strtr_byte_map(input, from, to);
    ptn_string_operand_free(input);
    ptn_string_operand_free(from);
    ptn_string_operand_free(to);
    return result;
}

static const char *ptn_find_bytes(
    const char *haystack,
    size_t haystack_len,
    const char *needle,
    size_t needle_len
) {
    size_t match = ptn_find_bytes_from(haystack, haystack_len, needle, needle_len, 0, 0);
    if (match == SIZE_MAX || needle_len == 0) {
        return NULL;
    }
    return haystack + match;
}

static void ptn_internal_throw_array_or_string_arg_type_error(
    PtnRuntime *runtime,
    const char *function_name,
    size_t position,
    const char *argument_name,
    PtnValue value
) {
    value = ptn_value_deref(value);
    char message[224];
    int written = snprintf(
        message,
        sizeof(message),
        "%s(): Argument #%zu ($%s) must be of type array|string, %s given",
        function_name,
        position,
        argument_name,
        ptn_internal_string_arg_type_name(value)
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "TypeError", message);
}

static PtnStringOperand ptn_internal_expect_str_replace_arg(
    PtnRuntime *runtime,
    const char *function_name,
    size_t position,
    const char *argument_name,
    PtnValue value,
    size_t line
) {
    value = ptn_value_deref(value);
    if (value.type == PTN_NULL) {
        char message[192];
        int written = snprintf(
            message,
            sizeof(message),
            "%s(): Passing null to parameter #%zu ($%s) of type array|string is deprecated",
            function_name,
            position,
            argument_name
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_emit_deprecation(&runtime->diagnostics, message, line);
    }
    if (
        value.type == PTN_RESOURCE ||
        value.type == PTN_CLOSURE ||
        value.type == PTN_EXCEPTION
    ) {
        ptn_internal_throw_array_or_string_arg_type_error(
            runtime,
            function_name,
            position,
            argument_name,
            value
        );
        return ptn_string_operand_borrowed("");
    }
    if (value.type == PTN_OBJECT) {
        PtnStringOperand object_string;
        if (ptn_try_object_to_string_operand(runtime, value, line, &object_string)) {
            return object_string;
        }
        ptn_internal_throw_array_or_string_arg_type_error(
            runtime,
            function_name,
            position,
            argument_name,
            value
        );
        return ptn_string_operand_borrowed("");
    }
    return ptn_value_to_string_operand_with_runtime(runtime, value, line);
}

typedef struct {
    PtnStringOperand *items;
    size_t len;
    int is_array;
} PtnStrReplaceStringList;

static void ptn_str_replace_string_list_free(PtnStrReplaceStringList *list) {
    for (size_t i = 0; i < list->len; i++) {
        ptn_string_operand_free(list->items[i]);
    }
    free(list->items);
    list->items = NULL;
    list->len = 0;
}

static PtnStringOperand ptn_str_replace_entry_to_string(PtnRuntime *runtime, PtnValue value, size_t line) {
    value = ptn_value_deref(value);
    if (value.type == PTN_ARRAY) {
        ptn_emit_spaced_warning(&runtime->diagnostics, "Array to string conversion", line);
    }
    return ptn_value_to_string_operand_with_runtime(runtime, value, line);
}

static PtnStrReplaceStringList ptn_str_replace_string_list_from_arg(
    PtnRuntime *runtime,
    const char *function_name,
    size_t position,
    const char *argument_name,
    PtnValue value,
    size_t line
) {
    value = ptn_value_deref(value);
    PtnStrReplaceStringList list;
    list.items = NULL;
    list.len = 0;
    list.is_array = value.type == PTN_ARRAY;

    if (!list.is_array) {
        list.items = malloc(sizeof(PtnStringOperand));
        if (list.items == NULL) {
            ptn_abort_out_of_memory();
        }
        list.len = 1;
        list.items[0] = ptn_internal_expect_str_replace_arg(
            runtime,
            function_name,
            position,
            argument_name,
            value,
            line
        );
        return list;
    }

    if (value.as.array->len == 0) {
        return list;
    }

    list.items = malloc(value.as.array->len * sizeof(PtnStringOperand));
    if (list.items == NULL) {
        ptn_abort_out_of_memory();
    }
    list.len = value.as.array->len;
    for (size_t i = 0; i < value.as.array->len; i++) {
        list.items[i] = ptn_str_replace_entry_to_string(runtime, value.as.array->entries[i].value, line);
    }
    return list;
}

static PtnValue ptn_str_replace_apply_to_string(
    PtnStringOperand subject,
    const PtnStrReplaceStringList *search,
    const PtnStrReplaceStringList *replace,
    int64_t *replacement_count,
    int case_insensitive
) {
    PtnStringOperand current = ptn_string_operand_owned_len(
        ptn_duplicate_string_len(subject.data, subject.len),
        subject.len
    );

    for (size_t i = 0; i < search->len; i++) {
        PtnStringOperand needle = search->items[i];
        if (needle.len == 0) {
            continue;
        }

        PtnStringOperand replacement = ptn_string_operand_borrowed("");
        if (replace->is_array) {
            if (i < replace->len) {
                replacement = replace->items[i];
            }
        } else if (replace->len > 0) {
            replacement = replace->items[0];
        }

        PtnStringBuffer output;
        ptn_string_buffer_init(&output);
        size_t offset = 0;
        while (offset < current.len) {
            const char *matched = ptn_find_bytes(
                current.data + offset,
                current.len - offset,
                needle.data,
                needle.len
            );
            if (case_insensitive) {
                size_t match = ptn_find_bytes_from(
                    current.data,
                    current.len,
                    needle.data,
                    needle.len,
                    offset,
                    1
                );
                matched = match == SIZE_MAX ? NULL : current.data + match;
            }
            if (matched == NULL) {
                ptn_string_buffer_append_len(&output, current.data + offset, current.len - offset);
                break;
            }
            size_t prefix_len = (size_t)(matched - (current.data + offset));
            ptn_string_buffer_append_len(&output, current.data + offset, prefix_len);
            ptn_string_buffer_append_len(&output, replacement.data, replacement.len);
            offset += prefix_len + needle.len;
            (*replacement_count)++;
        }

        ptn_string_operand_free(current);
        current = ptn_string_operand_owned_len(output.data, output.len);
    }

    char *result = current.owned;
    size_t result_len = current.len;
    current.owned = NULL;
    return ptn_owned_string_len(result, result_len);
}

static PtnValue ptn_internal_str_replace_named(
    PtnRuntime *runtime,
    const char *function_name,
    size_t argc,
    const PtnValue *args,
    size_t line,
    int case_insensitive
) {
    PtnValue replace_value = ptn_value_deref(args[1]);

    PtnStrReplaceStringList search =
        ptn_str_replace_string_list_from_arg(runtime, function_name, 1, "search", args[0], line);
    if (!search.is_array && replace_value.type == PTN_ARRAY) {
        ptn_str_replace_string_list_free(&search);
        char message[144];
        int written = snprintf(
            message,
            sizeof(message),
            "%s(): Argument #2 ($replace) must be of type string when argument #1 ($search) is a string",
            function_name
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "TypeError", message);
        return ptn_null();
    }

    PtnStrReplaceStringList replace =
        ptn_str_replace_string_list_from_arg(runtime, function_name, 2, "replace", args[1], line);
    int64_t replacement_count = 0;

    PtnValue result;
    PtnValue subject_value = ptn_value_deref(args[2]);
    if (subject_value.type == PTN_ARRAY) {
        result = ptn_array_from_literal_entries(0, NULL);
        for (size_t i = 0; i < subject_value.as.array->len; i++) {
            PtnStringOperand subject =
                ptn_str_replace_entry_to_string(runtime, subject_value.as.array->entries[i].value, line);
            PtnValue replaced =
                ptn_str_replace_apply_to_string(subject, &search, &replace, &replacement_count, case_insensitive);
            ptn_string_operand_free(subject);
            ptn_array_set_entry(
                result.as.array,
                ptn_array_key_clone(subject_value.as.array->entries[i].key),
                replaced
            );
        }
    } else {
        PtnStringOperand subject =
            ptn_internal_expect_str_replace_arg(runtime, function_name, 3, "subject", args[2], line);
        result = ptn_str_replace_apply_to_string(subject, &search, &replace, &replacement_count, case_insensitive);
        ptn_string_operand_free(subject);
    }

    if (argc >= 4 && args[3].type == PTN_REFERENCE) {
        PtnValue count_value = ptn_int(replacement_count);
        ptn_reference_assign(runtime, args[3].as.reference, count_value);
    }

    ptn_str_replace_string_list_free(&search);
    ptn_str_replace_string_list_free(&replace);
    return result;
}

static PtnValue ptn_internal_str_replace(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    return ptn_internal_str_replace_named(runtime, "str_replace", argc, args, line, 0);
}

static PtnValue ptn_internal_str_ireplace(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    return ptn_internal_str_replace_named(runtime, "str_ireplace", argc, args, line, 1);
}

static size_t ptn_substr_replace_clamp_positive(int64_t value, size_t limit) {
    if (value <= 0) {
        return 0;
    }
    if ((uint64_t)value > (uint64_t)limit) {
        return limit;
    }
    return (size_t)value;
}

static size_t ptn_substr_replace_clamp_negative_distance(int64_t value, size_t limit) {
    if (value >= 0) {
        return 0;
    }
    if (value == INT64_MIN) {
        return limit;
    }
    uint64_t distance = (uint64_t)(-value);
    if (distance > (uint64_t)limit) {
        return limit;
    }
    return (size_t)distance;
}

static PtnValue ptn_substr_replace_apply(
    PtnStringOperand subject,
    PtnStringOperand replacement,
    int64_t offset,
    int has_length,
    int64_t length
) {
    size_t start = offset >= 0
        ? ptn_substr_replace_clamp_positive(offset, subject.len)
        : subject.len - ptn_substr_replace_clamp_negative_distance(offset, subject.len);
    size_t end = subject.len;
    if (has_length) {
        if (length >= 0) {
            size_t replace_len = ptn_substr_replace_clamp_positive(length, subject.len - start);
            end = start + replace_len;
        } else {
            end = subject.len - ptn_substr_replace_clamp_negative_distance(length, subject.len);
            if (end < start) {
                end = start;
            }
        }
    }

    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    ptn_string_buffer_append_len(&output, subject.data, start);
    ptn_string_buffer_append_len(&output, replacement.data, replacement.len);
    ptn_string_buffer_append_len(&output, subject.data + end, subject.len - end);
    return ptn_owned_string_len(output.data, output.len);
}

static PtnStringOperand ptn_substr_replace_stable_operand(PtnStringOperand operand) {
    if (operand.owned != NULL) {
        return operand;
    }
    return ptn_string_operand_owned_len(
        ptn_duplicate_string_len(operand.data, operand.len),
        operand.len
    );
}

static PtnStringOperand ptn_substr_replace_value_to_string(
    PtnRuntime *runtime,
    PtnValue value,
    size_t line
) {
    if (ptn_value_deref(value).type == PTN_ARRAY) {
        ptn_emit_spaced_warning(&runtime->diagnostics, "Array to string conversion", line);
    }
    return ptn_value_to_string_operand_with_runtime(runtime, value, line);
}

static PtnStringOperand ptn_substr_replace_array_string_at(
    PtnRuntime *runtime,
    PtnValue value,
    size_t index,
    size_t line
) {
    value = ptn_value_deref(value);
    if (value.type != PTN_ARRAY) {
        return ptn_internal_expect_string_arg(runtime, "substr_replace", 2, "replace", value, line);
    }
    if (index >= value.as.array->len) {
        return ptn_string_operand_borrowed("");
    }
    return ptn_substr_replace_value_to_string(runtime, value.as.array->entries[index].value, line);
}

static int64_t ptn_substr_replace_array_integer_at(
    PtnValue value,
    size_t index,
    int64_t fallback
) {
    value = ptn_value_deref(value);
    if (value.type != PTN_ARRAY) {
        return ptn_value_to_integer(value);
    }
    if (index >= value.as.array->len) {
        return fallback;
    }
    return ptn_value_to_integer(value.as.array->entries[index].value);
}

static PtnValue ptn_internal_substr_replace(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnValue string_value = ptn_value_deref(args[0]);
    PtnValue offset_value = ptn_value_deref(args[2]);
    PtnValue length_value = argc >= 4 ? ptn_value_deref(args[3]) : ptn_null();
    int has_length = argc >= 4 && length_value.type != PTN_NULL;

    if (string_value.type != PTN_ARRAY) {
        if (offset_value.type == PTN_ARRAY) {
            ptn_throw_exception(
                runtime,
                "TypeError",
                "substr_replace(): Argument #3 ($offset) cannot be an array when working on a single string"
            );
            return ptn_null();
        }
        if (has_length && length_value.type == PTN_ARRAY) {
            ptn_throw_exception(
                runtime,
                "TypeError",
                "substr_replace(): Argument #4 ($length) cannot be an array when working on a single string"
            );
            return ptn_null();
        }

        PtnStringOperand subject =
            ptn_internal_expect_string_arg(runtime, "substr_replace", 1, "string", args[0], line);
        subject = ptn_substr_replace_stable_operand(subject);
        PtnStringOperand replacement;
        PtnValue replacement_value = ptn_value_deref(args[1]);
        if (replacement_value.type == PTN_ARRAY) {
            replacement = replacement_value.as.array->len == 0
                ? ptn_string_operand_borrowed("")
                : ptn_substr_replace_value_to_string(runtime, replacement_value.as.array->entries[0].value, line);
        } else {
            replacement =
                ptn_internal_expect_string_arg(runtime, "substr_replace", 2, "replace", replacement_value, line);
        }
        int64_t offset =
            ptn_internal_expect_integer_arg(runtime, "substr_replace", 3, "offset", args[2], line);
        int64_t length = has_length
            ? ptn_internal_expect_integer_arg(runtime, "substr_replace", 4, "length", args[3], line)
            : 0;
        PtnValue result = ptn_substr_replace_apply(subject, replacement, offset, has_length, length);
        ptn_string_operand_free(subject);
        ptn_string_operand_free(replacement);
        return result;
    }

    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    for (size_t i = 0; i < string_value.as.array->len; i++) {
        PtnArrayEntry *entry = &string_value.as.array->entries[i];
        PtnStringOperand subject = ptn_substr_replace_value_to_string(runtime, entry->value, line);
        subject = ptn_substr_replace_stable_operand(subject);
        PtnStringOperand replacement = ptn_substr_replace_array_string_at(runtime, args[1], i, line);
        int64_t offset = ptn_substr_replace_array_integer_at(args[2], i, 0);
        int entry_has_length = has_length;
        int64_t length = 0;
        if (has_length) {
            PtnValue raw_length = ptn_value_deref(args[3]);
            if (raw_length.type == PTN_ARRAY && i >= raw_length.as.array->len) {
                entry_has_length = 0;
            } else {
                length = ptn_substr_replace_array_integer_at(args[3], i, 0);
            }
        }
        PtnValue replaced = ptn_substr_replace_apply(subject, replacement, offset, entry_has_length, length);
        ptn_string_operand_free(subject);
        ptn_string_operand_free(replacement);
        ptn_array_set_entry(result.as.array, ptn_array_key_clone(entry->key), replaced);
    }
    return result;
}

static PtnValue ptn_internal_nl2br(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "nl2br", 1, "string", args[0], line);
    const char *break_tag = argc >= 2 && !ptn_is_truthy(args[1]) ? "<br>" : "<br />";
    size_t break_tag_len = strlen(break_tag);

    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    for (size_t i = 0; i < input.len; i++) {
        char byte = input.data[i];
        if (byte == '\r' || byte == '\n') {
            ptn_string_buffer_append_len(&output, break_tag, break_tag_len);
            ptn_string_buffer_append_char(&output, byte);
            if (i + 1 < input.len) {
                char next = input.data[i + 1];
                if ((byte == '\r' && next == '\n') || (byte == '\n' && next == '\r')) {
                    ptn_string_buffer_append_char(&output, next);
                    i++;
                }
            }
        } else {
            ptn_string_buffer_append_char(&output, byte);
        }
    }

    size_t len = output.len;
    ptn_string_operand_free(input);
    return ptn_owned_string_len(output.data, len);
}

static int ptn_regex_is_escaped(const char *data, size_t index) {
    size_t slash_count = 0;
    while (index > 0 && data[index - 1] == '\\') {
        slash_count++;
        index--;
    }
    return (slash_count % 2) != 0;
}

static int ptn_regex_delimiter_end(PtnStringOperand pattern, size_t *end_out) {
    if (pattern.len < 2) {
        return 0;
    }
    char delimiter = pattern.data[0];
    if (isalnum((unsigned char)delimiter) || delimiter == '\\' || delimiter == '\0' || isspace((unsigned char)delimiter)) {
        return 0;
    }
    char closing_delimiter = delimiter;
    switch (delimiter) {
        case '(':
            closing_delimiter = ')';
            break;
        case '[':
            closing_delimiter = ']';
            break;
        case '{':
            closing_delimiter = '}';
            break;
        case '<':
            closing_delimiter = '>';
            break;
        default:
            break;
    }
    for (size_t i = pattern.len - 1; i > 0; i--) {
        if (pattern.data[i] == closing_delimiter && !ptn_regex_is_escaped(pattern.data, i)) {
            *end_out = i;
            return 1;
        }
    }
    return 0;
}

static int ptn_regex_char_is_posix_special(char byte) {
    switch (byte) {
        case '.':
        case '^':
        case '$':
        case '*':
        case '+':
        case '?':
        case '(':
        case ')':
        case '[':
        case ']':
        case '{':
        case '}':
        case '|':
        case '\\':
            return 1;
        default:
            return 0;
    }
}

static int ptn_pcre_pattern_starts_with(
    PtnStringOperand pattern,
    size_t offset,
    size_t end,
    const char *literal
) {
    size_t literal_len = strlen(literal);
    return offset <= end &&
        literal_len <= end - offset &&
        memcmp(pattern.data + offset, literal, literal_len) == 0;
}

typedef struct {
    size_t posix_index;
    char *name;
} PtnPregCapture;

static void ptn_preg_captures_free(PtnPregCapture *captures, size_t capture_count) {
    if (captures == NULL) {
        return;
    }
    for (size_t i = 0; i < capture_count; i++) {
        free(captures[i].name);
    }
    free(captures);
}

static char *ptn_preg_format_error(const char *format, ...) {
    PtnStringBuffer buffer;
    ptn_string_buffer_init(&buffer);
    va_list args;
    va_start(args, format);
    int needed = vsnprintf(NULL, 0, format, args);
    va_end(args);
    if (needed < 0) {
        ptn_abort_out_of_memory();
    }
    ptn_string_buffer_reserve(&buffer, (size_t)needed);
    va_start(args, format);
    int written = vsnprintf(buffer.data, buffer.capacity, format, args);
    va_end(args);
    if (written < 0 || written != needed) {
        ptn_abort_out_of_memory();
    }
    buffer.len = (size_t)written;
    return buffer.data;
}

static int ptn_preg_capture_name_is_valid(PtnStringOperand pattern, size_t start, size_t end) {
    if (start >= end) {
        return 0;
    }
    unsigned char first = (unsigned char)pattern.data[start];
    if (!(isalpha(first) || first == '_')) {
        return 0;
    }
    for (size_t i = start + 1; i < end; i++) {
        unsigned char byte = (unsigned char)pattern.data[i];
        if (!(isalnum(byte) || byte == '_')) {
            return 0;
        }
    }
    return 1;
}

static void ptn_preg_capture_push(
    PtnPregCapture **captures,
    size_t *capture_count,
    size_t group_index,
    const char *name,
    size_t name_len
) {
    size_t new_count = *capture_count + 1;
    PtnPregCapture *new_captures = realloc(*captures, new_count * sizeof(PtnPregCapture));
    if (new_captures == NULL) {
        ptn_abort_out_of_memory();
    }
    new_captures[*capture_count].posix_index = group_index;
    new_captures[*capture_count].name = name == NULL ? NULL : ptn_duplicate_string_len(name, name_len);
    *captures = new_captures;
    *capture_count = new_count;
}

static int ptn_octal_nibble(unsigned char byte);

static char *ptn_pcre_pattern_to_posix(
    PtnStringOperand pattern,
    int *flags_out,
    PtnPregCapture **captures_out,
    size_t *capture_count_out,
    char **error_out
) {
    *captures_out = NULL;
    *capture_count_out = 0;
    *error_out = NULL;

    size_t end = 0;
    if (!ptn_regex_delimiter_end(pattern, &end)) {
        if (pattern.len == 0) {
            *error_out = ptn_duplicate_string("Empty regular expression");
        } else {
            char delimiter = pattern.data[0];
            if (isalnum((unsigned char)delimiter) || delimiter == '\\' || delimiter == '\0' || isspace((unsigned char)delimiter)) {
                *error_out = ptn_duplicate_string("Delimiter must not be alphanumeric, backslash, or NUL byte");
            } else {
                char closing_delimiter = delimiter;
                switch (delimiter) {
                    case '(':
                        closing_delimiter = ')';
                        break;
                    case '[':
                        closing_delimiter = ']';
                        break;
                    case '{':
                        closing_delimiter = '}';
                        break;
                    case '<':
                        closing_delimiter = '>';
                        break;
                    default:
                        break;
                }
                *error_out = ptn_preg_format_error("No ending delimiter '%c' found", closing_delimiter);
            }
        }
        return NULL;
    }

    *flags_out = REG_EXTENDED;
    int extended_mode = 0;
    for (size_t i = end + 1; i < pattern.len; i++) {
        switch (pattern.data[i]) {
            case 'i':
                *flags_out |= REG_ICASE;
                break;
            case 'm':
                *flags_out |= REG_NEWLINE;
                break;
            case 'x':
                extended_mode = 1;
                break;
            case 's':
            case 'S':
            case 'U':
            case 'u':
            case 'A':
            case 'D':
            case 'J':
                break;
            default:
                if (isalpha((unsigned char)pattern.data[i])) {
                    *error_out = ptn_preg_format_error("Unknown modifier '%c'", pattern.data[i]);
                    return NULL;
                }
                break;
        }
    }

    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    PtnPregCapture *captures = NULL;
    size_t capture_count = 0;
    size_t posix_group_index = 0;
    int in_char_class = 0;
    int char_class_has_literal_hyphen = 0;
    size_t char_class_start = 0;
    char delimiter = pattern.data[0];
    char closing_delimiter = delimiter;
    switch (delimiter) {
        case '(':
            closing_delimiter = ')';
            break;
        case '[':
            closing_delimiter = ']';
            break;
        case '{':
            closing_delimiter = '}';
            break;
        case '<':
            closing_delimiter = '>';
            break;
        default:
            break;
    }
    for (size_t i = 1; i < end; i++) {
        const char *float_atom = "(?:\\d+|(?=\\.\\d))(?:\\.\\d+)?(?:[Ee][+-]?\\d+)?";
        if (!in_char_class && ptn_pcre_pattern_starts_with(pattern, i, end, float_atom)) {
            ptn_string_buffer_append(&output, "([0-9]+(\\.[0-9]+)?|\\.[0-9]+)([Ee][+-]?[0-9]+)?");
            posix_group_index += 3;
            i += strlen(float_atom) - 1;
            continue;
        }

        char byte = pattern.data[i];
        if (extended_mode && !in_char_class) {
            if (isspace((unsigned char)byte)) {
                continue;
            }
            if (byte == '#') {
                while (i + 1 < end && pattern.data[i + 1] != '\n') {
                    i++;
                }
                continue;
            }
        }

        if (byte == '\\' && i + 1 < end) {
            char next = pattern.data[++i];
            switch (next) {
                case 'Q':
                    while (i + 1 < end) {
                        if (pattern.data[i + 1] == '\\' && i + 2 < end && pattern.data[i + 2] == 'E') {
                            i += 2;
                            break;
                        }
                        char quoted = pattern.data[++i];
                        if (ptn_regex_char_is_posix_special(quoted)) {
                            ptn_string_buffer_append_char(&output, '\\');
                        }
                        ptn_string_buffer_append_char(&output, quoted);
                    }
                    break;
                case 'E':
                    break;
                case 'd':
                    ptn_string_buffer_append(&output, in_char_class ? "0-9" : "[0-9]");
                    break;
                case 'D':
                    ptn_string_buffer_append(&output, in_char_class ? "^0-9" : "[^0-9]");
                    break;
                case 's':
                    ptn_string_buffer_append(&output, in_char_class ? "[:space:]" : "[[:space:]]");
                    break;
                case 'S':
                    ptn_string_buffer_append(&output, in_char_class ? "^[:space:]" : "[^[:space:]]");
                    break;
                case 'w':
                    ptn_string_buffer_append(&output, in_char_class ? "A-Za-z0-9_" : "[A-Za-z0-9_]");
                    break;
                case 'W':
                    ptn_string_buffer_append(&output, in_char_class ? "^A-Za-z0-9_" : "[^A-Za-z0-9_]");
                    break;
                case 'b':
                    ptn_string_buffer_append(&output, "\\<");
                    break;
                case 'n':
                    ptn_string_buffer_append_char(&output, '\n');
                    break;
                case 'r':
                    ptn_string_buffer_append_char(&output, '\r');
                    break;
                case 't':
                    ptn_string_buffer_append_char(&output, '\t');
                    break;
                case 'z':
                case 'Z':
                    ptn_string_buffer_append_char(&output, in_char_class ? next : '$');
                    break;
                case '0': {
                    unsigned int value = 0;
                    size_t digits = 0;
                    i--;
                    while (digits < 3 && i + 1 < end) {
                        int octal = ptn_octal_nibble((unsigned char)pattern.data[i + 1]);
                        if (octal < 0) {
                            break;
                        }
                        value = (value << 3) | (unsigned int)octal;
                        digits++;
                        i++;
                    }
                    ptn_string_buffer_append_char(&output, (char)(value & 0xff));
                    break;
                }
                default:
                    if (in_char_class && next == '-') {
                        char_class_has_literal_hyphen = 1;
                        break;
                    }
                    if (next == delimiter || next == closing_delimiter || !ptn_regex_char_is_posix_special(next)) {
                        ptn_string_buffer_append_char(&output, next);
                    } else {
                        ptn_string_buffer_append_char(&output, '\\');
                        ptn_string_buffer_append_char(&output, next);
                    }
                    break;
            }
            continue;
        }

        if (byte == '[') {
            in_char_class = 1;
            char_class_has_literal_hyphen = 0;
            char_class_start = i;
            ptn_string_buffer_append_char(&output, byte);
            continue;
        }
        if (byte == ']') {
            if (char_class_has_literal_hyphen) {
                ptn_string_buffer_append_char(&output, '-');
            }
            in_char_class = 0;
            ptn_string_buffer_append_char(&output, byte);
            continue;
        }

        if (!in_char_class && byte == '$' && i + 1 == end) {
            ptn_string_buffer_append(&output, "\n?$");
            continue;
        }

        if (!in_char_class && byte == '(') {
            posix_group_index++;
            if (i + 3 < end && pattern.data[i + 1] == '?' && pattern.data[i + 2] == 'P' && pattern.data[i + 3] == '<') {
                size_t name_start = i + 4;
                size_t name_end = name_start;
                while (name_end < end && pattern.data[name_end] != '>') {
                    name_end++;
                }
                if (name_end < end && ptn_preg_capture_name_is_valid(pattern, name_start, name_end)) {
                    ptn_string_buffer_append_char(&output, '(');
                    ptn_preg_capture_push(
                        &captures,
                        &capture_count,
                        posix_group_index,
                        pattern.data + name_start,
                        name_end - name_start
                    );
                    i = name_end;
                    continue;
                }
            }
            if (i + 2 < end && pattern.data[i + 1] == '?' && pattern.data[i + 2] == '<') {
                size_t name_start = i + 3;
                size_t name_end = name_start;
                while (name_end < end && pattern.data[name_end] != '>') {
                    name_end++;
                }
                if (name_end < end && ptn_preg_capture_name_is_valid(pattern, name_start, name_end)) {
                    ptn_string_buffer_append_char(&output, '(');
                    ptn_preg_capture_push(
                        &captures,
                        &capture_count,
                        posix_group_index,
                        pattern.data + name_start,
                        name_end - name_start
                    );
                    i = name_end;
                    continue;
                }
            }
            if (i + 2 < end && pattern.data[i + 1] == '?' && pattern.data[i + 2] == ':') {
                ptn_string_buffer_append_char(&output, '(');
                i += 2;
                continue;
            }
            ptn_preg_capture_push(&captures, &capture_count, posix_group_index, NULL, 0);
        }

        if (
            !in_char_class &&
            (byte == delimiter || byte == closing_delimiter) &&
            ptn_regex_char_is_posix_special(byte)
        ) {
            ptn_string_buffer_append_char(&output, '\\');
        }
        ptn_string_buffer_append_char(&output, byte);
    }
    if (in_char_class) {
        free(output.data);
        ptn_preg_captures_free(captures, capture_count);
        *error_out = ptn_preg_format_error(
            "Compilation failed: missing terminating ] for character class at offset %zu",
            char_class_start
        );
        return NULL;
    }
    *captures_out = captures;
    *capture_count_out = capture_count;
    return output.data;
}

static PtnValue ptn_preg_match_array_value(
    const char *subject,
    regmatch_t *matches,
    PtnPregCapture *captures,
    size_t capture_count,
    size_t base_offset,
    int offset_capture,
    int unmatched_as_null
);

static void ptn_preg_match_assign_matches(
    PtnRuntime *runtime,
    PtnValue matches_arg,
    const char *subject,
    regmatch_t *matches,
    PtnPregCapture *captures,
    size_t capture_count,
    int offset_capture
) {
    if (matches_arg.type != PTN_REFERENCE) {
        return;
    }

    PtnValue result = ptn_preg_match_array_value(subject, matches, captures, capture_count, 0, offset_capture, 0);
    ptn_reference_assign(runtime, matches_arg.as.reference, result);
    ptn_value_destroy(&result);
}

static PtnValue ptn_preg_capture_value(
    const char *subject,
    regmatch_t *matches,
    size_t match_index,
    size_t base_offset,
    int offset_capture,
    int unmatched_as_null
) {
    int matched = matches[match_index].rm_so >= 0 && matches[match_index].rm_eo >= matches[match_index].rm_so;
    PtnValue value;
    int64_t offset = -1;
    if (!matched) {
        value = unmatched_as_null ? ptn_null() : ptn_string("");
    } else {
        size_t start = base_offset + (size_t)matches[match_index].rm_so;
        size_t len = (size_t)(matches[match_index].rm_eo - matches[match_index].rm_so);
        offset = start > (size_t)INT64_MAX ? INT64_MAX : (int64_t)start;
        if (!offset_capture && len == 1) {
            static char ptn_preg_single_byte_literals[256][2];
            static int ptn_preg_single_byte_literals_initialized = 0;
            if (!ptn_preg_single_byte_literals_initialized) {
                for (size_t i = 0; i < 256; i++) {
                    ptn_preg_single_byte_literals[i][0] = (char)i;
                    ptn_preg_single_byte_literals[i][1] = '\0';
                }
                ptn_preg_single_byte_literals_initialized = 1;
            }
            value = ptn_string_literal(ptn_preg_single_byte_literals[(unsigned char)subject[start]], 1);
        } else {
            value = ptn_owned_string_len(ptn_duplicate_string_len(subject + start, len), len);
        }
    }

    if (!offset_capture) {
        return value;
    }

    PtnValue pair = ptn_array_from_literal_entries(0, NULL);
    ptn_array_set_entry(pair.as.array, ptn_array_int_key(0), value);
    ptn_array_set_entry(pair.as.array, ptn_array_int_key(1), ptn_int(offset));
    return pair;
}

static void ptn_preg_array_set_capture_entry(
    PtnArray *array,
    size_t capture_index,
    PtnPregCapture *captures,
    PtnValue value
) {
    if (capture_index > (size_t)INT64_MAX) {
        ptn_abort_out_of_memory();
    }
    if (capture_index > 0 && captures[capture_index - 1].name != NULL) {
        ptn_array_set_entry(
            array,
            ptn_array_string_key(captures[capture_index - 1].name),
            ptn_value_clone(value)
        );
    }
    ptn_array_set_entry(array, ptn_array_int_key((int64_t)capture_index), value);
}

static PtnValue ptn_preg_match_array_value(
    const char *subject,
    regmatch_t *matches,
    PtnPregCapture *captures,
    size_t capture_count,
    size_t base_offset,
    int offset_capture,
    int unmatched_as_null
) {
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    for (size_t i = 0; i <= capture_count; i++) {
        size_t match_index = i == 0 ? 0 : captures[i - 1].posix_index;
        PtnValue value = ptn_preg_capture_value(
            subject,
            matches,
            match_index,
            base_offset,
            offset_capture,
            unmatched_as_null
        );
        ptn_preg_array_set_capture_entry(result.as.array, i, captures, value);
    }
    return result;
}

static int ptn_preg_compile_posix(
    PtnRuntime *runtime,
    const char *function_name,
    PtnStringOperand pattern,
    regex_t *regex,
    PtnPregCapture **captures,
    size_t *capture_count,
    size_t *match_count,
    size_t line
) {
    int regex_flags = 0;
    char *compile_error = NULL;
    char *posix_pattern = ptn_pcre_pattern_to_posix(pattern, &regex_flags, captures, capture_count, &compile_error);
    if (posix_pattern == NULL) {
        char message[256];
        int written = snprintf(
            message,
            sizeof(message),
            "%s(): %s",
            function_name,
            compile_error == NULL ? "Compilation failed" : compile_error
        );
        free(compile_error);
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_emit_warning(&runtime->diagnostics, message, line);
        return 0;
    }

#if defined(_WIN32)
    free(posix_pattern);
    ptn_preg_captures_free(*captures, *capture_count);
    *captures = NULL;
    *capture_count = 0;
    char message[160];
    int written = snprintf(
        message,
        sizeof(message),
        "%s(): regex matching is unsupported on this platform",
        function_name
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_emit_warning(&runtime->diagnostics, message, line);
    return 0;
#else
    int compile_result = regcomp(regex, posix_pattern, regex_flags);
    free(posix_pattern);
    if (compile_result != 0) {
        ptn_preg_captures_free(*captures, *capture_count);
        *captures = NULL;
        *capture_count = 0;
        char message[128];
        int written = snprintf(message, sizeof(message), "%s(): Compilation failed", function_name);
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_emit_warning(&runtime->diagnostics, message, line);
        return 0;
    }
    *match_count = regex->re_nsub + 1;
    return 1;
#endif
}

static PtnValue ptn_internal_preg_match(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand pattern = ptn_value_to_string_operand(args[0]);
    PtnStringOperand subject = ptn_value_to_string_operand(args[1]);
    PtnPregCapture *captures = NULL;
    size_t capture_count = 0;
    size_t match_count = 0;
    regex_t regex;
    if (!ptn_preg_compile_posix(
            runtime,
            "preg_match",
            pattern,
            &regex,
            &captures,
            &capture_count,
            &match_count,
            line
        )) {
        ptn_string_operand_free(pattern);
        ptn_string_operand_free(subject);
        return ptn_bool(0);
    }

#if defined(_WIN32)
    ptn_string_operand_free(pattern);
    ptn_string_operand_free(subject);
    return ptn_bool(0);
#else
    regmatch_t *matches = calloc(match_count, sizeof(regmatch_t));
    if (matches == NULL) {
        regfree(&regex);
        ptn_string_operand_free(pattern);
        ptn_string_operand_free(subject);
        ptn_abort_out_of_memory();
    }
    char *subject_c = ptn_duplicate_string_len(subject.data, subject.len);
    int exec_result = regexec(&regex, subject_c, match_count, matches, 0);
    int matched = exec_result == 0;
    if (argc >= 3) {
        if (matched) {
            ptn_preg_match_assign_matches(runtime, args[2], subject_c, matches, captures, capture_count, 0);
        } else if (args[2].type == PTN_REFERENCE) {
            PtnValue empty_matches = ptn_array_from_literal_entries(0, NULL);
            ptn_reference_assign(runtime, args[2].as.reference, empty_matches);
            ptn_value_destroy(&empty_matches);
        }
    }

    free(subject_c);
    free(matches);
    ptn_preg_captures_free(captures, capture_count);
    regfree(&regex);
    ptn_string_operand_free(pattern);
    ptn_string_operand_free(subject);
    return ptn_int(matched ? 1 : 0);
#endif
}

static int ptn_preg_match_all_flags_are_valid(int64_t flags) {
    int64_t order = flags & (PTN_PREG_PATTERN_ORDER | PTN_PREG_SET_ORDER);
    if (order == (PTN_PREG_PATTERN_ORDER | PTN_PREG_SET_ORDER)) {
        return 0;
    }
    int64_t allowed = PTN_PREG_PATTERN_ORDER |
        PTN_PREG_SET_ORDER |
        PTN_PREG_OFFSET_CAPTURE |
        PTN_PREG_UNMATCHED_AS_NULL;
    return (flags & ~allowed) == 0;
}

static PtnValue ptn_preg_empty_matches_value(void) {
    return ptn_array_from_literal_entries(0, NULL);
}

static void ptn_preg_assign_empty_matches(PtnRuntime *runtime, PtnValue matches_arg) {
    if (matches_arg.type != PTN_REFERENCE) {
        return;
    }
    PtnValue empty_matches = ptn_preg_empty_matches_value();
    ptn_reference_assign(runtime, matches_arg.as.reference, empty_matches);
    ptn_value_destroy(&empty_matches);
}

static PtnValue ptn_internal_preg_match_all(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand pattern = ptn_value_to_string_operand(args[0]);
    PtnStringOperand subject = ptn_value_to_string_operand(args[1]);
    int64_t flags = argc >= 4
        ? ptn_internal_expect_integer_arg(runtime, "preg_match_all", 4, "flags", args[3], line)
        : PTN_PREG_PATTERN_ORDER;
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(pattern);
        ptn_string_operand_free(subject);
        return ptn_null();
    }
    if (!ptn_preg_match_all_flags_are_valid(flags)) {
        ptn_throw_exception(
            runtime,
            "ValueError",
            "preg_match_all(): Argument #4 ($flags) must be a PREG_* constant"
        );
        ptn_string_operand_free(pattern);
        ptn_string_operand_free(subject);
        return ptn_null();
    }

    int64_t raw_offset = argc >= 5
        ? ptn_internal_expect_integer_arg(runtime, "preg_match_all", 5, "offset", args[4], line)
        : 0;
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(pattern);
        ptn_string_operand_free(subject);
        return ptn_null();
    }
    size_t start_offset = 0;
    if (raw_offset < 0) {
        int64_t adjusted = (int64_t)subject.len + raw_offset;
        start_offset = adjusted > 0 ? (size_t)adjusted : 0;
    } else {
        start_offset = (uint64_t)raw_offset > subject.len ? subject.len : (size_t)raw_offset;
    }

    PtnPregCapture *captures = NULL;
    size_t capture_count = 0;
    size_t match_count = 0;
    regex_t regex;
    if (!ptn_preg_compile_posix(
            runtime,
            "preg_match_all",
            pattern,
            &regex,
            &captures,
            &capture_count,
            &match_count,
            line
        )) {
        ptn_string_operand_free(pattern);
        ptn_string_operand_free(subject);
        ptn_preg_assign_empty_matches(runtime, argc >= 3 ? args[2] : ptn_null());
        return ptn_bool(0);
    }

#if defined(_WIN32)
    ptn_string_operand_free(pattern);
    ptn_string_operand_free(subject);
    ptn_preg_assign_empty_matches(runtime, argc >= 3 ? args[2] : ptn_null());
    return ptn_bool(0);
#else
    regmatch_t *matches = calloc(match_count, sizeof(regmatch_t));
    if (matches == NULL) {
        regfree(&regex);
        ptn_preg_captures_free(captures, capture_count);
        ptn_string_operand_free(pattern);
        ptn_string_operand_free(subject);
        ptn_abort_out_of_memory();
    }

    int use_set_order = (flags & PTN_PREG_SET_ORDER) != 0;
    int offset_capture = (flags & PTN_PREG_OFFSET_CAPTURE) != 0;
    int unmatched_as_null = (flags & PTN_PREG_UNMATCHED_AS_NULL) != 0;
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    PtnArray **pattern_buckets = NULL;
    if (!use_set_order) {
        pattern_buckets = calloc(capture_count + 1, sizeof(PtnArray *));
        if (pattern_buckets == NULL) {
            free(matches);
            ptn_preg_captures_free(captures, capture_count);
            regfree(&regex);
            ptn_string_operand_free(pattern);
            ptn_string_operand_free(subject);
            ptn_abort_out_of_memory();
        }
        for (size_t i = 0; i <= capture_count; i++) {
            PtnValue bucket = ptn_array_from_literal_entries(0, NULL);
            pattern_buckets[i] = bucket.as.array;
            ptn_preg_array_set_capture_entry(result.as.array, i, captures, bucket);
        }
    }

    char *subject_c = ptn_duplicate_string_len(subject.data, subject.len);
    size_t offset = start_offset;
    size_t total_matches = 0;
    while (offset <= subject.len) {
        int exec_result = regexec(&regex, subject_c + offset, match_count, matches, 0);
        if (exec_result != 0 || matches[0].rm_so < 0 || matches[0].rm_eo < matches[0].rm_so) {
            break;
        }

        size_t relative_start = (size_t)matches[0].rm_so;
        size_t relative_end = (size_t)matches[0].rm_eo;
        size_t absolute_start = offset + relative_start;
        size_t absolute_end = offset + relative_end;
        if (absolute_start > subject.len || absolute_end > subject.len || absolute_end < absolute_start) {
            break;
        }

        if (use_set_order) {
            PtnValue match_array = ptn_preg_match_array_value(
                subject_c,
                matches,
                captures,
                capture_count,
                offset,
                offset_capture,
                unmatched_as_null
            );
            if (total_matches > (size_t)INT64_MAX) {
                ptn_abort_out_of_memory();
            }
            ptn_array_set_entry(result.as.array, ptn_array_int_key((int64_t)total_matches), match_array);
        } else {
            for (size_t i = 0; i <= capture_count; i++) {
                size_t match_index = i == 0 ? 0 : captures[i - 1].posix_index;
                PtnValue value = ptn_preg_capture_value(
                    subject_c,
                    matches,
                    match_index,
                    offset,
                    offset_capture,
                    unmatched_as_null
                );
                if (total_matches > (size_t)INT64_MAX) {
                    ptn_abort_out_of_memory();
                }
                ptn_array_set_entry(pattern_buckets[i], ptn_array_int_key((int64_t)total_matches), value);
            }
        }

        total_matches++;
        if (absolute_end == absolute_start) {
            if (absolute_end >= subject.len) {
                break;
            }
            offset = absolute_end + 1;
        } else {
            offset = absolute_end;
        }
    }

    if (argc >= 3 && args[2].type == PTN_REFERENCE) {
        ptn_reference_assign(runtime, args[2].as.reference, result);
    }
    ptn_value_destroy(&result);
    free(pattern_buckets);
    free(subject_c);
    free(matches);
    ptn_preg_captures_free(captures, capture_count);
    regfree(&regex);
    ptn_string_operand_free(pattern);
    ptn_string_operand_free(subject);
    if (total_matches > (size_t)INT64_MAX) {
        ptn_abort_out_of_memory();
    }
    return ptn_int((int64_t)total_matches);
#endif
}

static PtnValue ptn_preg_split_piece_value(
    const char *subject,
    size_t start,
    size_t len,
    int offset_capture
) {
    PtnValue string = ptn_owned_string_len(ptn_duplicate_string_len(subject + start, len), len);
    if (!offset_capture) {
        return string;
    }
    PtnValue pair = ptn_array_from_literal_entries(0, NULL);
    ptn_array_set_entry(pair.as.array, ptn_array_int_key(0), string);
    ptn_array_set_entry(
        pair.as.array,
        ptn_array_int_key(1),
        ptn_int(start > (size_t)INT64_MAX ? INT64_MAX : (int64_t)start)
    );
    return pair;
}

static void ptn_preg_split_append_piece(
    PtnArray *array,
    const char *subject,
    size_t start,
    size_t len,
    int flags
) {
    if ((flags & PTN_PREG_SPLIT_NO_EMPTY) != 0 && len == 0) {
        return;
    }
    if (array->len > (size_t)INT64_MAX) {
        ptn_abort_out_of_memory();
    }
    PtnValue value = ptn_preg_split_piece_value(subject, start, len, (flags & PTN_PREG_SPLIT_OFFSET_CAPTURE) != 0);
    ptn_array_set_entry(array, ptn_array_int_key((int64_t)array->len), value);
}

static PtnValue ptn_internal_preg_split(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand pattern = ptn_value_to_string_operand(args[0]);
    PtnStringOperand subject = ptn_value_to_string_operand(args[1]);
    int64_t limit = argc >= 3
        ? ptn_internal_expect_integer_arg(runtime, "preg_split", 3, "limit", args[2], line)
        : -1;
    int64_t flags = argc >= 4
        ? ptn_internal_expect_integer_arg(runtime, "preg_split", 4, "flags", args[3], line)
        : 0;
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(pattern);
        ptn_string_operand_free(subject);
        return ptn_null();
    }
    if (limit == 0) {
        limit = 1;
    }

    PtnPregCapture *captures = NULL;
    size_t capture_count = 0;
    size_t match_count = 0;
    regex_t regex;
    if (!ptn_preg_compile_posix(
            runtime,
            "preg_split",
            pattern,
            &regex,
            &captures,
            &capture_count,
            &match_count,
            line
        )) {
        ptn_string_operand_free(pattern);
        ptn_string_operand_free(subject);
        return ptn_bool(0);
    }

#if defined(_WIN32)
    ptn_string_operand_free(pattern);
    ptn_string_operand_free(subject);
    return ptn_bool(0);
#else
    regmatch_t *matches = calloc(match_count, sizeof(regmatch_t));
    if (matches == NULL) {
        regfree(&regex);
        ptn_preg_captures_free(captures, capture_count);
        ptn_string_operand_free(pattern);
        ptn_string_operand_free(subject);
        ptn_abort_out_of_memory();
    }

    char *subject_c = ptn_duplicate_string_len(subject.data, subject.len);
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    size_t offset = 0;
    while (offset <= subject.len && (limit < 0 || (int64_t)result.as.array->len < limit - 1)) {
        int exec_result = regexec(&regex, subject_c + offset, match_count, matches, 0);
        if (exec_result != 0 || matches[0].rm_so < 0 || matches[0].rm_eo < matches[0].rm_so) {
            break;
        }
        size_t start = offset + (size_t)matches[0].rm_so;
        size_t end = offset + (size_t)matches[0].rm_eo;
        if (start > subject.len || end > subject.len || end < start) {
            break;
        }

        ptn_preg_split_append_piece(result.as.array, subject_c, offset, start - offset, (int)flags);
        if ((flags & PTN_PREG_SPLIT_DELIM_CAPTURE) != 0) {
            for (size_t i = 1; i <= capture_count; i++) {
                size_t match_index = captures[i - 1].posix_index;
                if (matches[match_index].rm_so < 0 || matches[match_index].rm_eo < matches[match_index].rm_so) {
                    continue;
                }
                size_t capture_start = offset + (size_t)matches[match_index].rm_so;
                size_t capture_end = offset + (size_t)matches[match_index].rm_eo;
                if (capture_start > subject.len || capture_end > subject.len || capture_end < capture_start) {
                    continue;
                }
                ptn_preg_split_append_piece(
                    result.as.array,
                    subject_c,
                    capture_start,
                    capture_end - capture_start,
                    (int)flags
                );
            }
        }

        if (end == start) {
            if (end >= subject.len) {
                offset = end;
                break;
            }
            offset = end + 1;
        } else {
            offset = end;
        }
    }
    ptn_preg_split_append_piece(result.as.array, subject_c, offset, subject.len - offset, (int)flags);

    free(subject_c);
    free(matches);
    ptn_preg_captures_free(captures, capture_count);
    regfree(&regex);
    ptn_string_operand_free(pattern);
    ptn_string_operand_free(subject);
    return result;
#endif
}

static int ptn_preg_quote_needs_escape(unsigned char byte) {
    switch (byte) {
        case '.':
        case '\\':
        case '+':
        case '*':
        case '?':
        case '[':
        case '^':
        case ']':
        case '$':
        case '(':
        case ')':
        case '{':
        case '}':
        case '=':
        case '!':
        case '<':
        case '>':
        case '|':
        case ':':
        case '-':
        case '#':
            return 1;
        default:
            return 0;
    }
}

static int ptn_preg_quote_is_delimiter(unsigned char byte, PtnStringOperand delimiter) {
    for (size_t i = 0; i < delimiter.len; i++) {
        if ((unsigned char)delimiter.data[i] == byte) {
            return 1;
        }
    }
    return 0;
}

static PtnValue ptn_internal_preg_quote(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input =
        ptn_internal_expect_string_arg(runtime, "preg_quote", 1, "str", args[0], line);
    PtnStringOperand delimiter = { NULL, NULL, 0 };
    if (argc >= 2 && ptn_value_deref(args[1]).type != PTN_NULL) {
        delimiter =
            ptn_internal_expect_string_arg(runtime, "preg_quote", 2, "delimiter", args[1], line);
    }

    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    for (size_t i = 0; i < input.len; i++) {
        unsigned char byte = (unsigned char)input.data[i];
        if (byte == '\0') {
            ptn_string_buffer_append(&output, "\\000");
            continue;
        }
        if (
            ptn_preg_quote_needs_escape(byte) ||
            ptn_preg_quote_is_delimiter(byte, delimiter)
        ) {
            ptn_string_buffer_append_char(&output, '\\');
        }
        ptn_string_buffer_append_char(&output, (char)byte);
    }

    ptn_string_operand_free(input);
    ptn_string_operand_free(delimiter);
    return ptn_owned_string_len(output.data, output.len);
}

static void ptn_preg_append_capture_replacement(
    PtnStringBuffer *output,
    const char *subject,
    regmatch_t *matches,
    PtnPregCapture *captures,
    size_t capture_count,
    size_t capture_index
) {
    if (capture_index > capture_count) {
        return;
    }
    size_t match_index = capture_index == 0 ? 0 : captures[capture_index - 1].posix_index;
    if (matches[match_index].rm_so < 0 || matches[match_index].rm_eo < matches[match_index].rm_so) {
        return;
    }
    size_t start = (size_t)matches[match_index].rm_so;
    size_t len = (size_t)(matches[match_index].rm_eo - matches[match_index].rm_so);
    ptn_string_buffer_append_len(output, subject + start, len);
}

static size_t ptn_preg_decimal_reference_value(const char *data, size_t start, size_t end, size_t *value_out) {
    size_t value = 0;
    size_t i = start;
    while (i < end && isdigit((unsigned char)data[i]) && i - start < 2) {
        value = value * 10 + (size_t)(data[i] - '0');
        i++;
    }
    if (i == start) {
        return 0;
    }
    *value_out = value;
    return i - start;
}

static void ptn_preg_append_expanded_replacement(
    PtnStringBuffer *output,
    PtnStringOperand replacement,
    const char *subject,
    regmatch_t *matches,
    PtnPregCapture *captures,
    size_t capture_count
) {
    for (size_t i = 0; i < replacement.len; i++) {
        char byte = replacement.data[i];
        if (byte == '\\' && i + 1 < replacement.len && isdigit((unsigned char)replacement.data[i + 1])) {
            size_t capture_index = (size_t)(replacement.data[i + 1] - '0');
            ptn_preg_append_capture_replacement(output, subject, matches, captures, capture_count, capture_index);
            i++;
            continue;
        }
        if (byte == '$' && i + 1 < replacement.len) {
            if (replacement.data[i + 1] == '{') {
                size_t close = i + 2;
                while (close < replacement.len && replacement.data[close] != '}') {
                    close++;
                }
                size_t capture_index = 0;
                size_t consumed = ptn_preg_decimal_reference_value(replacement.data, i + 2, close, &capture_index);
                if (close < replacement.len && consumed == close - (i + 2)) {
                    ptn_preg_append_capture_replacement(output, subject, matches, captures, capture_count, capture_index);
                    i = close;
                    continue;
                }
            } else if (isdigit((unsigned char)replacement.data[i + 1])) {
                size_t capture_index = 0;
                size_t consumed = ptn_preg_decimal_reference_value(
                    replacement.data,
                    i + 1,
                    replacement.len,
                    &capture_index
                );
                if (consumed == 2 && capture_index > capture_count) {
                    consumed = 1;
                    capture_index = (size_t)(replacement.data[i + 1] - '0');
                }
                ptn_preg_append_capture_replacement(output, subject, matches, captures, capture_count, capture_index);
                i += consumed;
                continue;
            }
        }
        ptn_string_buffer_append_char(output, byte);
    }
}

static PtnStringOperand ptn_preg_apply_replacement_callback(
    PtnRuntime *runtime,
    PtnValue callback,
    const char *subject,
    size_t base_offset,
    regmatch_t *matches,
    PtnPregCapture *captures,
    size_t capture_count,
    int offset_capture,
    int unmatched_as_null,
    size_t line
) {
    PtnValue match_array = ptn_preg_match_array_value(
        subject,
        matches,
        captures,
        capture_count,
        base_offset,
        offset_capture,
        unmatched_as_null
    );
    ptn_value_debug_hide_ref(match_array);
    PtnValue callback_args[] = { match_array };
    PtnValue callback_result = ptn_internal_call_callback(runtime, callback, 1, callback_args, line);
    ptn_value_debug_unhide_ref(match_array);
    ptn_value_destroy(&match_array);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_value_destroy(&callback_result);
        return ptn_string_operand_borrowed("");
    }

    PtnStringOperand replacement = ptn_value_to_string_operand_with_runtime(runtime, callback_result, line);
    PtnStringOperand copied = ptn_string_operand_owned_len(
        ptn_duplicate_string_len(replacement.data, replacement.len),
        replacement.len
    );
    ptn_string_operand_free(replacement);
    ptn_value_destroy(&callback_result);
    return copied;
}

static PtnValue ptn_preg_replace_apply_to_string(
    PtnRuntime *runtime,
    const char *function_name,
    PtnStringOperand pattern,
    PtnStringOperand replacement,
    PtnValue callback,
    int use_callback,
    int offset_capture,
    int unmatched_as_null,
    PtnStringOperand subject,
    int64_t limit,
    int64_t *replacement_count,
    size_t line
) {
    regex_t regex;
    PtnPregCapture *captures = NULL;
    size_t capture_count = 0;
    size_t match_count = 0;
    if (!ptn_preg_compile_posix(
            runtime,
            function_name,
            pattern,
            &regex,
            &captures,
            &capture_count,
            &match_count,
            line
        )) {
        return ptn_null();
    }

#if defined(_WIN32)
    (void)regex;
    (void)match_count;
    ptn_preg_captures_free(captures, capture_count);
    return ptn_null();
#else
    regmatch_t *matches = calloc(match_count, sizeof(regmatch_t));
    if (matches == NULL) {
        regfree(&regex);
        ptn_preg_captures_free(captures, capture_count);
        ptn_abort_out_of_memory();
    }

    char *subject_c = ptn_duplicate_string_len(subject.data, subject.len);
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    size_t offset = 0;
    int64_t local_count = 0;

    while (offset <= subject.len && (limit < 0 || local_count < limit)) {
        int exec_result = regexec(&regex, subject_c + offset, match_count, matches, 0);
        if (exec_result != 0 || matches[0].rm_so < 0 || matches[0].rm_eo < matches[0].rm_so) {
            break;
        }

        size_t relative_start = (size_t)matches[0].rm_so;
        size_t relative_end = (size_t)matches[0].rm_eo;
        size_t start = offset + relative_start;
        size_t end = offset + relative_end;
        if (start > subject.len || end > subject.len || end < start) {
            break;
        }

        ptn_string_buffer_append_len(&output, subject.data + offset, start - offset);

        PtnStringOperand callback_replacement = ptn_string_operand_borrowed("");
        PtnStringOperand active_replacement = replacement;
        if (use_callback) {
            callback_replacement = ptn_preg_apply_replacement_callback(
                runtime,
                callback,
                subject_c,
                offset,
                matches,
                captures,
                capture_count,
                offset_capture,
                unmatched_as_null,
                line
            );
            if (runtime->exceptions->active_exception != NULL) {
                ptn_string_operand_free(callback_replacement);
                free(subject_c);
                free(matches);
                ptn_preg_captures_free(captures, capture_count);
                regfree(&regex);
                free(output.data);
                return ptn_null();
            }
            active_replacement = callback_replacement;
        }
        if (use_callback) {
            ptn_string_buffer_append_len(&output, active_replacement.data, active_replacement.len);
        } else {
            ptn_preg_append_expanded_replacement(
                &output,
                active_replacement,
                subject_c + offset,
                matches,
                captures,
                capture_count
            );
        }
        if (use_callback) {
            ptn_string_operand_free(callback_replacement);
        }

        local_count++;
        if (end == start) {
            if (end >= subject.len) {
                offset = end;
                break;
            }
            ptn_string_buffer_append_len(&output, subject.data + end, 1);
            offset = end + 1;
        } else {
            offset = end;
        }
    }

    ptn_string_buffer_append_len(&output, subject.data + offset, subject.len - offset);
    *replacement_count += local_count;
    free(subject_c);
    free(matches);
    ptn_preg_captures_free(captures, capture_count);
    regfree(&regex);
    return ptn_owned_string_len(output.data, output.len);
#endif
}

static PtnValue ptn_internal_preg_replace(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand pattern = ptn_internal_expect_string_arg(runtime, "preg_replace", 1, "pattern", args[0], line);
    PtnStringOperand replacement = ptn_value_to_string_operand_with_runtime(runtime, args[1], line);
    int64_t limit = argc >= 4 ? ptn_internal_expect_integer_arg(runtime, "preg_replace", 4, "limit", args[3], line) : -1;
    int64_t replacement_count = 0;

    PtnValue subject_value = ptn_value_deref(args[2]);
    PtnValue result;
    if (subject_value.type == PTN_ARRAY) {
        result = ptn_array_from_literal_entries(0, NULL);
        for (size_t i = 0; i < subject_value.as.array->len; i++) {
            PtnArrayEntry *entry = &subject_value.as.array->entries[i];
            PtnStringOperand subject = ptn_value_to_string_operand_with_runtime(runtime, entry->value, line);
            PtnValue replaced = ptn_preg_replace_apply_to_string(
                runtime,
                "preg_replace",
                pattern,
                replacement,
                ptn_null(),
                0,
                0,
                0,
                subject,
                limit,
                &replacement_count,
                line
            );
            ptn_string_operand_free(subject);
            if (runtime->exceptions->active_exception != NULL) {
                ptn_value_destroy(&result);
                result = ptn_null();
                break;
            }
            ptn_array_set_entry(result.as.array, ptn_array_key_clone(entry->key), replaced);
        }
    } else {
        PtnStringOperand subject = ptn_internal_expect_string_arg(runtime, "preg_replace", 3, "subject", args[2], line);
        result = ptn_preg_replace_apply_to_string(
            runtime,
            "preg_replace",
            pattern,
            replacement,
            ptn_null(),
            0,
            0,
            0,
            subject,
            limit,
            &replacement_count,
            line
        );
        ptn_string_operand_free(subject);
    }

    if (argc >= 5 && args[4].type == PTN_REFERENCE) {
        PtnValue count_value = ptn_int(replacement_count);
        ptn_reference_assign(runtime, args[4].as.reference, count_value);
    }
    ptn_string_operand_free(pattern);
    ptn_string_operand_free(replacement);
    return result;
}

static PtnValue ptn_internal_preg_filter(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand pattern = ptn_internal_expect_string_arg(runtime, "preg_filter", 1, "pattern", args[0], line);
    PtnStringOperand replacement = ptn_value_to_string_operand_with_runtime(runtime, args[1], line);
    int64_t limit = argc >= 4 ? ptn_internal_expect_integer_arg(runtime, "preg_filter", 4, "limit", args[3], line) : -1;
    int64_t replacement_count = 0;

    PtnValue subject_value = ptn_value_deref(args[2]);
    PtnValue result;
    if (subject_value.type == PTN_ARRAY) {
        result = ptn_array_from_literal_entries(0, NULL);
        for (size_t i = 0; i < subject_value.as.array->len; i++) {
            PtnArrayEntry *entry = &subject_value.as.array->entries[i];
            PtnStringOperand subject = ptn_value_to_string_operand_with_runtime(runtime, entry->value, line);
            int64_t before = replacement_count;
            PtnValue replaced = ptn_preg_replace_apply_to_string(
                runtime,
                "preg_filter",
                pattern,
                replacement,
                ptn_null(),
                0,
                0,
                0,
                subject,
                limit,
                &replacement_count,
                line
            );
            ptn_string_operand_free(subject);
            if (runtime->exceptions->active_exception != NULL) {
                ptn_value_destroy(&result);
                result = ptn_null();
                break;
            }
            if (replacement_count != before) {
                ptn_array_set_entry(result.as.array, ptn_array_key_clone(entry->key), replaced);
            } else {
                ptn_value_destroy(&replaced);
            }
        }
    } else {
        PtnStringOperand subject = ptn_internal_expect_string_arg(runtime, "preg_filter", 3, "subject", args[2], line);
        int64_t before = replacement_count;
        result = ptn_preg_replace_apply_to_string(
            runtime,
            "preg_filter",
            pattern,
            replacement,
            ptn_null(),
            0,
            0,
            0,
            subject,
            limit,
            &replacement_count,
            line
        );
        ptn_string_operand_free(subject);
        if (replacement_count == before && runtime->exceptions->active_exception == NULL) {
            ptn_value_destroy(&result);
            result = ptn_null();
        }
    }

    if (argc >= 5 && args[4].type == PTN_REFERENCE) {
        PtnValue count_value = ptn_int(replacement_count);
        ptn_reference_assign(runtime, args[4].as.reference, count_value);
    }
    ptn_string_operand_free(pattern);
    ptn_string_operand_free(replacement);
    return result;
}

static PtnValue ptn_internal_preg_replace_callback(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand pattern = ptn_internal_expect_string_arg(runtime, "preg_replace_callback", 1, "pattern", args[0], line);
    PtnValue callback = ptn_internal_expect_callback_arg(runtime, "preg_replace_callback", 2, "callback", args[1]);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(pattern);
        ptn_value_destroy(&callback);
        return ptn_null();
    }

    int64_t limit = argc >= 4 ? ptn_internal_expect_integer_arg(runtime, "preg_replace_callback", 4, "limit", args[3], line) : -1;
    int64_t flags = argc >= 6 ? ptn_internal_expect_integer_arg(runtime, "preg_replace_callback", 6, "flags", args[5], line) : 0;
    int offset_capture = (flags & 256) != 0;
    int unmatched_as_null = (flags & 512) != 0;
    int64_t replacement_count = 0;
    PtnStringOperand empty_replacement = ptn_string_operand_borrowed("");

    PtnValue subject_value = ptn_value_deref(args[2]);
    PtnValue result;
    if (subject_value.type == PTN_ARRAY) {
        result = ptn_array_from_literal_entries(0, NULL);
        for (size_t i = 0; i < subject_value.as.array->len; i++) {
            PtnArrayEntry *entry = &subject_value.as.array->entries[i];
            PtnStringOperand subject = ptn_value_to_string_operand_with_runtime(runtime, entry->value, line);
            PtnValue replaced = ptn_preg_replace_apply_to_string(
                runtime,
                "preg_replace_callback",
                pattern,
                empty_replacement,
                callback,
                1,
                offset_capture,
                unmatched_as_null,
                subject,
                limit,
                &replacement_count,
                line
            );
            ptn_string_operand_free(subject);
            if (runtime->exceptions->active_exception != NULL) {
                ptn_value_destroy(&result);
                result = ptn_null();
                break;
            }
            ptn_array_set_entry(result.as.array, ptn_array_key_clone(entry->key), replaced);
        }
    } else {
        PtnStringOperand subject =
            ptn_internal_expect_str_replace_arg(runtime, "preg_replace_callback", 3, "subject", args[2], line);
        result = ptn_preg_replace_apply_to_string(
            runtime,
            "preg_replace_callback",
            pattern,
            empty_replacement,
            callback,
            1,
            offset_capture,
            unmatched_as_null,
            subject,
            limit,
            &replacement_count,
            line
        );
        ptn_string_operand_free(subject);
    }

    if (argc >= 5 && args[4].type == PTN_REFERENCE) {
        PtnValue count_value = ptn_int(replacement_count);
        ptn_reference_assign(runtime, args[4].as.reference, count_value);
    }
    ptn_value_destroy(&callback);
    ptn_string_operand_free(pattern);
    return result;
}

static PtnValue ptn_preg_replace_callback_array_apply_subject(
    PtnRuntime *runtime,
    PtnStringOperand pattern,
    PtnValue callback,
    PtnValue subject_arg,
    int64_t limit,
    int offset_capture,
    int unmatched_as_null,
    int64_t *replacement_count,
    size_t line
) {
    PtnStringOperand empty_replacement = ptn_string_operand_borrowed("");
    PtnValue subject_value = ptn_value_deref(subject_arg);
    if (subject_value.type == PTN_ARRAY) {
        PtnValue result = ptn_array_from_literal_entries(0, NULL);
        for (size_t i = 0; i < subject_value.as.array->len; i++) {
            PtnArrayEntry *entry = &subject_value.as.array->entries[i];
            PtnStringOperand subject = ptn_value_to_string_operand_with_runtime(runtime, entry->value, line);
            PtnValue replaced = ptn_preg_replace_apply_to_string(
                runtime,
                "preg_replace_callback_array",
                pattern,
                empty_replacement,
                callback,
                1,
                offset_capture,
                unmatched_as_null,
                subject,
                limit,
                replacement_count,
                line
            );
            ptn_string_operand_free(subject);
            if (runtime->exceptions->active_exception != NULL) {
                ptn_value_destroy(&result);
                return ptn_null();
            }
            ptn_array_set_entry(result.as.array, ptn_array_key_clone(entry->key), replaced);
        }
        return result;
    }

    PtnStringOperand subject =
        ptn_internal_expect_str_replace_arg(runtime, "preg_replace_callback_array", 2, "subject", subject_arg, line);
    PtnValue result = ptn_preg_replace_apply_to_string(
        runtime,
        "preg_replace_callback_array",
        pattern,
        empty_replacement,
        callback,
        1,
        offset_capture,
        unmatched_as_null,
        subject,
        limit,
        replacement_count,
        line
    );
    ptn_string_operand_free(subject);
    return result;
}

static PtnValue ptn_internal_preg_replace_callback_array(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnArray *patterns = ptn_internal_expect_array_arg(runtime, "preg_replace_callback_array", 1, "pattern", args[0]);
    int64_t limit = argc >= 3 ? ptn_internal_expect_integer_arg(runtime, "preg_replace_callback_array", 3, "limit", args[2], line) : -1;
    int64_t flags = argc >= 5 ? ptn_internal_expect_integer_arg(runtime, "preg_replace_callback_array", 5, "flags", args[4], line) : 0;
    int offset_capture = (flags & 256) != 0;
    int unmatched_as_null = (flags & 512) != 0;
    int64_t replacement_count = 0;

    for (size_t i = 0; i < patterns->len; i++) {
        PtnArrayEntry *entry = &patterns->entries[i];
        if (entry->key.type != PTN_ARRAY_KEY_STRING) {
            ptn_throw_exception_at(
                runtime,
                "TypeError",
                "preg_replace_callback_array(): Argument #1 ($pattern) must contain only string patterns as keys",
                runtime->source_path,
                line
            );
            return ptn_null();
        }
        PtnValue callback = ptn_value_clone_deref(entry->value);
        if (!ptn_callable_is_valid(runtime, callback, 0)) {
            ptn_value_destroy(&callback);
            ptn_throw_exception_at(
                runtime,
                "TypeError",
                "preg_replace_callback_array(): Argument #1 ($pattern) must contain only valid callbacks",
                runtime->source_path,
                line
            );
            return ptn_null();
        }
        ptn_value_destroy(&callback);
    }

    PtnValue current = ptn_value_clone_deref(args[1]);
    for (size_t i = 0; i < patterns->len; i++) {
        PtnArrayEntry *entry = &patterns->entries[i];
        PtnValue pattern_value = ptn_array_key_value(entry->key);
        PtnStringOperand pattern =
            ptn_value_to_string_operand_with_runtime(runtime, pattern_value, line);
        PtnValue callback = ptn_value_clone_deref(entry->value);

        PtnValue next = ptn_preg_replace_callback_array_apply_subject(
            runtime,
            pattern,
            callback,
            current,
            limit,
            offset_capture,
            unmatched_as_null,
            &replacement_count,
            line
        );
        ptn_string_operand_free(pattern);
        ptn_value_destroy(&pattern_value);
        ptn_value_destroy(&callback);
        ptn_value_destroy(&current);
        current = next;
        if (runtime->exceptions->active_exception != NULL) {
            ptn_value_destroy(&current);
            return ptn_null();
        }
        if (current.type == PTN_NULL) {
            return current;
        }
    }

    if (argc >= 4 && args[3].type == PTN_REFERENCE) {
        PtnValue count_value = ptn_int(replacement_count);
        ptn_reference_assign(runtime, args[3].as.reference, count_value);
    }
    return current;
}

static int ptn_quotemeta_needs_escape(unsigned char byte) {
    switch (byte) {
        case '.':
        case '\\':
        case '+':
        case '*':
        case '?':
        case '[':
        case '^':
        case ']':
        case '(':
        case '$':
        case ')':
            return 1;
        default:
            return 0;
    }
}

static char *ptn_quotemeta_string(const char *input, size_t len, size_t *output_len_out) {
    size_t escape_count = 0;
    for (size_t i = 0; i < len; i++) {
        if (ptn_quotemeta_needs_escape((unsigned char)input[i])) {
            escape_count++;
        }
    }
    if (escape_count > SIZE_MAX - len - 1) {
        ptn_abort_out_of_memory();
    }

    char *output = malloc(len + escape_count + 1);
    if (output == NULL) {
        ptn_abort_out_of_memory();
    }

    size_t out = 0;
    for (size_t i = 0; i < len; i++) {
        unsigned char byte = (unsigned char)input[i];
        if (ptn_quotemeta_needs_escape(byte)) {
            output[out++] = '\\';
        }
        output[out++] = (char)byte;
    }
    output[out] = '\0';
    *output_len_out = out;
    return output;
}

static PtnValue ptn_internal_quotemeta(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "quotemeta", 1, "string", args[0], line);
    size_t output_len = 0;
    char *output = ptn_quotemeta_string(input.data, input.len, &output_len);
    ptn_string_operand_free(input);
    return ptn_owned_string_len(output, output_len);
}

static char *ptn_chunk_split_string(
    const char *input,
    size_t input_len,
    size_t chunk_len,
    const char *ending,
    size_t ending_len,
    size_t *output_len_out
) {
    if (input_len == 0) {
        if (ending_len == SIZE_MAX) {
            ptn_abort_out_of_memory();
        }
        char *output = malloc(ending_len + 1);
        if (output == NULL) {
            ptn_abort_out_of_memory();
        }
        memcpy(output, ending, ending_len);
        output[ending_len] = '\0';
        *output_len_out = ending_len;
        return output;
    }

    size_t chunk_count = ((input_len - 1) / chunk_len) + 1;
    if (chunk_count != 0 && ending_len > (SIZE_MAX - input_len) / chunk_count) {
        ptn_abort_out_of_memory();
    }
    size_t output_len = input_len + (chunk_count * ending_len);
    if (output_len == SIZE_MAX) {
        ptn_abort_out_of_memory();
    }

    char *output = malloc(output_len + 1);
    if (output == NULL) {
        ptn_abort_out_of_memory();
    }

    size_t input_offset = 0;
    size_t output_offset = 0;
    while (input_offset < input_len) {
        size_t remaining = input_len - input_offset;
        size_t copy_len = remaining < chunk_len ? remaining : chunk_len;
        memcpy(output + output_offset, input + input_offset, copy_len);
        input_offset += copy_len;
        output_offset += copy_len;
        memcpy(output + output_offset, ending, ending_len);
        output_offset += ending_len;
    }
    output[output_offset] = '\0';
    *output_len_out = output_offset;
    return output;
}

static PtnValue ptn_internal_chunk_split(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "chunk_split", 1, "string", args[0], line);
    int64_t chunk_len_value = argc >= 2
        ? ptn_internal_expect_integer_arg(runtime, "chunk_split", 2, "length", args[1], line)
        : 76;
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(input);
        return ptn_null();
    }
    if (chunk_len_value <= 0) {
        ptn_string_operand_free(input);
        ptn_throw_exception(
            runtime,
            "ValueError",
            "chunk_split(): Argument #2 ($length) must be greater than 0"
        );
    }
    PtnStringOperand ending;
    if (argc >= 3) {
        ending = ptn_internal_expect_string_arg(runtime, "chunk_split", 3, "separator", args[2], line);
    } else {
        ending.data = "\r\n";
        ending.owned = NULL;
        ending.len = 2;
    }
    size_t output_len = 0;
    char *output = ptn_chunk_split_string(
        input.data,
        input.len,
        (size_t)chunk_len_value,
        ending.data,
        ending.len,
        &output_len
    );
    ptn_string_operand_free(input);
    ptn_string_operand_free(ending);
    return ptn_owned_string_len(output, output_len);
}

typedef struct {
    char **items;
    size_t len;
    size_t capacity;
} PtnStripTagsAllowedSet;

static void ptn_strip_tags_allowed_set_init(PtnStripTagsAllowedSet *set) {
    set->items = NULL;
    set->len = 0;
    set->capacity = 0;
}

static void ptn_strip_tags_allowed_set_free(PtnStripTagsAllowedSet *set) {
    for (size_t i = 0; i < set->len; i++) {
        free(set->items[i]);
    }
    free(set->items);
    set->items = NULL;
    set->len = 0;
    set->capacity = 0;
}

static int ptn_strip_tags_allowed_set_contains(PtnStripTagsAllowedSet *set, const char *name, size_t name_len) {
    for (size_t i = 0; i < set->len; i++) {
        if (strlen(set->items[i]) == name_len && ptn_ascii_case_equal(set->items[i], name)) {
            return 1;
        }
    }
    return 0;
}

static void ptn_strip_tags_allowed_set_push(PtnStripTagsAllowedSet *set, const char *name, size_t name_len) {
    if (name_len == 0 || ptn_strip_tags_allowed_set_contains(set, name, name_len)) {
        return;
    }
    if (set->len == set->capacity) {
        size_t new_capacity = set->capacity == 0 ? 8 : set->capacity * 2;
        if (new_capacity < set->capacity || new_capacity > SIZE_MAX / sizeof(char *)) {
            ptn_abort_out_of_memory();
        }
        char **new_items = realloc(set->items, new_capacity * sizeof(char *));
        if (new_items == NULL) {
            ptn_abort_out_of_memory();
        }
        set->items = new_items;
        set->capacity = new_capacity;
    }
    char *copy = malloc(name_len + 1);
    if (copy == NULL) {
        ptn_abort_out_of_memory();
    }
    for (size_t i = 0; i < name_len; i++) {
        unsigned char c = (unsigned char)name[i];
        copy[i] = (char)tolower(c);
    }
    copy[name_len] = '\0';
    set->items[set->len++] = copy;
}

static int ptn_strip_tags_name_byte(unsigned char byte) {
    return (byte >= 'a' && byte <= 'z') ||
        (byte >= 'A' && byte <= 'Z') ||
        (byte >= '0' && byte <= '9');
}

static void ptn_strip_tags_collect_allowed_name(
    PtnStripTagsAllowedSet *set,
    const char *data,
    size_t len,
    size_t *offset
) {
    size_t i = *offset;
    while (i < len && data[i] != '<') {
        i++;
    }
    if (i >= len) {
        size_t name_start = *offset;
        while (name_start < len && !ptn_strip_tags_name_byte((unsigned char)data[name_start])) {
            name_start++;
        }
        size_t name_end = name_start;
        while (name_end < len && ptn_strip_tags_name_byte((unsigned char)data[name_end])) {
            name_end++;
        }
        if (name_end > name_start) {
            ptn_strip_tags_allowed_set_push(set, data + name_start, name_end - name_start);
        }
        *offset = i;
        return;
    }
    size_t tag_start = i;
    i++;
    while (i < len && data[i] == '<') {
        i++;
    }
    if (i < len && data[i] == '/') {
        i++;
    }
    while (i < len && !ptn_strip_tags_name_byte((unsigned char)data[i]) && data[i] != '>') {
        i++;
    }
    size_t name_start = i;
    while (i < len && ptn_strip_tags_name_byte((unsigned char)data[i])) {
        i++;
    }
    ptn_strip_tags_allowed_set_push(set, data + name_start, i - name_start);
    while (i < len && data[i] != '>') {
        i++;
    }
    *offset = tag_start + 1;
}

static int ptn_strip_tags_build_allowed_set_from_value(
    PtnRuntime *runtime,
    PtnStripTagsAllowedSet *set,
    PtnValue value,
    size_t line
) {
    value = ptn_value_deref(value);
    if (value.type == PTN_NULL) {
        return 1;
    }
    if (value.type == PTN_ARRAY) {
        for (size_t i = 0; i < value.as.array->len; i++) {
            PtnValue entry_value = ptn_value_deref(value.as.array->entries[i].value);
            if (entry_value.type != PTN_STRING) {
                continue;
            }
            size_t offset = 0;
            PtnString string = entry_value.as.string;
            while (offset < string.len) {
                ptn_strip_tags_collect_allowed_name(set, (const char *)string.data, string.len, &offset);
            }
        }
        return 1;
    }
    if (
        value.type == PTN_RESOURCE ||
        value.type == PTN_CLOSURE ||
        value.type == PTN_EXCEPTION
    ) {
        char message[192];
        int written = snprintf(
            message,
            sizeof(message),
            "strip_tags(): Argument #2 ($allowed_tags) must be of type array|string|null, %s given",
            ptn_internal_string_arg_type_name(value)
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "TypeError", message);
        return 0;
    }
    PtnStringOperand allowed = ptn_value_to_string_operand_with_runtime(runtime, value, line);
    size_t offset = 0;
    while (offset < allowed.len) {
        ptn_strip_tags_collect_allowed_name(set, allowed.data, allowed.len, &offset);
    }
    ptn_string_operand_free(allowed);
    return 1;
}

static size_t ptn_strip_tags_find_tag_end(const char *input, size_t len, size_t start) {
    unsigned char quote = 0;
    size_t nested = 0;
    for (size_t i = start; i < len; i++) {
        unsigned char byte = (unsigned char)input[i];
        if (quote != 0) {
            if (byte == quote) {
                quote = 0;
            }
            continue;
        }
        if (byte == '"' || byte == '\'') {
            quote = byte;
            continue;
        }
        if (byte == '<') {
            nested++;
            continue;
        }
        if (byte == '>') {
            if (nested > 0) {
                nested--;
                continue;
            }
            return i;
        }
    }
    return len;
}

static size_t ptn_strip_tags_find_php_tag_end(const char *input, size_t len, size_t start) {
    unsigned char quote = 0;
    for (size_t i = start; i < len; i++) {
        unsigned char byte = (unsigned char)input[i];
        int escaped_quote = i > start && input[i - 1] == '\\';
        if (quote != 0) {
            if (byte == quote && !escaped_quote) {
                quote = 0;
            }
            continue;
        }
        if ((byte == '"' || byte == '\'') && !escaped_quote) {
            quote = byte;
            continue;
        }
        if (input[i] == '?' && i + 1 < len && input[i + 1] == '>') {
            return i;
        }
    }
    return len;
}

static int ptn_strip_tags_extract_tag_name(
    const char *input,
    size_t len,
    size_t tag_start,
    char *name,
    size_t name_capacity,
    size_t *name_len_out
) {
    size_t i = tag_start + 1;
    while (i < len && input[i] == '<') {
        i++;
    }
    if (i < len && input[i] == '/') {
        i++;
    }
    if (i >= len || !ptn_strip_tags_name_byte((unsigned char)input[i])) {
        return 0;
    }
    size_t name_len = 0;
    while (i < len && ptn_strip_tags_name_byte((unsigned char)input[i])) {
        if (name_len + 1 >= name_capacity) {
            return 0;
        }
        name[name_len++] = (char)tolower((unsigned char)input[i]);
        i++;
    }
    if (i < len && input[i] == '/') {
        if (i + 1 < len && input[i + 1] != '>' && !isspace((unsigned char)input[i + 1])) {
            return 0;
        }
    } else if (i < len && input[i] != '>' && !isspace((unsigned char)input[i])) {
        return 0;
    }
    name[name_len] = '\0';
    *name_len_out = name_len;
    return name_len != 0;
}

static int ptn_strip_tags_probable_tag_start(const char *input, size_t len, size_t tag_start) {
    size_t i = tag_start + 1;
    while (i < len && input[i] == '<') {
        i++;
    }
    if (i < len && input[i] == '/') {
        i++;
    }
    if (i >= len) {
        return 0;
    }
    if (isspace((unsigned char)input[i])) {
        return 0;
    }
    return 1;
}

static size_t ptn_strip_tags_preserved_tag_start(const char *input, size_t tag_start) {
    size_t start = tag_start;
    while (input[start + 1] == '<') {
        start++;
    }
    return start;
}

static char *ptn_strip_tags_string(
    const char *input,
    size_t len,
    PtnStripTagsAllowedSet *allowed,
    size_t *output_len_out
) {
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);

    size_t input_offset = 0;
    while (input_offset < len) {
        if (input[input_offset] == '<') {
            if (input_offset + 1 < len && input[input_offset + 1] == '?') {
                size_t tag_end = ptn_strip_tags_find_php_tag_end(input, len, input_offset + 2);
                if (tag_end < len) {
                    input_offset = tag_end + 2;
                    continue;
                }
                tag_end = ptn_strip_tags_find_tag_end(input, len, input_offset + 1);
                input_offset = tag_end < len ? tag_end + 1 : len;
                continue;
            } else if (input_offset + 1 < len && input[input_offset + 1] == '%') {
                size_t tag_end = input_offset + 2;
                while (tag_end + 1 < len && !(input[tag_end] == '%' && input[tag_end + 1] == '>')) {
                    tag_end++;
                }
                if (tag_end + 1 < len) {
                    input_offset = tag_end + 2;
                    continue;
                }
            } else if (input_offset + 3 < len && memcmp(input + input_offset, "<!--", 4) == 0) {
                size_t tag_end = input_offset + 4;
                while (tag_end + 2 < len && memcmp(input + tag_end, "-->", 3) != 0) {
                    tag_end++;
                }
                if (tag_end + 2 < len) {
                    input_offset = tag_end + 3;
                    continue;
                }
            } else {
                size_t tag_end = ptn_strip_tags_find_tag_end(input, len, input_offset + 1);
                if (tag_end < len) {
                    if (!ptn_strip_tags_probable_tag_start(input, len, input_offset)) {
                        ptn_string_buffer_append_char(&output, input[input_offset++]);
                        continue;
                    }
                    char name[128];
                    size_t name_len = 0;
                    int allowed_tag = ptn_strip_tags_extract_tag_name(
                        input,
                        len,
                        input_offset,
                        name,
                        sizeof(name),
                        &name_len
                    ) && ptn_strip_tags_allowed_set_contains(allowed, name, name_len);
                    if (allowed_tag) {
                        size_t preserved_start = ptn_strip_tags_preserved_tag_start(input, input_offset);
                        size_t preserved_end = tag_end;
                        size_t extra_open_markers = preserved_start - input_offset;
                        while (extra_open_markers > 0 && preserved_end > preserved_start && input[preserved_end] == '>') {
                            preserved_end--;
                            extra_open_markers--;
                        }
                        ptn_string_buffer_append_len(&output, input + preserved_start, preserved_end - preserved_start + 1);
                        if (tag_end + 1 < len && input[tag_end + 1] == '>' && preserved_start != input_offset) {
                            tag_end++;
                        }
                    }
                    input_offset = tag_end + 1;
                    continue;
                }
            }
        }
        if (input[input_offset] == '\0') {
            input_offset++;
            continue;
        }
        ptn_string_buffer_append_char(&output, input[input_offset++]);
    }
    *output_len_out = output.len;
    return output.data == NULL ? ptn_duplicate_string("") : output.data;
}

static PtnValue ptn_internal_strip_tags(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "strip_tags", 1, "string", args[0], line);
    PtnStripTagsAllowedSet allowed;
    ptn_strip_tags_allowed_set_init(&allowed);
    if (argc >= 2 && !ptn_strip_tags_build_allowed_set_from_value(runtime, &allowed, args[1], line)) {
        ptn_strip_tags_allowed_set_free(&allowed);
        ptn_string_operand_free(input);
        return ptn_null();
    }
    size_t output_len = 0;
    char *output = ptn_strip_tags_string(input.data, input.len, &allowed, &output_len);
    ptn_strip_tags_allowed_set_free(&allowed);
    ptn_string_operand_free(input);
    return ptn_owned_string_len(output, output_len);
}

static uint32_t ptn_rotate_left32(uint32_t value, uint32_t amount) {
    return (value << amount) | (value >> (32 - amount));
}

static char *ptn_digest_hex_string(const unsigned char *digest, size_t digest_len) {
    static const char hex_digits[] = "0123456789abcdef";
    if (digest_len > (SIZE_MAX - 1) / 2) {
        ptn_abort_out_of_memory();
    }
    char *hex = malloc((digest_len * 2) + 1);
    if (hex == NULL) {
        ptn_abort_out_of_memory();
    }
    for (size_t i = 0; i < digest_len; i++) {
        hex[i * 2] = hex_digits[digest[i] >> 4];
        hex[i * 2 + 1] = hex_digits[digest[i] & 0x0f];
    }
    hex[digest_len * 2] = '\0';
    return hex;
}

static char *ptn_digest_raw_string(const unsigned char *digest, size_t digest_len) {
    char *raw = malloc(digest_len + 1);
    if (raw == NULL) {
        ptn_abort_out_of_memory();
    }
    memcpy(raw, digest, digest_len);
    raw[digest_len] = '\0';
    return raw;
}

static PtnValue ptn_digest_value(const unsigned char *digest, size_t digest_len, int raw_output) {
    if (raw_output) {
        return ptn_owned_string_len(ptn_digest_raw_string(digest, digest_len), digest_len);
    }
    return ptn_owned_string_len(ptn_digest_hex_string(digest, digest_len), digest_len * 2);
}

static void ptn_md5_digest_bytes(const unsigned char *input, size_t input_len, unsigned char digest[16]) {
    static const uint32_t shifts[64] = {
        7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22,
        5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20,
        4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23,
        6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21
    };
    static const uint32_t constants[64] = {
        0xd76aa478, 0xe8c7b756, 0x242070db, 0xc1bdceee,
        0xf57c0faf, 0x4787c62a, 0xa8304613, 0xfd469501,
        0x698098d8, 0x8b44f7af, 0xffff5bb1, 0x895cd7be,
        0x6b901122, 0xfd987193, 0xa679438e, 0x49b40821,
        0xf61e2562, 0xc040b340, 0x265e5a51, 0xe9b6c7aa,
        0xd62f105d, 0x02441453, 0xd8a1e681, 0xe7d3fbc8,
        0x21e1cde6, 0xc33707d6, 0xf4d50d87, 0x455a14ed,
        0xa9e3e905, 0xfcefa3f8, 0x676f02d9, 0x8d2a4c8a,
        0xfffa3942, 0x8771f681, 0x6d9d6122, 0xfde5380c,
        0xa4beea44, 0x4bdecfa9, 0xf6bb4b60, 0xbebfbc70,
        0x289b7ec6, 0xeaa127fa, 0xd4ef3085, 0x04881d05,
        0xd9d4d039, 0xe6db99e5, 0x1fa27cf8, 0xc4ac5665,
        0xf4292244, 0x432aff97, 0xab9423a7, 0xfc93a039,
        0x655b59c3, 0x8f0ccc92, 0xffeff47d, 0x85845dd1,
        0x6fa87e4f, 0xfe2ce6e0, 0xa3014314, 0x4e0811a1,
        0xf7537e82, 0xbd3af235, 0x2ad7d2bb, 0xeb86d391
    };

    size_t padded_len = input_len + 1;
    while ((padded_len % 64) != 56) {
        padded_len++;
    }
    if (padded_len < input_len || padded_len > SIZE_MAX - 8) {
        ptn_abort_out_of_memory();
    }

    unsigned char *message = calloc(padded_len + 8, 1);
    if (message == NULL) {
        ptn_abort_out_of_memory();
    }
    if (input_len != 0) {
        memcpy(message, input, input_len);
    }
    message[input_len] = 0x80;

    uint64_t bit_len = (uint64_t)input_len * 8;
    for (size_t i = 0; i < 8; i++) {
        message[padded_len + i] = (unsigned char)(bit_len >> (8 * i));
    }

    uint32_t h0 = 0x67452301;
    uint32_t h1 = 0xefcdab89;
    uint32_t h2 = 0x98badcfe;
    uint32_t h3 = 0x10325476;

    for (size_t offset = 0; offset < padded_len; offset += 64) {
        uint32_t words[16];
        for (size_t i = 0; i < 16; i++) {
            size_t base = offset + i * 4;
            words[i] = (uint32_t)message[base]
                | ((uint32_t)message[base + 1] << 8)
                | ((uint32_t)message[base + 2] << 16)
                | ((uint32_t)message[base + 3] << 24);
        }

        uint32_t a = h0;
        uint32_t b = h1;
        uint32_t c = h2;
        uint32_t d = h3;

        for (uint32_t i = 0; i < 64; i++) {
            uint32_t f;
            uint32_t g;
            if (i < 16) {
                f = (b & c) | ((~b) & d);
                g = i;
            } else if (i < 32) {
                f = (d & b) | ((~d) & c);
                g = (5 * i + 1) % 16;
            } else if (i < 48) {
                f = b ^ c ^ d;
                g = (3 * i + 5) % 16;
            } else {
                f = c ^ (b | (~d));
                g = (7 * i) % 16;
            }

            uint32_t next = d;
            d = c;
            c = b;
            b = b + ptn_rotate_left32(a + f + constants[i] + words[g], shifts[i]);
            a = next;
        }

        h0 += a;
        h1 += b;
        h2 += c;
        h3 += d;
    }

    free(message);

    uint32_t words[4] = { h0, h1, h2, h3 };
    for (size_t i = 0; i < 4; i++) {
        digest[i * 4] = (unsigned char)words[i];
        digest[i * 4 + 1] = (unsigned char)(words[i] >> 8);
        digest[i * 4 + 2] = (unsigned char)(words[i] >> 16);
        digest[i * 4 + 3] = (unsigned char)(words[i] >> 24);
    }
}

static PtnValue ptn_internal_md5(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "md5", 1, "string", args[0], line);
    unsigned char digest[16];
    ptn_md5_digest_bytes((const unsigned char *)input.data, input.len, digest);
    int raw_output = argc >= 2 && ptn_is_truthy(args[1]);
    ptn_string_operand_free(input);
    return ptn_digest_value(digest, sizeof(digest), raw_output);
}

static uint32_t ptn_crc32_bytes(const unsigned char *input, size_t input_len) {
    uint32_t crc = UINT32_C(0xffffffff);
    for (size_t i = 0; i < input_len; i++) {
        crc ^= (uint32_t)input[i];
        for (size_t bit = 0; bit < 8; bit++) {
            uint32_t mask = -(crc & UINT32_C(1));
            crc = (crc >> 1) ^ (UINT32_C(0xedb88320) & mask);
        }
    }
    return crc ^ UINT32_C(0xffffffff);
}

static PtnValue ptn_internal_crc32(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "crc32", 1, "string", args[0], line);
    uint32_t checksum = ptn_crc32_bytes((const unsigned char *)input.data, input.len);
    ptn_string_operand_free(input);
    return ptn_int((int64_t)checksum);
}

static PtnValue ptn_internal_crypt(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand string = ptn_internal_expect_string_arg(runtime, "crypt", 1, "string", args[0], line);
    PtnStringOperand salt_input = ptn_internal_expect_string_arg(runtime, "crypt", 2, "salt", args[1], line);

    char *password = ptn_duplicate_string_len(string.data, string.len);
    char salt[PTN_CRYPT_MAX_SALT_LEN + 1];
    memset(salt, '$', sizeof(salt));
    salt[PTN_CRYPT_MAX_SALT_LEN] = '\0';
    size_t salt_len = salt_input.len < PTN_CRYPT_MAX_SALT_LEN
        ? salt_input.len
        : PTN_CRYPT_MAX_SALT_LEN;
    if (salt_len != 0) {
        memcpy(salt, salt_input.data, salt_len);
    }
    salt[salt_len] = '\0';

    char output[PTN_CRYPT_OUTPUT_SIZE];
    memset(output, 0, sizeof(output));
    char *crypted = ptn_php_crypt_port(password, salt, output, sizeof(output));
    PtnValue result = ptn_null();
    if (crypted == NULL) {
        result = ptn_string(salt[0] == '*' && salt[1] == '0' ? "*1" : "*0");
    } else {
        result = ptn_owned_string(ptn_duplicate_string(crypted));
    }

    free(password);
    ptn_string_operand_free(string);
    ptn_string_operand_free(salt_input);
    return result;
}

typedef enum {
    PTN_PASSWORD_ALGO_UNKNOWN = 0,
    PTN_PASSWORD_ALGO_BCRYPT = 1
} PtnPasswordAlgorithm;

static void ptn_password_throw_algo_type_error(
    PtnRuntime *runtime,
    const char *function_name,
    size_t position,
    const char *argument_name,
    PtnValue value
) {
    value = ptn_value_deref(value);
    const char *given = value.type == PTN_OBJECT
        ? value.as.object->class_name
        : ptn_offset_container_type_name(value);
    char message[192];
    int written = snprintf(
        message,
        sizeof(message),
        "%s(): Argument #%zu ($%s) must be of type string|int|null, %s given",
        function_name,
        position,
        argument_name,
        given
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "TypeError", message);
}

static int ptn_password_string_algo(PtnStringOperand algo) {
    return algo.len == 2 && memcmp(algo.data, PTN_PASSWORD_BCRYPT, 2) == 0
        ? PTN_PASSWORD_ALGO_BCRYPT
        : PTN_PASSWORD_ALGO_UNKNOWN;
}

static int ptn_password_resolve_algo(
    PtnRuntime *runtime,
    const char *function_name,
    size_t position,
    const char *argument_name,
    PtnValue value,
    size_t line,
    PtnPasswordAlgorithm *out
) {
    value = ptn_value_deref(value);
    switch (value.type) {
        case PTN_NULL:
            *out = PTN_PASSWORD_ALGO_BCRYPT;
            return 1;
        case PTN_BOOL:
            *out = value.as.boolean ? PTN_PASSWORD_ALGO_BCRYPT : PTN_PASSWORD_ALGO_BCRYPT;
            return 1;
        case PTN_INT:
            *out = (value.as.integer == 0 || value.as.integer == PTN_PASSWORD_LEGACY_BCRYPT)
                ? PTN_PASSWORD_ALGO_BCRYPT
                : PTN_PASSWORD_ALGO_UNKNOWN;
            return 1;
        case PTN_FLOAT: {
            int64_t integer = ptn_value_to_integer(value);
            *out = (integer == 0 || integer == PTN_PASSWORD_LEGACY_BCRYPT)
                ? PTN_PASSWORD_ALGO_BCRYPT
                : PTN_PASSWORD_ALGO_UNKNOWN;
            return 1;
        }
        case PTN_STRING: {
            PtnStringOperand algo = ptn_string_operand_borrowed_len(
                (const char *)value.as.string.data,
                value.as.string.len
            );
            *out = (PtnPasswordAlgorithm)ptn_password_string_algo(algo);
            return 1;
        }
        case PTN_OBJECT: {
            PtnStringOperand algo;
            if (ptn_try_object_to_string_operand(runtime, value, line, &algo)) {
                *out = (PtnPasswordAlgorithm)ptn_password_string_algo(algo);
                ptn_string_operand_free(algo);
                return 1;
            }
            break;
        }
        case PTN_ARRAY:
        case PTN_CLOSURE:
        case PTN_EXCEPTION:
        case PTN_RESOURCE:
        case PTN_REFERENCE:
            break;
    }
    ptn_password_throw_algo_type_error(runtime, function_name, position, argument_name, value);
    return 0;
}

static PtnArrayEntry *ptn_password_options_entry(PtnArray *options, const char *name) {
    if (options == NULL) {
        return NULL;
    }
    PtnArrayKey key = ptn_array_string_key(name);
    PtnArrayEntry *entry = ptn_array_entry_for_key(options, key);
    ptn_array_key_free(key);
    return entry;
}

static int ptn_password_bcrypt_cost(
    PtnRuntime *runtime,
    PtnArray *options,
    int validate,
    int *out
) {
    int64_t cost = PTN_PASSWORD_BCRYPT_DEFAULT_COST;
    PtnArrayEntry *entry = ptn_password_options_entry(options, "cost");
    if (entry != NULL) {
        cost = ptn_value_to_integer(entry->value);
    }
    if (validate && (cost < 4 || cost > 31)) {
        char message[96];
        int written = snprintf(
            message,
            sizeof(message),
            "Invalid bcrypt cost parameter specified: %lld",
            (long long)cost
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "ValueError", message);
        return 0;
    }
    *out = (int)cost;
    return 1;
}

static void ptn_password_emit_salt_ignored_warning(PtnRuntime *runtime, PtnArray *options, size_t line) {
    if (ptn_password_options_entry(options, "salt") != NULL) {
        ptn_emit_warning(
            &runtime->diagnostics,
            "password_hash(): The \"salt\" option has been ignored, since providing a custom salt is no longer supported",
            line
        );
    }
}

static void ptn_password_bcrypt_salt(char salt[30], int cost) {
    static const char alphabet[] =
        "./ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    int written = snprintf(salt, 8, "$2y$%02d$", cost);
    if (written != 7) {
        ptn_abort_out_of_memory();
    }
    for (size_t i = 0; i < 22; i++) {
        salt[7 + i] = alphabet[(unsigned int)rand() & 0x3f];
    }
    salt[29] = '\0';
}

static PtnValue ptn_password_bcrypt_hash_value(PtnStringOperand password, int cost) {
    char *password_copy = ptn_duplicate_string_len(password.data, password.len);
    char salt[30];
    ptn_password_bcrypt_salt(salt, cost);

    char output[PTN_CRYPT_OUTPUT_SIZE];
    memset(output, 0, sizeof(output));
    char *crypted = ptn_php_crypt_port(password_copy, salt, output, sizeof(output));
    free(password_copy);
    if (crypted == NULL || crypted[0] == '*') {
        return ptn_bool(0);
    }
    return ptn_owned_string(ptn_duplicate_string(crypted));
}

static int ptn_password_bcrypt_info(const char *hash, size_t hash_len, int *cost_out) {
    if (hash_len != 60) {
        return 0;
    }
    if (
        hash[0] != '$' ||
        hash[1] != '2' ||
        !(hash[2] == 'a' || hash[2] == 'b' || hash[2] == 'y') ||
        hash[3] != '$' ||
        !isdigit((unsigned char)hash[4]) ||
        !isdigit((unsigned char)hash[5]) ||
        hash[6] != '$'
    ) {
        return 0;
    }
    int cost = (hash[4] - '0') * 10 + (hash[5] - '0');
    if (cost < 4 || cost > 31) {
        return 0;
    }
    *cost_out = cost;
    return 1;
}

static PtnValue ptn_password_info_array(int found, int cost) {
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    PtnValue options = ptn_array_from_literal_entries(0, NULL);
    if (found) {
        ptn_array_set_entry(options.as.array, ptn_array_string_key("cost"), ptn_int(cost));
    }
    ptn_array_set_entry(
        result.as.array,
        ptn_array_string_key("algo"),
        found ? ptn_string(PTN_PASSWORD_BCRYPT) : ptn_null()
    );
    ptn_array_set_entry(
        result.as.array,
        ptn_array_string_key("algoName"),
        ptn_string(found ? "bcrypt" : "unknown")
    );
    ptn_array_set_entry(result.as.array, ptn_array_string_key("options"), options);
    return result;
}

static PtnValue ptn_internal_password_get_info(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand hash = ptn_internal_expect_string_arg(runtime, "password_get_info", 1, "hash", args[0], line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(hash);
        return ptn_null();
    }
    int cost = 0;
    int found = ptn_password_bcrypt_info(hash.data, hash.len, &cost);
    ptn_string_operand_free(hash);
    return ptn_password_info_array(found, cost);
}

static PtnValue ptn_internal_password_hash(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand password = ptn_internal_expect_string_arg(runtime, "password_hash", 1, "password", args[0], line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(password);
        return ptn_null();
    }
    PtnPasswordAlgorithm algorithm = PTN_PASSWORD_ALGO_UNKNOWN;
    if (!ptn_password_resolve_algo(runtime, "password_hash", 2, "algo", args[1], line, &algorithm)) {
        ptn_string_operand_free(password);
        return ptn_null();
    }
    PtnArray *options = NULL;
    if (argc >= 3) {
        options = ptn_internal_expect_array_arg(runtime, "password_hash", 3, "options", args[2]);
        if (options == NULL || runtime->exceptions->active_exception != NULL) {
            ptn_string_operand_free(password);
            return ptn_null();
        }
    }
    if (algorithm != PTN_PASSWORD_ALGO_BCRYPT) {
        ptn_string_operand_free(password);
        ptn_throw_exception_at(
            runtime,
            "ValueError",
            "password_hash(): Argument #2 ($algo) must be a valid password hashing algorithm",
            runtime->source_path,
            line
        );
        return ptn_null();
    }
    int cost = PTN_PASSWORD_BCRYPT_DEFAULT_COST;
    if (!ptn_password_bcrypt_cost(runtime, options, 1, &cost)) {
        ptn_string_operand_free(password);
        return ptn_null();
    }
    if (memchr(password.data, '\0', password.len) != NULL) {
        ptn_string_operand_free(password);
        ptn_throw_exception(runtime, "ValueError", "Bcrypt password must not contain null character");
        return ptn_null();
    }
    ptn_password_emit_salt_ignored_warning(runtime, options, line);
    PtnValue result = ptn_password_bcrypt_hash_value(password, cost);
    ptn_string_operand_free(password);
    return result;
}

static PtnValue ptn_internal_password_needs_rehash(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand hash = ptn_internal_expect_string_arg(runtime, "password_needs_rehash", 1, "hash", args[0], line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(hash);
        return ptn_null();
    }
    PtnPasswordAlgorithm algorithm = PTN_PASSWORD_ALGO_UNKNOWN;
    if (!ptn_password_resolve_algo(runtime, "password_needs_rehash", 2, "algo", args[1], line, &algorithm)) {
        ptn_string_operand_free(hash);
        return ptn_null();
    }
    PtnArray *options = NULL;
    if (argc >= 3) {
        options = ptn_internal_expect_array_arg(runtime, "password_needs_rehash", 3, "options", args[2]);
        if (options == NULL || runtime->exceptions->active_exception != NULL) {
            ptn_string_operand_free(hash);
            return ptn_null();
        }
    }
    if (algorithm != PTN_PASSWORD_ALGO_BCRYPT) {
        ptn_string_operand_free(hash);
        return ptn_bool(0);
    }
    int existing_cost = 0;
    int desired_cost = PTN_PASSWORD_BCRYPT_DEFAULT_COST;
    int found = ptn_password_bcrypt_info(hash.data, hash.len, &existing_cost);
    ptn_string_operand_free(hash);
    if (!found) {
        return ptn_bool(1);
    }
    if (!ptn_password_bcrypt_cost(runtime, options, 0, &desired_cost)) {
        return ptn_null();
    }
    return ptn_bool(existing_cost != desired_cost);
}

static PtnValue ptn_internal_password_verify(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand password = ptn_internal_expect_string_arg(runtime, "password_verify", 1, "password", args[0], line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(password);
        return ptn_null();
    }
    PtnStringOperand hash = ptn_internal_expect_string_arg(runtime, "password_verify", 2, "hash", args[1], line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(password);
        ptn_string_operand_free(hash);
        return ptn_null();
    }

    char *password_copy = ptn_duplicate_string_len(password.data, password.len);
    char *salt = ptn_duplicate_string_len(hash.data, hash.len);
    char output[PTN_CRYPT_OUTPUT_SIZE];
    memset(output, 0, sizeof(output));
    char *crypted = ptn_php_crypt_port(password_copy, salt, output, sizeof(output));
    int ok = crypted != NULL &&
        strlen(crypted) == hash.len &&
        memcmp(crypted, hash.data, hash.len) == 0;
    free(password_copy);
    free(salt);
    ptn_string_operand_free(password);
    ptn_string_operand_free(hash);
    return ptn_bool(ok);
}

static void ptn_sha1_digest_bytes(const unsigned char *input, size_t input_len, unsigned char digest[20]) {
    size_t padded_len = input_len + 1;
    while ((padded_len % 64) != 56) {
        padded_len++;
    }
    if (padded_len < input_len || padded_len > SIZE_MAX - 8) {
        ptn_abort_out_of_memory();
    }

    unsigned char *message = calloc(padded_len + 8, 1);
    if (message == NULL) {
        ptn_abort_out_of_memory();
    }
    if (input_len != 0) {
        memcpy(message, input, input_len);
    }
    message[input_len] = 0x80;

    uint64_t bit_len = (uint64_t)input_len * 8;
    for (size_t i = 0; i < 8; i++) {
        message[padded_len + 7 - i] = (unsigned char)(bit_len >> (8 * i));
    }

    uint32_t h0 = 0x67452301;
    uint32_t h1 = 0xefcdab89;
    uint32_t h2 = 0x98badcfe;
    uint32_t h3 = 0x10325476;
    uint32_t h4 = 0xc3d2e1f0;

    for (size_t offset = 0; offset < padded_len; offset += 64) {
        uint32_t words[80];
        for (size_t i = 0; i < 16; i++) {
            size_t base = offset + i * 4;
            words[i] = ((uint32_t)message[base] << 24)
                | ((uint32_t)message[base + 1] << 16)
                | ((uint32_t)message[base + 2] << 8)
                | (uint32_t)message[base + 3];
        }
        for (size_t i = 16; i < 80; i++) {
            words[i] = ptn_rotate_left32(words[i - 3] ^ words[i - 8] ^ words[i - 14] ^ words[i - 16], 1);
        }

        uint32_t a = h0;
        uint32_t b = h1;
        uint32_t c = h2;
        uint32_t d = h3;
        uint32_t e = h4;

        for (size_t i = 0; i < 80; i++) {
            uint32_t f;
            uint32_t k;
            if (i < 20) {
                f = (b & c) | ((~b) & d);
                k = 0x5a827999;
            } else if (i < 40) {
                f = b ^ c ^ d;
                k = 0x6ed9eba1;
            } else if (i < 60) {
                f = (b & c) | (b & d) | (c & d);
                k = 0x8f1bbcdc;
            } else {
                f = b ^ c ^ d;
                k = 0xca62c1d6;
            }

            uint32_t temp = ptn_rotate_left32(a, 5) + f + e + k + words[i];
            e = d;
            d = c;
            c = ptn_rotate_left32(b, 30);
            b = a;
            a = temp;
        }

        h0 += a;
        h1 += b;
        h2 += c;
        h3 += d;
        h4 += e;
    }

    free(message);

    uint32_t words[5] = { h0, h1, h2, h3, h4 };
    for (size_t i = 0; i < 5; i++) {
        digest[i * 4] = (unsigned char)(words[i] >> 24);
        digest[i * 4 + 1] = (unsigned char)(words[i] >> 16);
        digest[i * 4 + 2] = (unsigned char)(words[i] >> 8);
        digest[i * 4 + 3] = (unsigned char)words[i];
    }
}

static PtnValue ptn_internal_sha1(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "sha1", 1, "string", args[0], line);
    unsigned char digest[20];
    ptn_sha1_digest_bytes((const unsigned char *)input.data, input.len, digest);
    int raw_output = argc >= 2 && ptn_is_truthy(args[1]);
    ptn_string_operand_free(input);
    return ptn_digest_value(digest, sizeof(digest), raw_output);
}

static PtnValue ptn_internal_pow(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    return ptn_power(runtime, args[0], args[1], line);
}

static int ptn_path_is_separator(char byte);

static int ptn_path_contains_scheme_separator(const char *path, size_t len) {
    if (len < 3) {
        return 0;
    }
    for (size_t i = 0; i + 2 < len; i++) {
        if (path[i] == ':' && path[i + 1] == '/' && path[i + 2] == '/') {
            return 1;
        }
    }
    return 0;
}

static int ptn_normalized_previous_segment_is_parent(const char *path, size_t len) {
    if (len < 2) {
        return 0;
    }
    size_t end = len;
    if (end > 0 && path[end - 1] == '/') {
        end--;
    }
    size_t start = end;
    while (start > 0 && path[start - 1] != '/') {
        start--;
    }
    return end - start == 2 && path[start] == '.' && path[start + 1] == '.';
}

static char *ptn_normalize_filesystem_path(const char *path, size_t len) {
    if (len == 0) {
        return ptn_duplicate_string_len(path, len);
    }

    const char *source = path;
    size_t source_len = len;
    if (source_len >= 8 && strncmp(source, "file:///", 8) == 0) {
        source += 7;
        source_len -= 7;
    } else if (ptn_path_contains_scheme_separator(source, source_len)) {
        return ptn_duplicate_string_len(path, len);
    }

    char *normalized = malloc(source_len + 2);
    if (normalized == NULL) {
        ptn_abort_out_of_memory();
    }

    int absolute = source_len > 0 && ptn_path_is_separator(source[0]);
    size_t out_len = 0;
    if (absolute) {
        normalized[out_len++] = '/';
        while (source_len > 0 && ptn_path_is_separator(*source)) {
            source++;
            source_len--;
        }
    }

    while (source_len > 0) {
        while (source_len > 0 && ptn_path_is_separator(*source)) {
            source++;
            source_len--;
        }
        if (source_len == 0) {
            break;
        }

        const char *segment = source;
        size_t segment_len = 0;
        while (segment_len < source_len && !ptn_path_is_separator(segment[segment_len])) {
            segment_len++;
        }

        if (segment_len == 1 && segment[0] == '.') {
            source += segment_len;
            source_len -= segment_len;
            continue;
        }

        if (segment_len == 2 && segment[0] == '.' && segment[1] == '.') {
            if (
                out_len > 0 &&
                !(absolute && out_len == 1) &&
                (absolute || !ptn_normalized_previous_segment_is_parent(normalized, out_len))
            ) {
                size_t trim = out_len;
                if (trim > 0 && normalized[trim - 1] == '/') {
                    trim--;
                }
                while (trim > 0 && normalized[trim - 1] != '/') {
                    trim--;
                }
                if (trim == 0) {
                    out_len = 0;
                } else if (absolute) {
                    out_len = trim;
                } else {
                    out_len = trim - 1;
                }
            } else if (!absolute) {
                if (out_len > 0 && normalized[out_len - 1] != '/') {
                    normalized[out_len++] = '/';
                }
                memcpy(normalized + out_len, "..", 2);
                out_len += 2;
            }
            source += segment_len;
            source_len -= segment_len;
            continue;
        }

        if (out_len > 0 && normalized[out_len - 1] != '/') {
            normalized[out_len++] = '/';
        }
        memcpy(normalized + out_len, segment, segment_len);
        out_len += segment_len;

        source += segment_len;
        source_len -= segment_len;
    }

    if (out_len == 0) {
        if (absolute) {
            normalized[out_len++] = '/';
        } else {
            normalized[out_len++] = '.';
        }
    }
    normalized[out_len] = '\0';
    return normalized;
}

static char *ptn_path_operand_to_c_string(PtnStringOperand path) {
    if (memchr(path.data, '\0', path.len) != NULL) {
        return NULL;
    }
    return ptn_duplicate_string_len(path.data, path.len);
}

static char *ptn_fopen_path_operand_to_c_string(PtnStringOperand path) {
    if (memchr(path.data, '\0', path.len) != NULL) {
        return NULL;
    }
    if (path.len >= 8 && strncmp(path.data, "file:///", 8) == 0) {
        return ptn_duplicate_string_len(path.data + 7, path.len - 7);
    }
    return ptn_duplicate_string_len(path.data, path.len);
}

static void ptn_emit_file_warning(
    PtnRuntime *runtime,
    const char *function_name,
    const char *path,
    const char *detail,
    size_t line
) {
    int needed = snprintf(NULL, 0, "%s(%s): %s", function_name, path, detail);
    if (needed < 0) {
        ptn_abort_out_of_memory();
    }
    char *message = malloc((size_t)needed + 1);
    if (message == NULL) {
        ptn_abort_out_of_memory();
    }
    int written = snprintf(message, (size_t)needed + 1, "%s(%s): %s", function_name, path, detail);
    if (written < 0 || written != needed) {
        free(message);
        ptn_abort_out_of_memory();
    }
    ptn_emit_spaced_warning(&runtime->diagnostics, message, line);
    free(message);
}

static void ptn_emit_directory_open_warning(
    PtnRuntime *runtime,
    const char *function_name,
    const char *path,
    const char *detail,
    size_t line
) {
    char reason[256];
    int written = snprintf(reason, sizeof(reason), "Failed to open directory: %s", detail);
    if (written < 0 || (size_t)written >= sizeof(reason)) {
        ptn_abort_out_of_memory();
    }
    ptn_emit_file_warning(runtime, function_name, path, reason, line);
}

