static int ptn_ascii_case_has_prefix(const char *value, const char *prefix) {
    size_t prefix_len = strlen(prefix);
    return strlen(value) >= prefix_len && ptn_ascii_case_equal_n(value, prefix, prefix_len);
}

static int ptn_parse_php_temp_max_memory(const char *path, size_t *max_memory) {
    *max_memory = 2 * 1024 * 1024;
    const char *prefix = "php://temp";
    size_t prefix_len = strlen(prefix);
    if (!ptn_ascii_case_has_prefix(path, prefix)) {
        return 0;
    }
    const char *suffix = path + prefix_len;
    if (suffix[0] == '\0') {
        return 1;
    }
    if (suffix[0] != '/') {
        return 0;
    }
    const char *setting = suffix + 1;
    const char *colon_prefix = "maxmemory:";
    const char *equals_prefix = "maxmemory=";
    if (ptn_ascii_case_has_prefix(setting, colon_prefix)) {
        setting += strlen(colon_prefix);
    } else if (ptn_ascii_case_has_prefix(setting, equals_prefix)) {
        setting += strlen(equals_prefix);
    } else {
        return 0;
    }
    if (setting[0] == '\0') {
        return 0;
    }
    size_t parsed = 0;
    for (const char *cursor = setting; *cursor != '\0'; cursor++) {
        unsigned char byte = (unsigned char)*cursor;
        if (byte < '0' || byte > '9') {
            return 0;
        }
        size_t digit = (size_t)(byte - '0');
        if (parsed > (SIZE_MAX - digit) / 10) {
            parsed = SIZE_MAX;
        } else {
            parsed = parsed * 10 + digit;
        }
    }
    *max_memory = parsed;
    return 1;
}

static const char *ptn_php_memory_stream_mode(const char *mode, int *writable, int *append) {
    *append = mode[0] == 'a' || mode[0] == 'A';
    if ((mode[0] == 'r' || mode[0] == 'R') && strchr(mode, '+') == NULL) {
        *writable = 0;
        return "rb";
    }
    *writable = 1;
    return *append ? "a+b" : "w+b";
}

static int ptn_try_open_php_memory_stream(const char *path, const char *mode, PtnValue *out) {
    int writable = 0;
    int append = 0;
    const char *stream_mode = ptn_php_memory_stream_mode(mode, &writable, &append);
    if (ptn_ascii_case_equal(path, "php://memory")) {
        *out = ptn_resource(ptn_resource_new_memory_stream(
            path,
            stream_mode,
            PTN_STREAM_BACKEND_MEMORY,
            SIZE_MAX,
            writable,
            append
        ));
        return 1;
    }

    size_t max_memory = 0;
    if (!ptn_parse_php_temp_max_memory(path, &max_memory)) {
        return 0;
    }
    *out = ptn_resource(ptn_resource_new_memory_stream(
        path,
        stream_mode,
        PTN_STREAM_BACKEND_TEMP,
        max_memory,
        writable,
        append
    ));
    return 1;
}

static int ptn_try_open_php_input_stream(PtnRuntime *runtime, const char *path, PtnValue *out) {
    if (!ptn_ascii_case_equal(path, "php://input")) {
        return 0;
    }

    size_t request_body_len = 0;
    const char *request_body = ptn_runtime_request_body(runtime, &request_body_len);
    PtnResource *resource = ptn_resource_new_memory_stream(
        "php://input",
        "rb",
        PTN_STREAM_BACKEND_INPUT,
        SIZE_MAX,
        1,
        0
    );
    if (request_body_len != 0) {
        size_t written = ptn_stream_write_bytes(resource, request_body, request_body_len);
        if (written != request_body_len) {
            ptn_abort_out_of_memory();
        }
    }
    (void)ptn_stream_seek(resource, 0, SEEK_SET);
    resource->memory_stream->writable = 0;
    resource->memory_stream->append = 0;
    *out = ptn_resource(resource);
    return 1;
}

static int ptn_try_open_php_standard_stream(const char *path, PtnValue *out) {
    if (ptn_ascii_case_equal(path, "php://output") ||
        ptn_ascii_case_equal(path, "php://stdout")) {
        *out = ptn_standard_stream_resource_value(2);
        return 1;
    }
    if (ptn_ascii_case_equal(path, "php://stderr")) {
        *out = ptn_standard_stream_resource_value(3);
        return 1;
    }
    return 0;
}

static char *ptn_fopen_c_mode(const char *mode) {
    if (mode[0] != 'x') {
        return ptn_duplicate_string(mode);
    }
    size_t len = strlen(mode);
    char *c_mode = malloc(len + 2);
    if (c_mode == NULL) {
        ptn_abort_out_of_memory();
    }
    c_mode[0] = 'w';
    if (len > 1) {
        memcpy(c_mode + 1, mode + 1, len - 1);
    }
    c_mode[len] = 'x';
    c_mode[len + 1] = '\0';
    return c_mode;
}

static int ptn_stream_mode_is_append(PtnResource *resource) {
    return resource != NULL && resource->stream_mode != NULL && resource->stream_mode[0] == 'a';
}

static PtnValue ptn_internal_fopen(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand path_operand = ptn_internal_expect_string_arg(runtime, "fopen", 1, "filename", args[0], line);
    char *path = ptn_fopen_path_operand_to_c_string(path_operand);
    ptn_string_operand_free(path_operand);
    if (path == NULL) {
        ptn_emit_warning(&runtime->diagnostics, "fopen(): Filename contains null byte", line);
        return ptn_bool(0);
    }
    if (strncmp(path, "file://", 7) == 0 && strncmp(path, "file:///", 8) != 0) {
        int needed = snprintf(NULL, 0, "fopen(): Remote host file access not supported, %s", path);
        if (needed < 0) {
            free(path);
            ptn_abort_out_of_memory();
        }
        char *message = malloc((size_t)needed + 1);
        if (message == NULL) {
            free(path);
            ptn_abort_out_of_memory();
        }
        int written = snprintf(message, (size_t)needed + 1, "fopen(): Remote host file access not supported, %s", path);
        if (written < 0 || written != needed) {
            free(message);
            free(path);
            ptn_abort_out_of_memory();
        }
        ptn_emit_spaced_warning(&runtime->diagnostics, message, line);
        free(message);
        ptn_emit_file_warning(runtime, "fopen", path, "Failed to open stream: no suitable wrapper could be found", line);
        free(path);
        return ptn_bool(0);
    }

    PtnStringOperand mode_operand = ptn_internal_expect_string_arg(runtime, "fopen", 2, "mode", args[1], line);
    char *mode = ptn_path_operand_to_c_string(mode_operand);
    ptn_string_operand_free(mode_operand);
    if (mode == NULL) {
        ptn_emit_warning(&runtime->diagnostics, "fopen(): Argument #2 ($mode) must not contain any null bytes", line);
        free(path);
        return ptn_bool(0);
    }

    PtnValue php_stream;
    if (ptn_try_open_php_input_stream(runtime, path, &php_stream)) {
        free(mode);
        free(path);
        return php_stream;
    }
    if (ptn_try_open_php_standard_stream(path, &php_stream)) {
        free(mode);
        free(path);
        return php_stream;
    }
    if (ptn_try_open_php_memory_stream(path, mode, &php_stream)) {
        free(mode);
        free(path);
        return php_stream;
    }

    char *c_mode = ptn_fopen_c_mode(mode);
    FILE *stream = fopen(path, c_mode);
    free(c_mode);
    if (stream == NULL) {
        char detail[192];
        int needed = snprintf(detail, sizeof(detail), "Failed to open stream: %s", strerror(errno));
        if (needed < 0 || (size_t)needed >= sizeof(detail)) {
            ptn_abort_out_of_memory();
        }
        ptn_emit_file_warning(runtime, "fopen", path, detail, line);
        free(mode);
        free(path);
        return ptn_bool(0);
    }
    if (mode[0] == 'a') {
        (void)fseek(stream, 0, SEEK_SET);
    }

    PtnValue resource = ptn_resource(ptn_resource_new_stream(stream, path, mode));
    free(mode);
    free(path);
    return resource;
}

static PtnValue ptn_internal_opendir(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand path_operand = ptn_internal_expect_string_arg(runtime, "opendir", 1, "directory", args[0], line);
    char *path = ptn_path_operand_to_c_string(path_operand);
    ptn_string_operand_free(path_operand);
    if (path == NULL) {
        ptn_emit_warning(&runtime->diagnostics, "opendir(): Filename contains null byte", line);
        return ptn_bool(0);
    }

#if defined(_WIN32)
    ptn_emit_file_warning(runtime, "opendir", path, "directory streams are unsupported on this platform", line);
    free(path);
    return ptn_bool(0);
#else
    DIR *directory = opendir(path);
    if (directory == NULL) {
        ptn_emit_directory_open_warning(runtime, "opendir", path, strerror(errno), line);
        free(path);
        return ptn_bool(0);
    }

    PtnValue resource = ptn_resource(ptn_resource_new_directory(directory, path));
    free(path);
    return resource;
#endif
}

static PtnValue ptn_directory_object_from_resource(PtnRuntime *runtime, PtnValue handle, const char *path, size_t line) {
    PtnValue object = ptn_object_new_shell(runtime, "Directory");
    PtnValue path_value = ptn_owned_string(ptn_duplicate_string(path));
    PtnValue assigned = ptn_object_declare_property(
        runtime,
        object,
        "path",
        "Directory",
        PTN_PROPERTY_PUBLIC,
        PTN_PROPERTY_PUBLIC,
        0,
        PTN_PROPERTY_TYPE_NONE,
        NULL,
        NULL,
        0,
        1,
        path_value,
        line
    );
    ptn_value_destroy(&assigned);
    ptn_value_destroy(&path_value);
    assigned = ptn_object_declare_property(
        runtime,
        object,
        "handle",
        "Directory",
        PTN_PROPERTY_PUBLIC,
        PTN_PROPERTY_PUBLIC,
        0,
        PTN_PROPERTY_TYPE_NONE,
        NULL,
        NULL,
        0,
        1,
        handle,
        line
    );
    ptn_value_destroy(&assigned);
    ptn_value_destroy(&handle);
    return object;
}

static PtnValue ptn_internal_dir(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand path_operand = ptn_internal_expect_string_arg(runtime, "dir", 1, "directory", args[0], line);
    char *path = ptn_path_operand_to_c_string(path_operand);
    ptn_string_operand_free(path_operand);
    if (path == NULL) {
        ptn_emit_warning(&runtime->diagnostics, "dir(): Filename contains null byte", line);
        return ptn_bool(0);
    }

#if defined(_WIN32)
    ptn_emit_directory_open_warning(runtime, "dir", path, "directory streams are unsupported on this platform", line);
    free(path);
    return ptn_bool(0);
#else
    DIR *directory = opendir(path);
    if (directory == NULL) {
        ptn_emit_directory_open_warning(runtime, "dir", path, strerror(errno), line);
        free(path);
        return ptn_bool(0);
    }

    PtnValue handle = ptn_resource(ptn_resource_new_directory(directory, path));
    PtnValue object = ptn_directory_object_from_resource(runtime, handle, path, line);
    free(path);
    return object;
#endif
}

static PtnValue ptn_internal_closedir(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)line;
    PtnValue value = ptn_value_deref(args[0]);
    if (value.type == PTN_NULL) {
        ptn_throw_exception(runtime, "TypeError", "No resource supplied");
        return ptn_null();
    }
    if (value.type != PTN_RESOURCE) {
        char message[192];
        int written = snprintf(
            message,
            sizeof(message),
            "closedir(): Argument #1 ($dir_handle) must be of type resource or null, %s given",
            ptn_offset_container_type_name(value)
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "TypeError", message);
        return ptn_null();
    }
    if (value.as.resource->directory == NULL) {
        ptn_throw_exception(
            runtime,
            "TypeError",
            "closedir(): Argument #1 ($dir_handle) must be a valid Directory resource"
        );
        return ptn_null();
    }
    ptn_resource_close(value.as.resource);
    return ptn_null();
}

static PtnValue ptn_internal_fclose(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnValue value = ptn_value_deref(args[0]);
    if (value.type != PTN_RESOURCE) {
        char message[192];
        int written = snprintf(
            message,
            sizeof(message),
            "fclose(): Argument #1 ($stream) must be of type resource, %s given",
            ptn_offset_container_type_name(value)
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "TypeError", message);
        return ptn_null();
    }
    if (!ptn_stream_resource_is_open(value.as.resource)) {
        return ptn_bool(0);
    }
    ptn_resource_close(value.as.resource);
    (void)line;
    return ptn_bool(1);
}

