static PtnValue ptn_internal_bin2hex(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    static const char hex_digits[] = "0123456789abcdef";
    PtnStringOperand string = ptn_internal_expect_string_arg(runtime, "bin2hex", 1, "string", args[0], line);
    size_t len = string.len;
    if (len > (SIZE_MAX - 1) / 2) {
        ptn_abort_out_of_memory();
    }
    char *hex = malloc((len * 2) + 1);
    if (hex == NULL) {
        ptn_abort_out_of_memory();
    }
    for (size_t i = 0; i < len; i++) {
        unsigned char byte = (unsigned char)string.data[i];
        hex[i * 2] = hex_digits[byte >> 4];
        hex[(i * 2) + 1] = hex_digits[byte & 0x0f];
    }
    hex[len * 2] = '\0';
    ptn_string_operand_free(string);
    return ptn_owned_string_len(hex, len * 2);
}

static int ptn_hex_nibble(unsigned char byte) {
    if (byte >= '0' && byte <= '9') {
        return (int)(byte - '0');
    }
    if (byte >= 'a' && byte <= 'f') {
        return 10 + (int)(byte - 'a');
    }
    if (byte >= 'A' && byte <= 'F') {
        return 10 + (int)(byte - 'A');
    }
    return -1;
}

static int ptn_octal_nibble(unsigned char byte) {
    if (byte >= '0' && byte <= '7') {
        return (int)(byte - '0');
    }
    return -1;
}

static void ptn_cslashes_charlist_mask(
    PtnRuntime *runtime,
    const char *function_name,
    const char *charlist,
    size_t len,
    size_t line,
    unsigned char mask[256]
) {
    memset(mask, 0, 256);
    for (size_t i = 0; i < len; i++) {
        unsigned char start = (unsigned char)charlist[i];
        if (i + 3 < len && charlist[i + 1] == '.' && charlist[i + 2] == '.') {
            unsigned char end = (unsigned char)charlist[i + 3];
            if (start <= end) {
                for (unsigned int byte = start; byte <= end; byte++) {
                    mask[byte] = 1;
                }
                i += 3;
                continue;
            }
            char message[128];
            int written = snprintf(
                message,
                sizeof(message),
                "%s(): Invalid '..'-range, '..'-range needs to be incrementing",
                function_name
            );
            if (written < 0 || (size_t)written >= sizeof(message)) {
                ptn_abort_out_of_memory();
            }
            ptn_emit_warning(&runtime->diagnostics, message, line);
        }
        mask[start] = 1;
    }
}

static size_t ptn_addcslashes_escape_len(unsigned char byte) {
    switch (byte) {
        case '\0':
            return 4;
        case '\n':
        case '\r':
        case '\t':
        case '\v':
        case '\f':
        case '\a':
        case '\b':
            return 2;
        default:
            if (byte < 32 || byte > 126) {
                return 4;
            }
            return 2;
    }
}

static void ptn_addcslashes_write_escape(char *output, size_t *out, unsigned char byte) {
    output[(*out)++] = '\\';
    switch (byte) {
        case '\0':
            output[(*out)++] = '0';
            output[(*out)++] = '0';
            output[(*out)++] = '0';
            break;
        case '\n':
            output[(*out)++] = 'n';
            break;
        case '\r':
            output[(*out)++] = 'r';
            break;
        case '\t':
            output[(*out)++] = 't';
            break;
        case '\v':
            output[(*out)++] = 'v';
            break;
        case '\f':
            output[(*out)++] = 'f';
            break;
        case '\a':
            output[(*out)++] = 'a';
            break;
        case '\b':
            output[(*out)++] = 'b';
            break;
        default:
            if (byte < 32 || byte > 126) {
                static const char octal_digits[] = "01234567";
                output[(*out)++] = octal_digits[(byte >> 6) & 0x07];
                output[(*out)++] = octal_digits[(byte >> 3) & 0x07];
                output[(*out)++] = octal_digits[byte & 0x07];
            } else {
                output[(*out)++] = (char)byte;
            }
            break;
    }
}

static char *ptn_addcslashes_string(
    PtnRuntime *runtime,
    const char *function_name,
    const char *input,
    size_t input_len,
    const char *charlist,
    size_t charlist_len,
    size_t line,
    size_t *output_len_out
) {
    unsigned char mask[256];
    ptn_cslashes_charlist_mask(runtime, function_name, charlist, charlist_len, line, mask);

    size_t output_len = 0;
    for (size_t i = 0; i < input_len; i++) {
        unsigned char byte = (unsigned char)input[i];
        size_t add_len = mask[byte] ? ptn_addcslashes_escape_len(byte) : 1;
        if (add_len > SIZE_MAX - output_len - 1) {
            ptn_abort_out_of_memory();
        }
        output_len += add_len;
    }

    char *output = malloc(output_len + 1);
    if (output == NULL) {
        ptn_abort_out_of_memory();
    }

    size_t out = 0;
    for (size_t i = 0; i < input_len; i++) {
        unsigned char byte = (unsigned char)input[i];
        if (mask[byte]) {
            ptn_addcslashes_write_escape(output, &out, byte);
        } else {
            output[out++] = (char)byte;
        }
    }
    output[out] = '\0';
    *output_len_out = out;
    return output;
}

static PtnValue ptn_internal_addcslashes(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "addcslashes", 1, "string", args[0], line);
    PtnStringOperand charlist = ptn_internal_expect_string_arg(runtime, "addcslashes", 2, "characters", args[1], line);
    size_t output_len = 0;
    char *output = ptn_addcslashes_string(
        runtime,
        "addcslashes",
        input.data,
        input.len,
        charlist.data,
        charlist.len,
        line,
        &output_len
    );
    ptn_string_operand_free(input);
    ptn_string_operand_free(charlist);
    return ptn_owned_string_len(output, output_len);
}

static int ptn_addslashes_needs_escape(unsigned char byte) {
    return byte == '\0' || byte == '\'' || byte == '"' || byte == '\\';
}

static size_t ptn_addslashes_escape_len(unsigned char byte) {
    return ptn_addslashes_needs_escape(byte) ? 2 : 1;
}

static void ptn_addslashes_write_escape(char *output, size_t *out, unsigned char byte) {
    if (byte == '\0') {
        output[(*out)++] = '\\';
        output[(*out)++] = '0';
        return;
    }
    if (ptn_addslashes_needs_escape(byte)) {
        output[(*out)++] = '\\';
    }
    output[(*out)++] = (char)byte;
}

static char *ptn_addslashes_string(const char *input, size_t len, size_t *output_len_out) {
    size_t output_len = 0;
    for (size_t i = 0; i < len; i++) {
        size_t add_len = ptn_addslashes_escape_len((unsigned char)input[i]);
        if (add_len > SIZE_MAX - output_len - 1) {
            ptn_abort_out_of_memory();
        }
        output_len += add_len;
    }

    char *output = malloc(output_len + 1);
    if (output == NULL) {
        ptn_abort_out_of_memory();
    }

    size_t out = 0;
    for (size_t i = 0; i < len; i++) {
        ptn_addslashes_write_escape(output, &out, (unsigned char)input[i]);
    }
    output[out] = '\0';
    *output_len_out = out;
    return output;
}

static PtnValue ptn_internal_addslashes(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "addslashes", 1, "string", args[0], line);
    size_t output_len = 0;
    char *output = ptn_addslashes_string(input.data, input.len, &output_len);
    ptn_string_operand_free(input);
    return ptn_owned_string_len(output, output_len);
}

static char *ptn_stripcslashes_string(const char *input, size_t len, size_t *output_len_out) {
    char *output = malloc(len + 1);
    if (output == NULL) {
        ptn_abort_out_of_memory();
    }

    size_t out = 0;
    for (size_t i = 0; i < len; i++) {
        unsigned char byte = (unsigned char)input[i];
        if (byte != '\\') {
            output[out++] = (char)byte;
            continue;
        }
        if (i + 1 >= len) {
            output[out++] = '\\';
            continue;
        }

        unsigned char escaped = (unsigned char)input[++i];
        switch (escaped) {
            case 'n':
                output[out++] = '\n';
                break;
            case 'r':
                output[out++] = '\r';
                break;
            case 't':
                output[out++] = '\t';
                break;
            case 'v':
                output[out++] = '\v';
                break;
            case 'f':
                output[out++] = '\f';
                break;
            case 'a':
                output[out++] = '\a';
                break;
            case 'b':
                output[out++] = '\b';
                break;
            case '\\':
                output[out++] = '\\';
                break;
            case 'x': {
                unsigned int value = 0;
                size_t digits = 0;
                while (digits < 2 && i + 1 < len) {
                    int nibble = ptn_hex_nibble((unsigned char)input[i + 1]);
                    if (nibble < 0) {
                        break;
                    }
                    value = (value << 4) | (unsigned int)nibble;
                    digits++;
                    i++;
                }
                output[out++] = digits == 0 ? 'x' : (char)(value & 0xff);
                break;
            }
            default: {
                int octal = ptn_octal_nibble(escaped);
                if (octal < 0) {
                    output[out++] = (char)escaped;
                    break;
                }
                unsigned int value = (unsigned int)octal;
                size_t digits = 1;
                while (digits < 3 && i + 1 < len) {
                    int next = ptn_octal_nibble((unsigned char)input[i + 1]);
                    if (next < 0) {
                        break;
                    }
                    value = (value << 3) | (unsigned int)next;
                    digits++;
                    i++;
                }
                output[out++] = (char)(value & 0xff);
                break;
            }
        }
    }

    output[out] = '\0';
    *output_len_out = out;
    return output;
}

static PtnValue ptn_internal_stripcslashes(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "stripcslashes", 1, "string", args[0], line);
    size_t output_len = 0;
    char *output = ptn_stripcslashes_string(input.data, input.len, &output_len);
    ptn_string_operand_free(input);
    return ptn_owned_string_len(output, output_len);
}

static char *ptn_stripslashes_string(const char *input, size_t len, size_t *output_len_out) {
    char *output = malloc(len + 1);
    if (output == NULL) {
        ptn_abort_out_of_memory();
    }

    size_t input_offset = 0;
    size_t output_offset = 0;
    while (input_offset < len) {
        unsigned char byte = (unsigned char)input[input_offset++];
        if (byte != '\\') {
            output[output_offset++] = (char)byte;
            continue;
        }
        if (input_offset >= len) {
            continue;
        }
        byte = (unsigned char)input[input_offset++];
        output[output_offset++] = byte == '0' ? '\0' : (char)byte;
    }
    output[output_offset] = '\0';
    *output_len_out = output_offset;
    return output;
}

static PtnValue ptn_internal_stripslashes(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "stripslashes", 1, "string", args[0], line);
    size_t output_len = 0;
    char *output = ptn_stripslashes_string(input.data, input.len, &output_len);
    ptn_string_operand_free(input);
    return ptn_owned_string_len(output, output_len);
}

static PtnValue ptn_internal_hex2bin(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand hex = ptn_internal_expect_string_arg(runtime, "hex2bin", 1, "string", args[0], line);
    size_t len = hex.len;
    if ((len % 2) != 0) {
        ptn_emit_warning(
            &runtime->diagnostics,
            "hex2bin(): Hexadecimal input string must have an even length",
            line
        );
        ptn_string_operand_free(hex);
        return ptn_bool(0);
    }

    char *binary = malloc((len / 2) + 1);
    if (binary == NULL) {
        ptn_abort_out_of_memory();
    }

    size_t output_len = 0;
    for (size_t i = 0; i < len; i += 2) {
        int high = ptn_hex_nibble((unsigned char)hex.data[i]);
        int low = ptn_hex_nibble((unsigned char)hex.data[i + 1]);
        if (high < 0 || low < 0) {
            ptn_emit_warning(
                &runtime->diagnostics,
                "hex2bin(): Input string must be hexadecimal string",
                line
            );
            free(binary);
            ptn_string_operand_free(hex);
            return ptn_bool(0);
        }
        binary[output_len++] = (char)((high << 4) | low);
    }
    binary[output_len] = '\0';
    ptn_string_operand_free(hex);
    return ptn_owned_string_len(binary, output_len);
}

#define PTN_PACK_ENDIAN_MACHINE 0
#define PTN_PACK_ENDIAN_LITTLE 1
#define PTN_PACK_ENDIAN_BIG 2

static int ptn_pack_machine_is_little_endian(void) {
    const uint16_t value = 1;
    return *((const unsigned char *)&value) == 1;
}

static int ptn_pack_effective_endian(int endian) {
    if (endian == PTN_PACK_ENDIAN_MACHINE) {
        return ptn_pack_machine_is_little_endian()
            ? PTN_PACK_ENDIAN_LITTLE
            : PTN_PACK_ENDIAN_BIG;
    }
    return endian;
}

static int ptn_pack_integer_spec(
    unsigned char code,
    size_t *width_out,
    int *signed_out,
    int *endian_out
) {
    switch (code) {
        case 'c':
            *width_out = 1;
            *signed_out = 1;
            *endian_out = PTN_PACK_ENDIAN_LITTLE;
            return 1;
        case 'C':
            *width_out = 1;
            *signed_out = 0;
            *endian_out = PTN_PACK_ENDIAN_LITTLE;
            return 1;
        case 's':
            *width_out = 2;
            *signed_out = 1;
            *endian_out = PTN_PACK_ENDIAN_MACHINE;
            return 1;
        case 'S':
            *width_out = 2;
            *signed_out = 0;
            *endian_out = PTN_PACK_ENDIAN_MACHINE;
            return 1;
        case 'n':
            *width_out = 2;
            *signed_out = 0;
            *endian_out = PTN_PACK_ENDIAN_BIG;
            return 1;
        case 'v':
            *width_out = 2;
            *signed_out = 0;
            *endian_out = PTN_PACK_ENDIAN_LITTLE;
            return 1;
        case 'i':
        case 'l':
            *width_out = 4;
            *signed_out = 1;
            *endian_out = PTN_PACK_ENDIAN_MACHINE;
            return 1;
        case 'I':
        case 'L':
            *width_out = 4;
            *signed_out = 0;
            *endian_out = PTN_PACK_ENDIAN_MACHINE;
            return 1;
        case 'N':
            *width_out = 4;
            *signed_out = 0;
            *endian_out = PTN_PACK_ENDIAN_BIG;
            return 1;
        case 'V':
            *width_out = 4;
            *signed_out = 0;
            *endian_out = PTN_PACK_ENDIAN_LITTLE;
            return 1;
        case 'q':
            *width_out = 8;
            *signed_out = 1;
            *endian_out = PTN_PACK_ENDIAN_MACHINE;
            return 1;
        case 'Q':
            *width_out = 8;
            *signed_out = 0;
            *endian_out = PTN_PACK_ENDIAN_MACHINE;
            return 1;
        case 'J':
            *width_out = 8;
            *signed_out = 0;
            *endian_out = PTN_PACK_ENDIAN_BIG;
            return 1;
        case 'P':
            *width_out = 8;
            *signed_out = 0;
            *endian_out = PTN_PACK_ENDIAN_LITTLE;
            return 1;
    }
    return 0;
}

static int ptn_pack_float_spec(unsigned char code, size_t *width_out, int *endian_out) {
    switch (code) {
        case 'e':
            *width_out = 8;
            *endian_out = PTN_PACK_ENDIAN_LITTLE;
            return 1;
        case 'E':
            *width_out = 8;
            *endian_out = PTN_PACK_ENDIAN_BIG;
            return 1;
        case 'g':
            *width_out = 4;
            *endian_out = PTN_PACK_ENDIAN_LITTLE;
            return 1;
        case 'G':
            *width_out = 4;
            *endian_out = PTN_PACK_ENDIAN_BIG;
            return 1;
    }
    return 0;
}

static int ptn_pack_string_spec(unsigned char code) {
    return code == 'a' || code == 'A' || code == 'Z' || code == 'h' || code == 'H';
}

static int ptn_pack_control_spec(unsigned char code) {
    return code == 'x' || code == 'X' || code == '@';
}

static int ptn_pack_supported_spec(unsigned char code) {
    size_t width = 0;
    int signed_value = 0;
    int endian = 0;
    return ptn_pack_integer_spec(code, &width, &signed_value, &endian) ||
        ptn_pack_float_spec(code, &width, &endian) ||
        ptn_pack_string_spec(code) ||
        ptn_pack_control_spec(code);
}

static int ptn_pack_parse_repeater(
    PtnStringOperand format,
    size_t *offset,
    int *has_repeater_out,
    int *star_out,
    size_t *repeat_out
) {
    *has_repeater_out = 0;
    *star_out = 0;
    *repeat_out = 1;
    if (*offset >= format.len) {
        return 1;
    }
    unsigned char byte = (unsigned char)format.data[*offset];
    if (byte == '*') {
        *has_repeater_out = 1;
        *star_out = 1;
        (*offset)++;
        return 1;
    }
    if (!isdigit(byte)) {
        return 1;
    }
    *has_repeater_out = 1;
    size_t value = 0;
    while (*offset < format.len && isdigit((unsigned char)format.data[*offset])) {
        unsigned int digit = (unsigned int)(format.data[*offset] - '0');
        if (value > (SIZE_MAX - digit) / 10) {
            return 0;
        }
        value = value * 10 + digit;
        (*offset)++;
    }
    *repeat_out = value;
    return 1;
}

static void ptn_pack_append_uint(PtnStringBuffer *buffer, uint64_t value, size_t width, int endian) {
    endian = ptn_pack_effective_endian(endian);
    if (endian == PTN_PACK_ENDIAN_LITTLE) {
        for (size_t i = 0; i < width; i++) {
            ptn_string_buffer_append_char(buffer, (char)((value >> (8 * i)) & 0xff));
        }
        return;
    }
    for (size_t i = 0; i < width; i++) {
        size_t shift = 8 * (width - 1 - i);
        ptn_string_buffer_append_char(buffer, (char)((value >> shift) & 0xff));
    }
}

static uint64_t ptn_unpack_read_uint(const unsigned char *data, size_t width, int endian) {
    uint64_t value = 0;
    endian = ptn_pack_effective_endian(endian);
    if (endian == PTN_PACK_ENDIAN_LITTLE) {
        for (size_t i = 0; i < width; i++) {
            value |= ((uint64_t)data[i]) << (8 * i);
        }
        return value;
    }
    for (size_t i = 0; i < width; i++) {
        value = (value << 8) | (uint64_t)data[i];
    }
    return value;
}

static int64_t ptn_unpack_signed_value(uint64_t value, size_t width) {
    switch (width) {
        case 1:
            return (int64_t)(int8_t)value;
        case 2:
            return (int64_t)(int16_t)value;
        case 4:
            return (int64_t)(int32_t)value;
        case 8:
            return (int64_t)value;
    }
    return (int64_t)value;
}

static void ptn_pack_warn_float_int_cast(PtnRuntime *runtime, double floating, size_t line) {
    char value_text[64];
    int value_written = snprintf(value_text, sizeof(value_text), "%.16G", floating);
    if (value_written < 0 || (size_t)value_written >= sizeof(value_text)) {
        ptn_abort_out_of_memory();
    }
    char message[160];
    int written = snprintf(
        message,
        sizeof(message),
        "The float %s is not representable as an int, cast occurred",
        value_text
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_emit_spaced_warning(&runtime->diagnostics, message, line);
}

static int64_t ptn_pack_value_to_integer(PtnRuntime *runtime, PtnValue value, size_t line) {
    value = ptn_value_deref(value);
    int64_t integer = 0;
    if (ptn_fast_integer_value(value, &integer)) {
        return integer;
    }
    if (value.type == PTN_FLOAT) {
        if (ptn_float_to_int_out_of_range(value.as.floating)) {
            ptn_pack_warn_float_int_cast(runtime, value.as.floating, line);
            return INT64_MIN;
        }
        return (int64_t)value.as.floating;
    }
    return ptn_value_to_integer(value);
}

static double ptn_pack_value_to_double(PtnValue value) {
    return ptn_value_to_double(value);
}

static void ptn_pack_append_float(PtnStringBuffer *buffer, PtnValue value, size_t width, int endian) {
    uint64_t bits = 0;
    double floating = ptn_pack_value_to_double(value);
    if (width == 8) {
        memcpy(&bits, &floating, sizeof(bits));
    } else {
        float narrowed = (float)floating;
        uint32_t narrow_bits = 0;
        memcpy(&narrow_bits, &narrowed, sizeof(narrow_bits));
        bits = narrow_bits;
    }
    ptn_pack_append_uint(buffer, bits, width, endian);
}

static int ptn_pack_repeater_for_string(
    unsigned char code,
    int has_repeater,
    int star,
    size_t repeat,
    size_t input_len,
    size_t *count_out
) {
    if (star) {
        *count_out = code == 'Z' ? input_len + 1 : input_len;
        if (*count_out < input_len) {
            return 0;
        }
        return 1;
    }
    *count_out = has_repeater ? repeat : 1;
    return 1;
}

static void ptn_pack_append_padded_string(
    PtnStringBuffer *buffer,
    PtnStringOperand string,
    size_t count,
    char pad
) {
    size_t copy_len = string.len < count ? string.len : count;
    ptn_string_buffer_append_len(buffer, string.data, copy_len);
    for (size_t i = copy_len; i < count; i++) {
        ptn_string_buffer_append_char(buffer, pad);
    }
}

static void ptn_pack_append_z_string(PtnStringBuffer *buffer, PtnStringOperand string, size_t count) {
    if (count == 0) {
        return;
    }
    size_t copy_limit = count - 1;
    size_t copy_len = string.len < copy_limit ? string.len : copy_limit;
    ptn_string_buffer_append_len(buffer, string.data, copy_len);
    for (size_t i = copy_len; i < count; i++) {
        ptn_string_buffer_append_char(buffer, '\0');
    }
}

static int ptn_pack_string_hex_nibble(PtnStringOperand string, size_t index) {
    if (index >= string.len) {
        return 0;
    }
    int nibble = ptn_hex_nibble((unsigned char)string.data[index]);
    return nibble < 0 ? 0 : nibble;
}

static void ptn_pack_append_hex_string(
    PtnStringBuffer *buffer,
    PtnStringOperand string,
    size_t nibble_count,
    int high_nibble_first
) {
    size_t byte_count = (nibble_count + 1) / 2;
    for (size_t byte_index = 0; byte_index < byte_count; byte_index++) {
        size_t first_index = byte_index * 2;
        int first = ptn_pack_string_hex_nibble(string, first_index);
        int second = first_index + 1 < nibble_count
            ? ptn_pack_string_hex_nibble(string, first_index + 1)
            : 0;
        unsigned char byte = high_nibble_first
            ? (unsigned char)((first << 4) | second)
            : (unsigned char)(first | (second << 4));
        ptn_string_buffer_append_char(buffer, (char)byte);
    }
}

static void ptn_pack_emit_format_error(PtnRuntime *runtime, const char *function_name, unsigned char code) {
    char message[96];
    int written = snprintf(message, sizeof(message), "Invalid format type %c", code);
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    (void)function_name;
    ptn_throw_exception(runtime, "ValueError", message);
}

static int ptn_pack_require_arguments(
    PtnRuntime *runtime,
    unsigned char code,
    size_t needed,
    size_t available
) {
    if (needed <= available) {
        return 1;
    }
    char message[96];
    int written = snprintf(message, sizeof(message), "Type %c: too few arguments", code);
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "ValueError", message);
    return 0;
}

static PtnValue ptn_internal_pack(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand format = ptn_internal_expect_string_arg(runtime, "pack", 1, "format", args[0], line);
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    size_t arg_index = 1;

    for (size_t format_offset = 0; format_offset < format.len;) {
        unsigned char code = (unsigned char)format.data[format_offset++];
        if (code == '/') {
            continue;
        }
        if (!ptn_pack_supported_spec(code)) {
            ptn_pack_emit_format_error(runtime, "pack", code);
            ptn_string_operand_free(format);
            free(output.data);
            return ptn_null();
        }

        int has_repeater = 0;
        int star = 0;
        size_t repeat = 1;
        if (!ptn_pack_parse_repeater(format, &format_offset, &has_repeater, &star, &repeat)) {
            ptn_string_operand_free(format);
            free(output.data);
            ptn_throw_exception(runtime, "ValueError", "pack(): Type repeater must be less than or equal to SIZE_MAX");
            return ptn_null();
        }

        size_t width = 0;
        int signed_value = 0;
        int endian = 0;
        if (ptn_pack_integer_spec(code, &width, &signed_value, &endian)) {
            (void)signed_value;
            size_t count = star ? (argc - arg_index) : repeat;
            if (!ptn_pack_require_arguments(runtime, code, count, argc - arg_index)) {
                ptn_string_operand_free(format);
                free(output.data);
                return ptn_null();
            }
            for (size_t i = 0; i < count; i++) {
                PtnValue value = arg_index < argc ? args[arg_index] : ptn_null();
                arg_index++;
                uint64_t bits = (uint64_t)ptn_pack_value_to_integer(runtime, value, line);
                ptn_pack_append_uint(&output, bits, width, endian);
            }
            continue;
        }

        if (ptn_pack_float_spec(code, &width, &endian)) {
            size_t count = star ? (argc - arg_index) : repeat;
            if (!ptn_pack_require_arguments(runtime, code, count, argc - arg_index)) {
                ptn_string_operand_free(format);
                free(output.data);
                return ptn_null();
            }
            for (size_t i = 0; i < count; i++) {
                PtnValue value = arg_index < argc ? args[arg_index] : ptn_null();
                arg_index++;
                ptn_pack_append_float(&output, value, width, endian);
            }
            continue;
        }

        if (ptn_pack_string_spec(code)) {
            if (!ptn_pack_require_arguments(runtime, code, 1, argc - arg_index)) {
                ptn_string_operand_free(format);
                free(output.data);
                return ptn_null();
            }
            PtnValue value = arg_index < argc ? args[arg_index] : ptn_null();
            arg_index++;
            PtnStringOperand string = ptn_internal_expect_string_arg(runtime, "pack", arg_index, "value", value, line);
            size_t count = 0;
            if (!ptn_pack_repeater_for_string(code, has_repeater, star, repeat, string.len, &count)) {
                ptn_string_operand_free(string);
                ptn_string_operand_free(format);
                free(output.data);
                ptn_abort_out_of_memory();
            }
            if (code == 'a') {
                ptn_pack_append_padded_string(&output, string, count, '\0');
            } else if (code == 'A') {
                ptn_pack_append_padded_string(&output, string, count, ' ');
            } else if (code == 'Z') {
                ptn_pack_append_z_string(&output, string, count);
            } else {
                ptn_pack_append_hex_string(&output, string, count, code == 'H');
            }
            ptn_string_operand_free(string);
            continue;
        }

        size_t count = star ? 0 : repeat;
        if (code == 'x') {
            for (size_t i = 0; i < count; i++) {
                ptn_string_buffer_append_char(&output, '\0');
            }
        } else if (code == 'X') {
            output.len = count > output.len ? 0 : output.len - count;
            output.data[output.len] = '\0';
        } else if (code == '@') {
            if (count < output.len) {
                output.len = count;
                output.data[output.len] = '\0';
            } else {
                while (output.len < count) {
                    ptn_string_buffer_append_char(&output, '\0');
                }
            }
        }
    }

    ptn_string_operand_free(format);
    return ptn_owned_string_len(output.data, output.len);
}

static void ptn_unpack_emit_not_enough(
    PtnRuntime *runtime,
    unsigned char code,
    size_t needed,
    size_t available,
    size_t line
) {
    char message[160];
    int written = snprintf(
        message,
        sizeof(message),
        "unpack(): Type %c: not enough input values, need %zu values but only %zu %s provided",
        code,
        needed,
        available,
        available == 1 ? "was" : "were"
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_emit_spaced_warning(&runtime->diagnostics, message, line);
}

static void ptn_unpack_emit_integer_overflow(PtnRuntime *runtime, unsigned char code, size_t line) {
    char message[96];
    int written = snprintf(message, sizeof(message), "unpack(): Type %c: integer overflow", code);
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_emit_spaced_warning(&runtime->diagnostics, message, line);
}

static int ptn_unpack_require_input(
    PtnRuntime *runtime,
    unsigned char code,
    size_t cursor,
    size_t data_len,
    size_t needed,
    size_t line
) {
    size_t available = cursor <= data_len ? data_len - cursor : 0;
    if (available >= needed) {
        return 1;
    }
    ptn_unpack_emit_not_enough(runtime, code, needed, available, line);
    return 0;
}

static void ptn_unpack_set_result(
    PtnArray *array,
    const char *name,
    size_t name_len,
    int suffix_named_key,
    size_t item_index,
    size_t *next_auto_key,
    PtnValue value
) {
    if (name_len == 0) {
        ptn_array_set_entry(array, ptn_array_int_key((int64_t)(*next_auto_key)), value);
        (*next_auto_key)++;
        return;
    }
    if (!suffix_named_key) {
        ptn_array_set_entry(array, ptn_array_string_key_len(name, name_len), value);
        return;
    }

    int digits = snprintf(NULL, 0, "%zu", item_index + 1);
    if (digits < 0) {
        ptn_abort_out_of_memory();
    }
    char *key = malloc(name_len + (size_t)digits + 1);
    if (key == NULL) {
        ptn_abort_out_of_memory();
    }
    memcpy(key, name, name_len);
    snprintf(key + name_len, (size_t)digits + 1, "%zu", item_index + 1);
    ptn_array_set_entry(array, ptn_array_string_key_len(key, name_len + (size_t)digits), value);
    free(key);
}

static size_t ptn_unpack_trim_a_len(const unsigned char *data, size_t len) {
    while (len > 0) {
        unsigned char byte = data[len - 1];
        if (byte != '\0' && byte > ' ') {
            break;
        }
        len--;
    }
    return len;
}

static PtnValue ptn_unpack_string_value(unsigned char code, const unsigned char *data, size_t len) {
    if (code == 'A') {
        len = ptn_unpack_trim_a_len(data, len);
    } else if (code == 'Z') {
        size_t nul_offset = 0;
        while (nul_offset < len && data[nul_offset] != '\0') {
            nul_offset++;
        }
        len = nul_offset;
    }
    return ptn_owned_string_len(ptn_duplicate_string_len((const char *)data, len), len);
}

static char ptn_unpack_hex_char(unsigned int nibble) {
    static const char digits[] = "0123456789abcdef";
    return digits[nibble & 0xf];
}

static PtnValue ptn_unpack_hex_value(
    unsigned char code,
    const unsigned char *data,
    size_t nibble_count
) {
    char *output = malloc(nibble_count + 1);
    if (output == NULL) {
        ptn_abort_out_of_memory();
    }
    for (size_t i = 0; i < nibble_count; i++) {
        unsigned char byte = data[i / 2];
        unsigned int nibble;
        if (code == 'H') {
            nibble = (i % 2) == 0 ? (byte >> 4) : (byte & 0xf);
        } else {
            nibble = (i % 2) == 0 ? (byte & 0xf) : (byte >> 4);
        }
        output[i] = ptn_unpack_hex_char(nibble);
    }
    output[nibble_count] = '\0';
    return ptn_owned_string_len(output, nibble_count);
}

static PtnValue ptn_unpack_float_value(const unsigned char *data, size_t width, int endian) {
    uint64_t bits = ptn_unpack_read_uint(data, width, endian);
    if (width == 8) {
        double floating = 0.0;
        memcpy(&floating, &bits, sizeof(floating));
        return ptn_float(floating);
    }
    uint32_t narrow_bits = (uint32_t)bits;
    float narrowed = 0.0f;
    memcpy(&narrowed, &narrow_bits, sizeof(narrowed));
    return ptn_float((double)narrowed);
}

static PtnValue ptn_unpack_integer_value(
    const unsigned char *data,
    size_t width,
    int signed_value,
    int endian
) {
    uint64_t raw = ptn_unpack_read_uint(data, width, endian);
    if (signed_value) {
        return ptn_int(ptn_unpack_signed_value(raw, width));
    }
    if (width == 8) {
        return ptn_int((int64_t)raw);
    }
    return ptn_int((int64_t)raw);
}

static PtnValue ptn_internal_unpack(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand format = ptn_internal_expect_string_arg(runtime, "unpack", 1, "format", args[0], line);
    PtnStringOperand data = ptn_internal_expect_string_arg(runtime, "unpack", 2, "data", args[1], line);
    int64_t raw_offset = argc >= 3
        ? ptn_internal_expect_integer_arg(runtime, "unpack", 3, "offset", args[2], line)
        : 0;
    if (raw_offset < 0 || (uint64_t)raw_offset > (uint64_t)data.len) {
        ptn_string_operand_free(format);
        ptn_string_operand_free(data);
        ptn_throw_exception(
            runtime,
            "ValueError",
            "unpack(): Argument #3 ($offset) must be contained in argument #2 ($data)"
        );
        return ptn_null();
    }

    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    PtnArray *array = result.as.array;
    const unsigned char *bytes = (const unsigned char *)data.data;
    size_t base_offset = (size_t)raw_offset;
    size_t cursor = base_offset;
    size_t next_auto_key = 1;

    for (size_t format_offset = 0; format_offset < format.len;) {
        if (format.data[format_offset] == '/') {
            format_offset++;
            continue;
        }
        unsigned char code = (unsigned char)format.data[format_offset++];
        if (!ptn_pack_supported_spec(code) || code == 'x') {
            ptn_pack_emit_format_error(runtime, "unpack", code);
            ptn_string_operand_free(format);
            ptn_string_operand_free(data);
            return ptn_null();
        }

        int has_repeater = 0;
        int star = 0;
        size_t repeat = 1;
        if (!ptn_pack_parse_repeater(format, &format_offset, &has_repeater, &star, &repeat)) {
            ptn_string_operand_free(format);
            ptn_string_operand_free(data);
            ptn_throw_exception(runtime, "ValueError", "unpack(): Type repeater must be less than or equal to SIZE_MAX");
            return ptn_null();
        }
        size_t name_start = format_offset;
        while (format_offset < format.len && format.data[format_offset] != '/') {
            format_offset++;
        }
        const char *name = format.data + name_start;
        size_t name_len = format_offset - name_start;

        if (code == 'X') {
            if (star) {
                ptn_emit_runtime_warning(runtime, "unpack(): Type X: '*' ignored", line);
                repeat = 1;
            }
            size_t count = has_repeater ? repeat : 1;
            cursor = count > cursor - base_offset ? base_offset : cursor - count;
            continue;
        }
        if (code == '@') {
            size_t target = star ? 0 : (has_repeater ? repeat : 1);
            cursor = target > SIZE_MAX - base_offset ? data.len + 1 : base_offset + target;
            continue;
        }

        size_t width = 0;
        int signed_value = 0;
        int endian = 0;
        if (ptn_pack_integer_spec(code, &width, &signed_value, &endian)) {
            size_t available = cursor <= data.len ? data.len - cursor : 0;
            size_t count = star ? available / width : repeat;
            int suffix_named_key = name_len != 0 && count != 1;
            for (size_t i = 0; i < count; i++) {
                if (!ptn_unpack_require_input(runtime, code, cursor, data.len, width, line)) {
                    ptn_string_operand_free(format);
                    ptn_string_operand_free(data);
                    ptn_value_destroy(&result);
                    return ptn_bool(0);
                }
                PtnValue value = ptn_unpack_integer_value(bytes + cursor, width, signed_value, endian);
                ptn_unpack_set_result(array, name, name_len, suffix_named_key, i, &next_auto_key, value);
                cursor += width;
            }
            continue;
        }

        if (ptn_pack_float_spec(code, &width, &endian)) {
            size_t available = cursor <= data.len ? data.len - cursor : 0;
            size_t count = star ? available / width : repeat;
            int suffix_named_key = name_len != 0 && count != 1;
            for (size_t i = 0; i < count; i++) {
                if (!ptn_unpack_require_input(runtime, code, cursor, data.len, width, line)) {
                    ptn_string_operand_free(format);
                    ptn_string_operand_free(data);
                    ptn_value_destroy(&result);
                    return ptn_bool(0);
                }
                PtnValue value = ptn_unpack_float_value(bytes + cursor, width, endian);
                ptn_unpack_set_result(array, name, name_len, suffix_named_key, i, &next_auto_key, value);
                cursor += width;
            }
            continue;
        }

        if (code == 'a' || code == 'A' || code == 'Z') {
            size_t available = cursor <= data.len ? data.len - cursor : 0;
            size_t count = star ? available : (has_repeater ? repeat : 1);
            if (!ptn_unpack_require_input(runtime, code, cursor, data.len, count, line)) {
                ptn_string_operand_free(format);
                ptn_string_operand_free(data);
                ptn_value_destroy(&result);
                return ptn_bool(0);
            }
            PtnValue value = ptn_unpack_string_value(code, bytes + cursor, count);
            ptn_unpack_set_result(array, name, name_len, 0, 0, &next_auto_key, value);
            cursor += count;
            continue;
        }

        if (code == 'h' || code == 'H') {
            size_t available = cursor <= data.len ? data.len - cursor : 0;
            size_t nibble_count = star ? available * 2 : (has_repeater ? repeat : 1);
            if (!star && nibble_count > (size_t)INT32_MAX) {
                ptn_unpack_emit_integer_overflow(runtime, code, line);
                ptn_string_operand_free(format);
                ptn_string_operand_free(data);
                ptn_value_destroy(&result);
                return ptn_bool(0);
            }
            size_t byte_count = (nibble_count + 1) / 2;
            if (!ptn_unpack_require_input(runtime, code, cursor, data.len, byte_count, line)) {
                ptn_string_operand_free(format);
                ptn_string_operand_free(data);
                ptn_value_destroy(&result);
                return ptn_bool(0);
            }
            PtnValue value = ptn_unpack_hex_value(code, bytes + cursor, nibble_count);
            ptn_unpack_set_result(array, name, name_len, 0, 0, &next_auto_key, value);
            cursor += byte_count;
            continue;
        }
    }

    ptn_string_operand_free(format);
    ptn_string_operand_free(data);
    return result;
}

static PtnValue ptn_internal_base64_encode(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    static const char alphabet[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "base64_encode", 1, "string", args[0], line);
    size_t output_len = ((input.len + 2) / 3) * 4;
    if (output_len == SIZE_MAX) {
        ptn_abort_out_of_memory();
    }
    char *output = malloc(output_len + 1);
    if (output == NULL) {
        ptn_abort_out_of_memory();
    }

    size_t out = 0;
    for (size_t i = 0; i < input.len; i += 3) {
        unsigned int a = (unsigned char)input.data[i];
        unsigned int b = i + 1 < input.len ? (unsigned char)input.data[i + 1] : 0;
        unsigned int c = i + 2 < input.len ? (unsigned char)input.data[i + 2] : 0;
        output[out++] = alphabet[(a >> 2) & 0x3f];
        output[out++] = alphabet[((a << 4) | (b >> 4)) & 0x3f];
        output[out++] = i + 1 < input.len ? alphabet[((b << 2) | (c >> 6)) & 0x3f] : '=';
        output[out++] = i + 2 < input.len ? alphabet[c & 0x3f] : '=';
    }
    output[out] = '\0';
    ptn_string_operand_free(input);
    return ptn_owned_string_len(output, out);
}

static int ptn_base64_decode_value(unsigned char byte) {
    if (byte >= 'A' && byte <= 'Z') {
        return (int)(byte - 'A');
    }
    if (byte >= 'a' && byte <= 'z') {
        return (int)(byte - 'a') + 26;
    }
    if (byte >= '0' && byte <= '9') {
        return (int)(byte - '0') + 52;
    }
    if (byte == '+') {
        return 62;
    }
    if (byte == '/') {
        return 63;
    }
    return -1;
}

static int ptn_base64_is_space(unsigned char byte) {
    return byte == ' ' || byte == '\t' || byte == '\n' || byte == '\r' || byte == '\f';
}

static PtnValue ptn_internal_base64_decode(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "base64_decode", 1, "string", args[0], line);
    int strict = argc >= 2 && ptn_is_truthy(args[1]);

    if (input.len > SIZE_MAX / sizeof(int)) {
        ptn_abort_out_of_memory();
    }
    int *values = input.len == 0 ? NULL : malloc(input.len * sizeof(int));
    if (input.len != 0 && values == NULL) {
        ptn_abort_out_of_memory();
    }

    size_t value_len = 0;
    size_t padding_len = 0;
    int saw_padding = 0;
    int invalid = 0;
    for (size_t i = 0; i < input.len; i++) {
        unsigned char byte = (unsigned char)input.data[i];
        if (ptn_base64_is_space(byte)) {
            continue;
        }

        int value = ptn_base64_decode_value(byte);
        if (value >= 0) {
            if (strict && saw_padding) {
                invalid = 1;
                break;
            }
            values[value_len++] = value;
            continue;
        }

        if (byte == '=') {
            if (strict) {
                saw_padding = 1;
                padding_len++;
            }
            continue;
        }

        if (strict) {
            invalid = 1;
            break;
        }
    }

    if (!invalid && strict) {
        size_t significant_len = value_len + padding_len;
        if (padding_len > 0) {
            if (padding_len > 2 || significant_len % 4 != 0 ||
                (padding_len == 1 && value_len % 4 != 3) ||
                (padding_len == 2 && value_len % 4 != 2)) {
                invalid = 1;
            }
        } else if (value_len % 4 == 1) {
            invalid = 1;
        }
    }

    if (invalid) {
        free(values);
        ptn_string_operand_free(input);
        return ptn_bool(0);
    }

    char *output = malloc(input.len + 1);
    if (output == NULL) {
        ptn_abort_out_of_memory();
    }

    size_t out = 0;
    size_t i = 0;
    while (i + 4 <= value_len) {
        output[out++] = (char)((values[i] << 2) | (values[i + 1] >> 4));
        output[out++] = (char)(((values[i + 1] & 0x0f) << 4) | (values[i + 2] >> 2));
        output[out++] = (char)(((values[i + 2] & 0x03) << 6) | values[i + 3]);
        i += 4;
    }
    size_t remainder = value_len - i;
    if (remainder >= 2) {
        output[out++] = (char)((values[i] << 2) | (values[i + 1] >> 4));
    }
    if (remainder >= 3) {
        output[out++] = (char)(((values[i + 1] & 0x0f) << 4) | (values[i + 2] >> 2));
    }

    output[out] = '\0';
    free(values);
    ptn_string_operand_free(input);
    return ptn_owned_string_len(output, out);
}

static int ptn_text_operand_ascii_case_equal(PtnStringOperand value, const char *literal) {
    size_t literal_len = strlen(literal);
    if (value.len != literal_len) {
        return 0;
    }
    for (size_t i = 0; i < literal_len; i++) {
        if (tolower((unsigned char)value.data[i]) != tolower((unsigned char)literal[i])) {
            return 0;
        }
    }
    return 1;
}

