static int ptn_mb_numeric_entity_map_allows(PtnValue map_value, uint32_t cp) {
    PtnValue resolved = ptn_value_deref(map_value);
    if (resolved.type != PTN_ARRAY) {
        return 1;
    }
    for (size_t i = 0; i + 3 < resolved.as.array->len; i += 4) {
        int64_t start = ptn_value_to_integer(resolved.as.array->entries[i].value);
        int64_t end = ptn_value_to_integer(resolved.as.array->entries[i + 1].value);
        if ((int64_t)cp >= start && (int64_t)cp <= end) {
            return 1;
        }
    }
    return 0;
}

static PtnValue ptn_internal_mb_encode_numericentity(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "mb_encode_numericentity", 1, "string", args[0], line);
    const char *encoding = argc >= 3
        ? ptn_mb_encoding_from_value(runtime, "mb_encode_numericentity", 3, "encoding", args[2], line, ptn_mb_current_internal_encoding(runtime), 1)
        : ptn_mb_current_internal_encoding(runtime);
    int hex = argc >= 4 && ptn_is_truthy(args[3]);
    size_t utf8_len = 0;
    char *utf8 = encoding == NULL ? ptn_duplicate_string_len(input.data, input.len) : ptn_mb_operand_to_utf8(input, encoding, &utf8_len);
    if (encoding == NULL) {
        utf8_len = input.len;
    }
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    size_t offset = 0;
    while (offset < utf8_len) {
        size_t before = offset;
        uint32_t cp = 0;
        ptn_mb_utf8_decode_one(utf8, utf8_len, &offset, &cp);
        if (ptn_mb_numeric_entity_map_allows(args[1], cp)) {
            if (hex) {
                ptn_string_buffer_append_format(&output, "&#x%X;", (unsigned int)cp);
            } else {
                ptn_string_buffer_append_format(&output, "&#%u;", (unsigned int)cp);
            }
        } else {
            ptn_string_buffer_append_len(&output, utf8 + before, offset - before);
        }
    }
    free(utf8);
    ptn_string_operand_free(input);
    return ptn_owned_string_len(output.data, output.len);
}

static PtnValue ptn_internal_mb_decode_numericentity(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "mb_decode_numericentity", 1, "string", args[0], line);
    const char *encoding = argc >= 3
        ? ptn_mb_encoding_from_value(runtime, "mb_decode_numericentity", 3, "encoding", args[2], line, ptn_mb_current_internal_encoding(runtime), 1)
        : ptn_mb_current_internal_encoding(runtime);
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    for (size_t i = 0; i < input.len; i++) {
        if (input.data[i] == '&' && i + 3 < input.len && input.data[i + 1] == '#') {
            size_t cursor = i + 2;
            int hex = 0;
            if (cursor < input.len && (input.data[cursor] == 'x' || input.data[cursor] == 'X')) {
                hex = 1;
                cursor++;
            }
            uint32_t cp = 0;
            size_t digit_start = cursor;
            while (cursor < input.len && input.data[cursor] != ';') {
                int digit = hex ? ptn_hex_nibble((unsigned char)input.data[cursor]) :
                    (isdigit((unsigned char)input.data[cursor]) ? input.data[cursor] - '0' : -1);
                if (digit < 0) {
                    break;
                }
                cp = (uint32_t)(cp * (hex ? 16 : 10) + (uint32_t)digit);
                cursor++;
            }
            if (cursor < input.len && input.data[cursor] == ';' && cursor > digit_start && ptn_mb_numeric_entity_map_allows(args[1], cp)) {
                ptn_mb_utf8_append_codepoint(&output, cp);
                i = cursor;
                continue;
            }
        }
        ptn_string_buffer_append_char(&output, input.data[i]);
    }
    ptn_string_operand_free(input);
    return ptn_mb_string_from_utf8(output.data, output.len, encoding == NULL ? "UTF-8" : encoding);
}

static PtnValue ptn_internal_mb_convert_variables(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    const char *to_encoding = ptn_mb_encoding_from_value(runtime, "mb_convert_variables", 1, "to_encoding", args[0], line, NULL, 0);
    const char *from_encoding = argc >= 2
        ? ptn_mb_encoding_list_first_from_value(runtime, "mb_convert_variables", 2, "from_encoding", args[1], line, ptn_mb_current_internal_encoding(runtime))
        : ptn_mb_current_internal_encoding(runtime);
    if (to_encoding == NULL || from_encoding == NULL) {
        return ptn_bool(0);
    }
    for (size_t i = 2; i < argc; i++) {
        if (args[i].type != PTN_REFERENCE) {
            continue;
        }
        PtnValue current = ptn_value_deref(args[i]);
        if (current.type != PTN_STRING) {
            continue;
        }
        size_t out_len = 0;
        char *out = ptn_mb_iconv_convert_alloc((const char *)current.as.string.data, current.as.string.len, from_encoding, to_encoding, &out_len);
        PtnValue assigned = ptn_owned_string_len(out, out_len);
        ptn_reference_assign(runtime, args[i].as.reference, assigned);
        ptn_value_destroy(&assigned);
    }
    return ptn_string(to_encoding);
}

static int ptn_ascii_is_letter(unsigned char byte) {
    return (byte >= 'A' && byte <= 'Z') || (byte >= 'a' && byte <= 'z');
}

static unsigned char ptn_ascii_upper(unsigned char byte) {
    if (byte >= 'a' && byte <= 'z') {
        return (unsigned char)(byte - ('a' - 'A'));
    }
    return byte;
}

static char ptn_soundex_code(unsigned char byte) {
    switch (ptn_ascii_upper(byte)) {
        case 'B':
        case 'F':
        case 'P':
        case 'V':
            return '1';
        case 'C':
        case 'G':
        case 'J':
        case 'K':
        case 'Q':
        case 'S':
        case 'X':
        case 'Z':
            return '2';
        case 'D':
        case 'T':
            return '3';
        case 'L':
            return '4';
        case 'M':
        case 'N':
            return '5';
        case 'R':
            return '6';
        default:
            return '\0';
    }
}

static int ptn_soundex_resets_previous(unsigned char byte) {
    switch (ptn_ascii_upper(byte)) {
        case 'A':
        case 'E':
        case 'I':
        case 'O':
        case 'U':
        case 'Y':
        case 'H':
        case 'W':
            return 1;
        default:
            return 0;
    }
}

static PtnValue ptn_internal_soundex(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand string = ptn_internal_expect_string_arg(runtime, "soundex", 1, "string", args[0], line);
    char *result = malloc(5);
    if (result == NULL) {
        ptn_abort_out_of_memory();
    }
    result[0] = '0';
    result[1] = '0';
    result[2] = '0';
    result[3] = '0';
    result[4] = '\0';

    size_t first = 0;
    while (first < string.len && !ptn_ascii_is_letter((unsigned char)string.data[first])) {
        first++;
    }
    if (first == string.len) {
        ptn_string_operand_free(string);
        return ptn_owned_string_len(result, 4);
    }

    result[0] = (char)ptn_ascii_upper((unsigned char)string.data[first]);
    char previous = ptn_soundex_code((unsigned char)string.data[first]);
    size_t output_len = 1;
    for (size_t i = first + 1; i < string.len && output_len < 4; i++) {
        unsigned char byte = (unsigned char)string.data[i];
        char code = ptn_soundex_code(byte);
        if (code == '\0') {
            if (ptn_soundex_resets_previous(byte)) {
                previous = '\0';
            }
            continue;
        }
        if (code != previous) {
            result[output_len++] = code;
        }
        previous = code;
    }

    ptn_string_operand_free(string);
    return ptn_owned_string_len(result, 4);
}

static void ptn_utf8_emit_deprecation(PtnRuntime *runtime, const char *function_name, size_t line) {
    char message[128];
    int written = snprintf(
        message,
        sizeof(message),
        "Function %s() is deprecated since 8.2, visit the php.net documentation for various alternatives",
        function_name
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_emit_deprecation(&runtime->diagnostics, message, line);
}

static PtnValue ptn_internal_utf8_encode(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    ptn_utf8_emit_deprecation(runtime, "utf8_encode", line);
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "utf8_encode", 1, "string", args[0], line);
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    for (size_t i = 0; i < input.len; i++) {
        unsigned char byte = (unsigned char)input.data[i];
        if (byte < 0x80) {
            ptn_string_buffer_append_char(&output, (char)byte);
        } else {
            ptn_string_buffer_append_char(&output, (char)(0xc0 | (byte >> 6)));
            ptn_string_buffer_append_char(&output, (char)(0x80 | (byte & 0x3f)));
        }
    }
    ptn_string_operand_free(input);
    return ptn_owned_string_len(output.data, output.len);
}

static int ptn_utf8_decode_continuation(unsigned char byte) {
    return (byte & 0xc0) == 0x80;
}

static PtnValue ptn_internal_utf8_decode(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    ptn_utf8_emit_deprecation(runtime, "utf8_decode", line);
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "utf8_decode", 1, "string", args[0], line);
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    for (size_t i = 0; i < input.len;) {
        unsigned char byte = (unsigned char)input.data[i];
        if (byte < 0x80) {
            ptn_string_buffer_append_char(&output, (char)byte);
            i++;
            continue;
        }

        size_t needed = 0;
        uint32_t codepoint = 0;
        uint32_t minimum = 0;
        if (byte >= 0xc2 && byte <= 0xdf) {
            needed = 1;
            codepoint = (uint32_t)(byte & 0x1f);
            minimum = 0x80;
        } else if (byte >= 0xe0 && byte <= 0xef) {
            needed = 2;
            codepoint = (uint32_t)(byte & 0x0f);
            minimum = 0x800;
        } else if (byte >= 0xf0 && byte <= 0xf4) {
            needed = 3;
            codepoint = (uint32_t)(byte & 0x07);
            minimum = 0x10000;
        } else {
            ptn_string_buffer_append_char(&output, '?');
            i++;
            continue;
        }

        size_t j = 0;
        int valid = 1;
        for (; j < needed; j++) {
            if (i + 1 + j >= input.len || !ptn_utf8_decode_continuation((unsigned char)input.data[i + 1 + j])) {
                valid = 0;
                break;
            }
            codepoint = (codepoint << 6) | (uint32_t)(input.data[i + 1 + j] & 0x3f);
        }
        if (!valid) {
            ptn_string_buffer_append_char(&output, '?');
            i += 1 + j;
            continue;
        }
        if (
            codepoint < minimum ||
            codepoint > 0x10ffff ||
            (codepoint >= 0xd800 && codepoint <= 0xdfff) ||
            codepoint > 0xff
        ) {
            ptn_string_buffer_append_char(&output, '?');
        } else {
            ptn_string_buffer_append_char(&output, (char)(unsigned char)codepoint);
        }
        i += needed + 1;
    }
    ptn_string_operand_free(input);
    return ptn_owned_string_len(output.data, output.len);
}

static int ptn_string_is_ascii_alnum(PtnStringOperand string) {
    for (size_t i = 0; i < string.len; i++) {
        unsigned char byte = (unsigned char)string.data[i];
        if (!((byte >= '0' && byte <= '9') ||
              (byte >= 'A' && byte <= 'Z') ||
              (byte >= 'a' && byte <= 'z'))) {
            return 0;
        }
    }
    return 1;
}

static void ptn_throw_string_incdec_empty(PtnRuntime *runtime, const char *function_name) {
    char message[96];
    int written = snprintf(
        message,
        sizeof(message),
        "%s(): Argument #1 ($string) must not be empty",
        function_name
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "ValueError", message);
}

static void ptn_throw_string_incdec_invalid(PtnRuntime *runtime, const char *function_name) {
    char message[128];
    int written = snprintf(
        message,
        sizeof(message),
        "%s(): Argument #1 ($string) must be composed only of alphanumeric ASCII characters",
        function_name
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "ValueError", message);
}

static void ptn_throw_string_decrement_range(PtnRuntime *runtime, PtnStringOperand string) {
    int needed = snprintf(
        NULL,
        0,
        "str_decrement(): Argument #1 ($string) \"%.*s\" is out of decrement range",
        (int)string.len,
        string.data
    );
    if (needed < 0) {
        ptn_abort_out_of_memory();
    }
    char *message = malloc((size_t)needed + 1);
    if (message == NULL) {
        ptn_abort_out_of_memory();
    }
    snprintf(
        message,
        (size_t)needed + 1,
        "str_decrement(): Argument #1 ($string) \"%.*s\" is out of decrement range",
        (int)string.len,
        string.data
    );
    ptn_throw_exception_owned_message(runtime, "ValueError", message);
}

static PtnValue ptn_internal_str_increment(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand string = ptn_internal_expect_string_arg(runtime, "str_increment", 1, "string", args[0], line);
    if (string.len == 0) {
        ptn_throw_string_incdec_empty(runtime, "str_increment");
        ptn_string_operand_free(string);
        return ptn_null();
    }
    if (!ptn_string_is_ascii_alnum(string)) {
        ptn_throw_string_incdec_invalid(runtime, "str_increment");
        ptn_string_operand_free(string);
        return ptn_null();
    }

    char *result = ptn_duplicate_string_len(string.data, string.len);
    size_t position = string.len - 1;
    int carry = 0;
    do {
        char byte = result[position];
        if (byte != 'z' && byte != 'Z' && byte != '9') {
            result[position]++;
            carry = 0;
        } else {
            carry = 1;
            if (byte == '9') {
                result[position] = '0';
            } else {
                result[position] = (char)(byte - 25);
            }
        }
    } while (carry && position-- > 0);

    if (carry) {
        char *expanded = malloc(string.len + 2);
        if (expanded == NULL) {
            ptn_abort_out_of_memory();
        }
        memcpy(expanded + 1, result, string.len);
        expanded[string.len + 1] = '\0';
        expanded[0] = result[0] == '0' ? '1' : result[0];
        free(result);
        ptn_string_operand_free(string);
        return ptn_owned_string_len(expanded, string.len + 1);
    }

    ptn_string_operand_free(string);
    return ptn_owned_string_len(result, strlen(result));
}

static PtnValue ptn_internal_str_decrement(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand string = ptn_internal_expect_string_arg(runtime, "str_decrement", 1, "string", args[0], line);
    if (string.len == 0) {
        ptn_throw_string_incdec_empty(runtime, "str_decrement");
        ptn_string_operand_free(string);
        return ptn_null();
    }
    if (!ptn_string_is_ascii_alnum(string)) {
        ptn_throw_string_incdec_invalid(runtime, "str_decrement");
        ptn_string_operand_free(string);
        return ptn_null();
    }
    if (string.data[0] == '0') {
        ptn_throw_string_decrement_range(runtime, string);
        ptn_string_operand_free(string);
        return ptn_null();
    }

    char *result = ptn_duplicate_string_len(string.data, string.len);
    size_t position = string.len - 1;
    int carry = 0;
    do {
        char byte = result[position];
        if (byte != 'a' && byte != 'A' && byte != '0') {
            result[position]--;
            carry = 0;
        } else {
            carry = 1;
            if (byte == '0') {
                result[position] = '9';
            } else {
                result[position] = (char)(byte + 25);
            }
        }
    } while (carry && position-- > 0);

    if (carry || (result[0] == '0' && string.len > 1)) {
        if (string.len == 1) {
            free(result);
            ptn_throw_string_decrement_range(runtime, string);
            ptn_string_operand_free(string);
            return ptn_null();
        }
        char *trimmed = malloc(string.len);
        if (trimmed == NULL) {
            ptn_abort_out_of_memory();
        }
        memcpy(trimmed, result + 1, string.len - 1);
        trimmed[string.len - 1] = '\0';
        free(result);
        ptn_string_operand_free(string);
        return ptn_owned_string_len(trimmed, string.len - 1);
    }

    ptn_string_operand_free(string);
    return ptn_owned_string_len(result, strlen(result));
}

static int ptn_metaphone_code(unsigned char byte) {
    switch ((unsigned char)toupper(byte)) {
        case 'A':
        case 'O':
        case 'U':
            return 1;
        case 'E':
        case 'I':
            return 9;
        case 'F':
        case 'J':
        case 'L':
        case 'M':
        case 'N':
        case 'R':
            return 2;
        case 'C':
        case 'G':
        case 'P':
        case 'S':
        case 'T':
            return 4;
        case 'Y':
            return 8;
        case 'B':
        case 'D':
        case 'H':
            return 16;
        default:
            return 0;
    }
}

static int ptn_metaphone_is_vowel(char byte) {
    return (ptn_metaphone_code((unsigned char)byte) & 1) != 0;
}

static int ptn_metaphone_affects_h(char byte) {
    return (ptn_metaphone_code((unsigned char)byte) & 4) != 0;
}

static int ptn_metaphone_makes_soft(char byte) {
    return (ptn_metaphone_code((unsigned char)byte) & 8) != 0;
}

static int ptn_metaphone_no_gh_to_f(char byte) {
    return (ptn_metaphone_code((unsigned char)byte) & 16) != 0;
}

static char ptn_metaphone_read(const char *word, size_t len, size_t index) {
    if (index >= len) {
        return '\0';
    }
    return (char)toupper((unsigned char)word[index]);
}

static int ptn_metaphone_append(char **buffer, size_t *len, size_t *capacity, char byte) {
    if (*len + 1 >= *capacity) {
        size_t new_capacity = *capacity == 0 ? 16 : *capacity * 2;
        char *grown = realloc(*buffer, new_capacity);
        if (grown == NULL) {
            ptn_abort_out_of_memory();
        }
        *buffer = grown;
        *capacity = new_capacity;
    }
    (*buffer)[(*len)++] = byte;
    (*buffer)[*len] = '\0';
    return 1;
}

static char *ptn_metaphone_string(const char *word, size_t word_len, int64_t max_phonemes, size_t *output_len_out) {
    size_t w_idx = 0;
    size_t p_idx = 0;
    size_t capacity = max_phonemes > 0 && max_phonemes < 1024 ? (size_t)max_phonemes + 3 : word_len * 2 + 3;
    if (capacity < 16) {
        capacity = 16;
    }
    char *output = calloc(capacity, 1);
    if (output == NULL) {
        ptn_abort_out_of_memory();
    }

    char curr_letter = '\0';
    while (w_idx < word_len) {
        curr_letter = word[w_idx];
        if (isalpha((unsigned char)curr_letter)) {
            break;
        }
        w_idx++;
    }
    if (w_idx >= word_len) {
        *output_len_out = 0;
        return output;
    }

    curr_letter = ptn_metaphone_read(word, word_len, w_idx);
    switch (curr_letter) {
        case 'A':
            if (ptn_metaphone_read(word, word_len, w_idx + 1) == 'E') {
                ptn_metaphone_append(&output, &p_idx, &capacity, 'E');
                w_idx += 2;
            } else {
                ptn_metaphone_append(&output, &p_idx, &capacity, 'A');
                w_idx++;
            }
            break;
        case 'G':
        case 'K':
        case 'P':
            if (ptn_metaphone_read(word, word_len, w_idx + 1) == 'N') {
                ptn_metaphone_append(&output, &p_idx, &capacity, 'N');
                w_idx += 2;
            }
            break;
        case 'W': {
            char next = ptn_metaphone_read(word, word_len, w_idx + 1);
            if (next == 'R') {
                ptn_metaphone_append(&output, &p_idx, &capacity, 'R');
                w_idx += 2;
            } else if (next == 'H' || ptn_metaphone_is_vowel(next)) {
                ptn_metaphone_append(&output, &p_idx, &capacity, 'W');
                w_idx += 2;
            }
            break;
        }
        case 'X':
            ptn_metaphone_append(&output, &p_idx, &capacity, 'S');
            w_idx++;
            break;
        case 'E':
        case 'I':
        case 'O':
        case 'U':
            ptn_metaphone_append(&output, &p_idx, &capacity, curr_letter);
            w_idx++;
            break;
        default:
            break;
    }

    for (; w_idx < word_len && (max_phonemes == 0 || p_idx < (size_t)max_phonemes); w_idx++) {
        curr_letter = word[w_idx];
        if (!isalpha((unsigned char)curr_letter)) {
            continue;
        }
        curr_letter = ptn_metaphone_read(word, word_len, w_idx);
        char prev_letter = w_idx > 0 ? ptn_metaphone_read(word, word_len, w_idx - 1) : '\0';
        if (curr_letter == prev_letter && curr_letter != 'C') {
            continue;
        }

        size_t skip = 0;
        switch (curr_letter) {
            case 'B':
                if (prev_letter != 'M') {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'B');
                }
                break;
            case 'C': {
                char next = ptn_metaphone_read(word, word_len, w_idx + 1);
                if (ptn_metaphone_makes_soft(next)) {
                    if (next == 'I' && ptn_metaphone_read(word, word_len, w_idx + 2) == 'A') {
                        ptn_metaphone_append(&output, &p_idx, &capacity, 'X');
                    } else if (prev_letter != 'S') {
                        ptn_metaphone_append(&output, &p_idx, &capacity, 'S');
                    }
                } else if (next == 'H') {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'X');
                    skip++;
                } else {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'K');
                }
                break;
            }
            case 'D':
                if (ptn_metaphone_read(word, word_len, w_idx + 1) == 'G' &&
                    ptn_metaphone_makes_soft(ptn_metaphone_read(word, word_len, w_idx + 2))) {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'J');
                    skip++;
                } else {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'T');
                }
                break;
            case 'G': {
                char next = ptn_metaphone_read(word, word_len, w_idx + 1);
                if (next == 'H') {
                    char look3 = w_idx >= 3 ? ptn_metaphone_read(word, word_len, w_idx - 3) : '\0';
                    char look4 = w_idx >= 4 ? ptn_metaphone_read(word, word_len, w_idx - 4) : '\0';
                    if (!ptn_metaphone_no_gh_to_f(look3) && look4 != 'H') {
                        ptn_metaphone_append(&output, &p_idx, &capacity, 'F');
                        skip++;
                    }
                } else if (next == 'N') {
                    char after = ptn_metaphone_read(word, word_len, w_idx + 2);
                    if (!(after == '\0' || !isalpha((unsigned char)after) ||
                          (after == 'E' && ptn_metaphone_read(word, word_len, w_idx + 3) == 'D'))) {
                        ptn_metaphone_append(&output, &p_idx, &capacity, 'K');
                    }
                } else if (ptn_metaphone_makes_soft(next) && prev_letter != 'G') {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'J');
                } else {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'K');
                }
                break;
            }
            case 'H':
                if (ptn_metaphone_is_vowel(ptn_metaphone_read(word, word_len, w_idx + 1)) &&
                    !ptn_metaphone_affects_h(prev_letter)) {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'H');
                }
                break;
            case 'K':
                if (prev_letter != 'C') {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'K');
                }
                break;
            case 'P':
                ptn_metaphone_append(
                    &output,
                    &p_idx,
                    &capacity,
                    ptn_metaphone_read(word, word_len, w_idx + 1) == 'H' ? 'F' : 'P'
                );
                break;
            case 'Q':
                ptn_metaphone_append(&output, &p_idx, &capacity, 'K');
                break;
            case 'S': {
                char next = ptn_metaphone_read(word, word_len, w_idx + 1);
                char after = ptn_metaphone_read(word, word_len, w_idx + 2);
                if (next == 'I' && (after == 'O' || after == 'A')) {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'X');
                } else if (next == 'H') {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'X');
                    skip++;
                } else {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'S');
                }
                break;
            }
            case 'T': {
                char next = ptn_metaphone_read(word, word_len, w_idx + 1);
                char after = ptn_metaphone_read(word, word_len, w_idx + 2);
                if (next == 'I' && (after == 'O' || after == 'A')) {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'X');
                } else if (next == 'H') {
                    ptn_metaphone_append(&output, &p_idx, &capacity, '0');
                    skip++;
                } else if (!(next == 'C' && after == 'H')) {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'T');
                }
                break;
            }
            case 'V':
                ptn_metaphone_append(&output, &p_idx, &capacity, 'F');
                break;
            case 'W':
                if (ptn_metaphone_is_vowel(ptn_metaphone_read(word, word_len, w_idx + 1))) {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'W');
                }
                break;
            case 'X':
                ptn_metaphone_append(&output, &p_idx, &capacity, 'K');
                ptn_metaphone_append(&output, &p_idx, &capacity, 'S');
                break;
            case 'Y':
                if (ptn_metaphone_is_vowel(ptn_metaphone_read(word, word_len, w_idx + 1))) {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'Y');
                }
                break;
            case 'Z':
                ptn_metaphone_append(&output, &p_idx, &capacity, 'S');
                break;
            case 'F':
            case 'J':
            case 'L':
            case 'M':
            case 'N':
            case 'R':
                ptn_metaphone_append(&output, &p_idx, &capacity, curr_letter);
                break;
            default:
                break;
        }
        w_idx += skip;
    }

    output[p_idx] = '\0';
    *output_len_out = p_idx;
    return output;
}

static PtnValue ptn_internal_metaphone(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand string = ptn_internal_expect_string_arg(runtime, "metaphone", 1, "string", args[0], line);
    int64_t max_phonemes = 0;
    if (argc >= 2) {
        max_phonemes = ptn_internal_expect_integer_arg(runtime, "metaphone", 2, "max_phonemes", args[1], line);
        if (max_phonemes < 0) {
            ptn_throw_exception(
                runtime,
                "ValueError",
                "metaphone(): Argument #2 ($max_phonemes) must be greater than or equal to 0"
            );
            ptn_string_operand_free(string);
            return ptn_null();
        }
    }

    size_t output_len = 0;
    char *output = ptn_metaphone_string(string.data, string.len, max_phonemes, &output_len);
    ptn_string_operand_free(string);
    return ptn_owned_string_len(output, output_len);
}

static int ptn_hebrev_is_hebrew(unsigned char byte) {
    return byte >= 224 && byte <= 250;
}

static int ptn_hebrev_is_blank(unsigned char byte) {
    return byte == ' ' || byte == '\t';
}

static int ptn_hebrev_is_newline(unsigned char byte) {
    return byte == '\n' || byte == '\r';
}

static char ptn_hebrev_flip_punctuation(char byte) {
    switch (byte) {
        case '(':
            return ')';
        case ')':
            return '(';
        case '[':
            return ']';
        case ']':
            return '[';
        case '{':
            return '}';
        case '}':
            return '{';
        case '<':
            return '>';
        case '>':
            return '<';
        case '\\':
            return '/';
        case '/':
            return '\\';
        default:
            return byte;
    }
}

static char *ptn_hebrev_string(const char *input, size_t len, int64_t max_chars, size_t *output_len_out) {
    char *hebrew = malloc(len + 1);
    char *broken = malloc(len + 1);
    if (hebrew == NULL || broken == NULL) {
        ptn_abort_out_of_memory();
    }

    size_t block_start = 0;
    size_t block_end = 0;
    size_t block_type = ptn_hebrev_is_hebrew((unsigned char)input[0]) ? 2 : 1;
    size_t target = len;
    hebrew[target] = '\0';

    while (1) {
        if (block_type == 2) {
            while (block_end < len - 1) {
                unsigned char next = (unsigned char)input[block_end + 1];
                if (!(ptn_hebrev_is_hebrew(next) || ptn_hebrev_is_blank(next) || ispunct(next) || next == '\n')) {
                    break;
                }
                block_end++;
            }
            for (size_t i = block_start; i <= block_end; i++) {
                hebrew[--target] = ptn_hebrev_flip_punctuation(input[i]);
            }
            block_type = 1;
        } else {
            while (block_end < len - 1) {
                unsigned char next = (unsigned char)input[block_end + 1];
                if (ptn_hebrev_is_hebrew(next) || next == '\n') {
                    break;
                }
                block_end++;
            }
            while ((ptn_hebrev_is_blank((unsigned char)input[block_end]) ||
                    ispunct((unsigned char)input[block_end])) &&
                   input[block_end] != '/' &&
                   input[block_end] != '-' &&
                   block_end > block_start) {
                block_end--;
            }
            size_t i = block_end + 1;
            while (i > block_start) {
                i--;
                hebrew[--target] = input[i];
            }
            block_type = 2;
        }
        block_start = block_end + 1;
        if (block_end >= len - 1) {
            break;
        }
        block_end = block_start;
    }

    size_t begin = len - 1;
    size_t end = len - 1;
    size_t out = 0;
    while (1) {
        int64_t char_count = 0;
        while ((max_chars == 0 || (max_chars > 0 && char_count < max_chars)) && begin > 0) {
            char_count++;
            begin--;
            if (ptn_hebrev_is_newline((unsigned char)hebrew[begin])) {
                while (begin > 0 && ptn_hebrev_is_newline((unsigned char)hebrew[begin - 1])) {
                    begin--;
                    char_count++;
                }
                break;
            }
        }
        if (max_chars >= 0 && char_count == max_chars) {
            int64_t new_char_count = char_count;
            size_t new_begin = begin;
            while (new_char_count > 0) {
                if (ptn_hebrev_is_blank((unsigned char)hebrew[new_begin]) ||
                    ptn_hebrev_is_newline((unsigned char)hebrew[new_begin])) {
                    break;
                }
                new_begin++;
                new_char_count--;
            }
            if (new_char_count > 0) {
                begin = new_begin;
            }
        }

        size_t orig_begin = begin;
        if (ptn_hebrev_is_blank((unsigned char)hebrew[begin])) {
            hebrew[begin] = '\n';
        }
        while (begin <= end && ptn_hebrev_is_newline((unsigned char)hebrew[begin])) {
            begin++;
        }
        for (size_t i = begin; i <= end; i++) {
            broken[out++] = hebrew[i];
        }
        for (size_t i = orig_begin; i <= end && ptn_hebrev_is_newline((unsigned char)hebrew[i]); i++) {
            broken[out++] = hebrew[i];
        }

        begin = orig_begin;
        if (begin == 0) {
            broken[out] = '\0';
            break;
        }
        begin--;
        end = begin;
    }

    free(hebrew);
    *output_len_out = out;
    return broken;
}

static PtnValue ptn_internal_hebrev(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand string = ptn_internal_expect_string_arg(runtime, "hebrev", 1, "string", args[0], line);
    if (string.len == 0) {
        ptn_string_operand_free(string);
        return ptn_string("");
    }
    int64_t max_chars = argc >= 2
        ? ptn_internal_expect_integer_arg(runtime, "hebrev", 2, "max_chars", args[1], line)
        : 0;
    size_t output_len = 0;
    char *output = ptn_hebrev_string(string.data, string.len, max_chars, &output_len);
    ptn_string_operand_free(string);
    return ptn_owned_string_len(output, output_len);
}

static PtnValue ptn_internal_set_time_limit(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)argc;
    (void)line;
    (void)ptn_value_to_integer(args[0]);
    return ptn_bool(1);
}

static PtnValue ptn_internal_sleep(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    int64_t seconds = ptn_internal_expect_integer_arg(runtime, "sleep", 1, "seconds", args[0], line);
    if (seconds < 0) {
        ptn_throw_exception(runtime, "ValueError", "sleep(): Argument #1 ($seconds) must be greater than or equal to 0");
        return ptn_null();
    }
    while (seconds > 0) {
        unsigned int chunk = seconds > (int64_t)UINT_MAX ? UINT_MAX : (unsigned int)seconds;
        unsigned int remaining = sleep(chunk);
        if (remaining != 0) {
            return ptn_int((int64_t)remaining + (seconds - (int64_t)chunk));
        }
        seconds -= (int64_t)chunk;
    }
    return ptn_int(0);
}

static PtnValue ptn_internal_usleep(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    int64_t microseconds = ptn_internal_expect_integer_arg(runtime, "usleep", 1, "microseconds", args[0], line);
    if (microseconds < 0) {
        ptn_throw_exception(runtime, "ValueError", "usleep(): Argument #1 ($microseconds) must be greater than or equal to 0");
        return ptn_null();
    }
    if (microseconds > 0) {
        struct timespec requested;
        requested.tv_sec = (time_t)(microseconds / 1000000);
        requested.tv_nsec = (long)((microseconds % 1000000) * 1000);
        while (nanosleep(&requested, &requested) != 0) {
            if (errno != EINTR) {
                break;
            }
        }
    }
    return ptn_null();
}

static int64_t ptn_synthetic_memory_peak_usage = 1048576;

static PtnValue ptn_internal_memory_get_usage(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)line;
    if (argc >= 1) {
        (void)ptn_is_truthy(args[0]);
    }
    return ptn_int(1048576);
}

static PtnValue ptn_internal_memory_get_peak_usage(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)line;
    if (argc >= 1) {
        (void)ptn_is_truthy(args[0]);
    }
    if (ptn_synthetic_memory_peak_usage <= INT64_MAX - 1024) {
        ptn_synthetic_memory_peak_usage += 1024;
    }
    return ptn_int(ptn_synthetic_memory_peak_usage);
}

static PtnValue ptn_internal_memory_reset_peak_usage(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)argc;
    (void)args;
    (void)line;
    ptn_synthetic_memory_peak_usage = 1048576;
    return ptn_null();
}

static PtnValue ptn_internal_gc_collect_cycles(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    PtnRuntime *root = ptn_runtime_root(runtime);
    if (root == NULL) {
        root = runtime;
    }
    root->gc_running = 1;
    size_t weak_map_cycles = ptn_runtime_collect_weak_map_cycles(runtime);
    int64_t collected = 0;
    if (weak_map_cycles > 0) {
        if (weak_map_cycles > (size_t)INT64_MAX) {
            ptn_abort_out_of_memory();
        }
        collected = (int64_t)weak_map_cycles;
    } else if (ptn_intl_cycle_collection_pending) {
        ptn_intl_cycle_collection_pending = 0;
        collected = 1;
    }
    if (collected > 0) {
        root->gc_runs++;
        root->gc_collected += (size_t)collected;
        root->gc_roots = 0;
    }
    root->gc_running = 0;
    return ptn_int(collected);
}

static PtnValue ptn_internal_gc_status(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    PtnRuntime *root = ptn_runtime_root(runtime);
    if (root == NULL) {
        root = runtime;
    }
    PtnValue status = ptn_array_from_literal_entries(0, NULL);
    ptn_array_set_entry(status.as.array, ptn_array_string_key("running"), ptn_bool(root->gc_running));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("protected"), ptn_bool(0));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("full"), ptn_bool(0));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("runs"), ptn_int((int64_t)root->gc_runs));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("collected"), ptn_int((int64_t)root->gc_collected));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("threshold"), ptn_int(10001));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("buffer_size"), ptn_int(16384));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("roots"), ptn_int((int64_t)root->gc_roots));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("application_time"), ptn_float(0.0));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("collector_time"), ptn_float(0.0));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("destructor_time"), ptn_float(0.0));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("free_time"), ptn_float(0.0));
    return status;
}

typedef struct {
    const char *data;
    size_t len;
} PtnIniText;

static PtnIniText ptn_ini_text(const char *data, size_t len) {
    PtnIniText text;
    text.data = data;
    text.len = len;
    return text;
}

static PtnIniText ptn_ini_trim_text(PtnIniText text) {
    while (text.len > 0 && isspace((unsigned char)text.data[0])) {
        text.data++;
        text.len--;
    }
    while (text.len > 0 && isspace((unsigned char)text.data[text.len - 1])) {
        text.len--;
    }
    return text;
}

static int ptn_ini_text_ascii_case_equal(PtnIniText text, const char *literal) {
    size_t literal_len = strlen(literal);
    if (text.len != literal_len) {
        return 0;
    }
    for (size_t i = 0; i < text.len; i++) {
        if (tolower((unsigned char)text.data[i]) != tolower((unsigned char)literal[i])) {
            return 0;
        }
    }
    return 1;
}

static char *ptn_ini_duplicate_text(PtnIniText text) {
    return ptn_duplicate_string_len(text.data, text.len);
}

static void ptn_ini_advance_newline(const char *data, size_t len, size_t *offset, size_t *line_no) {
    if (*offset >= len) {
        return;
    }
    if (data[*offset] == '\r' && *offset + 1 < len && data[*offset + 1] == '\n') {
        *offset += 2;
    } else {
        (*offset)++;
    }
    (*line_no)++;
}

static void ptn_ini_skip_to_next_line(const char *data, size_t len, size_t *offset, size_t *line_no) {
    while (*offset < len && data[*offset] != '\n' && data[*offset] != '\r') {
        (*offset)++;
    }
    if (*offset < len) {
        ptn_ini_advance_newline(data, len, offset, line_no);
    }
}

static void ptn_ini_emit_syntax_warning(
    PtnRuntime *runtime,
    const char *source_name,
    size_t source_line,
    size_t call_line,
    const char *detail
) {
    char message[512];
    int written = snprintf(
        message,
        sizeof(message),
        "syntax error, %s in %s on line %zu\n",
        detail,
        source_name == NULL ? "Unknown" : source_name,
        source_line
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_emit_warning(&runtime->diagnostics, message, call_line);
}

static int ptn_ini_is_name_start(unsigned char byte) {
    return isalpha(byte) || byte == '_' || byte == '\\';
}

static int ptn_ini_is_name_byte(unsigned char byte) {
    return isalnum(byte) || byte == '_' || byte == '\\' || byte == ':' || byte == '.';
}

static int ptn_ini_string_is_integer_key(const char *data, size_t len, int64_t *out) {
    if (len == 0 || data[0] == '+') {
        return 0;
    }
    if (len == 2 && data[0] == '-' && data[1] == '0') {
        return 0;
    }
    size_t offset = data[0] == '-' ? 1 : 0;
    if (offset == len) {
        return 0;
    }
    if (data[offset] == '0' && offset + 1 < len) {
        return 0;
    }
    for (size_t i = offset; i < len; i++) {
        if (!isdigit((unsigned char)data[i])) {
            return 0;
        }
    }
    char *copy = ptn_duplicate_string_len(data, len);
    char *end = NULL;
    errno = 0;
    long long parsed = strtoll(copy, &end, 10);
    int ok = errno != ERANGE && end != copy && *end == '\0';
    if (ok) {
        *out = (int64_t)parsed;
    }
    free(copy);
    return ok;
}

static PtnArrayKey ptn_ini_array_key_from_string(const char *data, size_t len, int append_empty) {
    if (append_empty && len == 0) {
        return ptn_array_int_key(INT64_MIN);
    }
    int64_t integer = 0;
    if (ptn_ini_string_is_integer_key(data, len, &integer)) {
        return ptn_array_int_key(integer);
    }
    return ptn_array_string_key_len(data, len);
}

static void ptn_ini_set_array_value(PtnArray *target, const char *key, size_t key_len, PtnValue value) {
    PtnArrayKey array_key = ptn_ini_array_key_from_string(key, key_len, 0);
    ptn_array_set_entry(target, array_key, value);
}

static void ptn_ini_append_or_set_array_value(
    PtnArray *target,
    const char *key,
    size_t key_len,
    int append,
    PtnValue value
) {
    if (append || key_len == 0) {
        ptn_array_set_entry(target, ptn_array_int_key(target->next_auto_key), value);
        return;
    }
    ptn_ini_set_array_value(target, key, key_len, value);
}

static int ptn_ini_value_to_string_buffer(PtnRuntime *runtime, PtnValue value, PtnStringBuffer *buffer, size_t line) {
    PtnStringOperand operand = ptn_value_to_string_operand_with_runtime(runtime, value, line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(operand);
        return 0;
    }
    ptn_string_buffer_append_len(buffer, operand.data, operand.len);
    ptn_string_operand_free(operand);
    return 1;
}

static int ptn_ini_find_fallback_delimiter(PtnIniText text, size_t *delimiter_out) {
    size_t depth = 0;
    char quote = '\0';
    for (size_t i = 0; i + 1 < text.len; i++) {
        char c = text.data[i];
        if (quote != '\0') {
            if (c == '\\' && i + 1 < text.len) {
                i++;
                continue;
            }
            if (c == quote) {
                quote = '\0';
            }
            continue;
        }
        if (c == '"' || c == '\'') {
            quote = c;
            continue;
        }
        if (c == '$' && text.data[i + 1] == '{') {
            depth++;
            i++;
            continue;
        }
        if (c == '}' && depth > 0) {
            depth--;
            continue;
        }
        if (depth == 0 && c == ':' && text.data[i + 1] == '-') {
            *delimiter_out = i;
            return 1;
        }
    }
    return 0;
}

static int ptn_ini_expand_text(
    PtnRuntime *runtime,
    PtnIniText text,
    int scanner_mode,
    int substitute_constants,
    PtnStringBuffer *buffer,
    size_t line,
    int *syntax_ok
);

static int ptn_ini_expand_variable(
    PtnRuntime *runtime,
    PtnIniText text,
    int scanner_mode,
    int substitute_constants,
    PtnStringBuffer *buffer,
    size_t line,
    int *syntax_ok
) {
    size_t delimiter = 0;
    PtnIniText name = text;
    PtnIniText fallback = ptn_ini_text(NULL, 0);
    int has_fallback = ptn_ini_find_fallback_delimiter(text, &delimiter);
    if (has_fallback) {
        name = ptn_ini_text(text.data, delimiter);
        fallback = ptn_ini_text(text.data + delimiter + 2, text.len - delimiter - 2);
    }
    name = ptn_ini_trim_text(name);
    if (name.len == 0) {
        *syntax_ok = 0;
        return 0;
    }
    char *name_copy = ptn_ini_duplicate_text(name);
    const char *env = getenv(name_copy);
    if (env != NULL && env[0] != '\0') {
        ptn_string_buffer_append(buffer, env);
        free(name_copy);
        return 1;
    }
    PtnValue constant;
    if (ptn_runtime_constant_value(runtime, name_copy, &constant)) {
        int ok = ptn_ini_value_to_string_buffer(runtime, constant, buffer, line);
        free(name_copy);
        return ok;
    }
    free(name_copy);
    if (has_fallback) {
        return ptn_ini_expand_text(runtime, fallback, scanner_mode, substitute_constants, buffer, line, syntax_ok);
    }
    return 1;
}

static void ptn_ini_append_quoted_text(
    PtnRuntime *runtime,
    PtnIniText text,
    char quote,
    int scanner_mode,
    int substitute_constants,
    PtnStringBuffer *buffer,
    size_t line,
    int *syntax_ok
) {
    for (size_t i = 0; i < text.len; i++) {
        char c = text.data[i];
        if (quote == '"' && c == '\\' && i + 1 < text.len) {
            char next = text.data[++i];
            switch (next) {
                case 'n':
                    ptn_string_buffer_append_char(buffer, '\n');
                    break;
                case 'r':
                    ptn_string_buffer_append_char(buffer, '\r');
                    break;
                case 't':
                    ptn_string_buffer_append_char(buffer, '\t');
                    break;
                case '"':
                    ptn_string_buffer_append_char(buffer, '"');
                    break;
                case '\\':
                    ptn_string_buffer_append_char(buffer, '\\');
                    break;
                case '$':
                    ptn_string_buffer_append_char(buffer, '$');
                    break;
                default:
                    ptn_string_buffer_append_char(buffer, '\\');
                    ptn_string_buffer_append_char(buffer, next);
                    break;
            }
            continue;
        }
        if (quote == '"' && c == '$' && i + 1 < text.len && text.data[i + 1] == '{') {
            size_t start = i + 2;
            size_t depth = 1;
            i += 2;
            while (i < text.len && depth > 0) {
                if (text.data[i] == '$' && i + 1 < text.len && text.data[i + 1] == '{') {
                    depth++;
                    i += 2;
                    continue;
                }
                if (text.data[i] == '}') {
                    depth--;
                    if (depth == 0) {
                        break;
                    }
                }
                i++;
            }
            if (i >= text.len || depth != 0) {
                *syntax_ok = 0;
                return;
            }
            PtnIniText variable = ptn_ini_text(text.data + start, i - start);
            if (!ptn_ini_expand_variable(runtime, variable, scanner_mode, substitute_constants, buffer, line, syntax_ok)) {
                return;
            }
            continue;
        }
        ptn_string_buffer_append_char(buffer, c);
    }
}

static int ptn_ini_expand_text(
    PtnRuntime *runtime,
    PtnIniText text,
    int scanner_mode,
    int substitute_constants,
    PtnStringBuffer *buffer,
    size_t line,
    int *syntax_ok
) {
    int last_concat_token = 0;
    for (size_t i = 0; i < text.len; i++) {
        char c = text.data[i];
        if (c == '$' && i + 1 < text.len && text.data[i + 1] == '{') {
            size_t start = i + 2;
            size_t depth = 1;
            i += 2;
            while (i < text.len && depth > 0) {
                if (text.data[i] == '$' && i + 1 < text.len && text.data[i + 1] == '{') {
                    depth++;
                    i += 2;
                    continue;
                }
                if (text.data[i] == '}') {
                    depth--;
                    if (depth == 0) {
                        break;
                    }
                }
                i++;
            }
            if (i >= text.len || depth != 0) {
                *syntax_ok = 0;
                return 0;
            }
            PtnIniText variable = ptn_ini_text(text.data + start, i - start);
            if (!ptn_ini_expand_variable(runtime, variable, scanner_mode, substitute_constants, buffer, line, syntax_ok)) {
                return 0;
            }
            last_concat_token = 1;
            continue;
        }
        if (substitute_constants && isspace((unsigned char)c)) {
            size_t lookahead = i + 1;
            while (lookahead < text.len && isspace((unsigned char)text.data[lookahead])) {
                lookahead++;
            }
            if (last_concat_token &&
                lookahead < text.len &&
                (text.data[lookahead] == '"' ||
                 text.data[lookahead] == '\'' ||
                 ptn_ini_is_name_start((unsigned char)text.data[lookahead]))) {
                continue;
            }
        }
        if (substitute_constants && (c == '"' || c == '\'')) {
            size_t start = i + 1;
            size_t cursor = start;
            while (cursor < text.len && text.data[cursor] != c) {
                if (c == '"' && text.data[cursor] == '\\' && cursor + 1 < text.len) {
                    cursor += 2;
                } else {
                    cursor++;
                }
            }
            if (cursor >= text.len) {
                ptn_string_buffer_append_char(buffer, c);
                last_concat_token = 0;
                continue;
            }
            PtnIniText quoted = ptn_ini_text(text.data + start, cursor - start);
            ptn_ini_append_quoted_text(runtime, quoted, c, scanner_mode, 0, buffer, line, syntax_ok);
            if (!*syntax_ok) {
                return 0;
            }
            i = cursor;
            last_concat_token = 1;
            continue;
        }
        if (substitute_constants && scanner_mode != PTN_INI_SCANNER_RAW && ptn_ini_is_name_start((unsigned char)c)) {
            size_t start = i;
            i++;
            while (i < text.len && ptn_ini_is_name_byte((unsigned char)text.data[i])) {
                i++;
            }
            PtnIniText name = ptn_ini_text(text.data + start, i - start);
            char *name_copy = ptn_ini_duplicate_text(name);
            PtnValue constant;
            if (ptn_runtime_constant_value(runtime, name_copy, &constant)) {
                int ok = ptn_ini_value_to_string_buffer(runtime, constant, buffer, line);
                free(name_copy);
                if (!ok) {
                    return 0;
                }
                last_concat_token = 1;
            } else {
                ptn_string_buffer_append_len(buffer, name.data, name.len);
                free(name_copy);
                last_concat_token = 0;
            }
            i--;
            continue;
        }
        ptn_string_buffer_append_char(buffer, c);
        last_concat_token = 0;
    }
    return *syntax_ok;
}

static int ptn_ini_strip_outer_quotes(PtnIniText text, PtnIniText *inner_out, char *quote_out) {
    text = ptn_ini_trim_text(text);
    if (text.len < 2 || (text.data[0] != '"' && text.data[0] != '\'')) {
        return 0;
    }
    char quote = text.data[0];
    if (text.data[text.len - 1] != quote) {
        return 0;
    }
    *inner_out = ptn_ini_text(text.data + 1, text.len - 2);
    *quote_out = quote;
    return 1;
}

static int ptn_ini_parse_integer_literal(PtnIniText text, int64_t *out) {
    text = ptn_ini_trim_text(text);
    if (text.len == 0) {
        return 0;
    }
    char *copy = ptn_ini_duplicate_text(text);
    char *end = NULL;
    errno = 0;
    long long parsed = strtoll(copy, &end, 0);
    int ok = errno != ERANGE && end != copy && *end == '\0';
    if (ok) {
        *out = (int64_t)parsed;
    }
    free(copy);
    return ok;
}

static int ptn_ini_eval_int_atom(PtnRuntime *runtime, PtnIniText text, int64_t *out) {
    text = ptn_ini_trim_text(text);
    if (text.len == 0) {
        return 0;
    }
    int invert = 0;
    while (text.len > 0 && text.data[0] == '~') {
        invert = !invert;
        text.data++;
        text.len--;
        text = ptn_ini_trim_text(text);
    }
    int64_t value = 0;
    if (!ptn_ini_parse_integer_literal(text, &value)) {
        char *numeric_copy = ptn_ini_duplicate_text(text);
        char *numeric_end = NULL;
        errno = 0;
        double parsed_float = strtod(numeric_copy, &numeric_end);
        int parsed_float_ok = errno != ERANGE &&
            numeric_end != numeric_copy &&
            *numeric_end == '\0' &&
            strchr(numeric_copy, '.') != NULL;
        if (parsed_float_ok) {
            free(numeric_copy);
            value = (int64_t)parsed_float;
            *out = invert ? ~value : value;
            return 1;
        }
        free(numeric_copy);
        char *name = ptn_ini_duplicate_text(text);
        PtnValue constant;
        if (!ptn_runtime_constant_value(runtime, name, &constant)) {
            free(name);
            return 0;
        }
        PtnValue resolved = ptn_value_deref(constant);
        if (resolved.type == PTN_INT) {
            value = resolved.as.integer;
        } else if (resolved.type == PTN_BOOL) {
            value = resolved.as.boolean ? 1 : 0;
        } else {
            PtnStringOperand operand = ptn_value_to_string_operand(resolved);
            int ok = ptn_ini_parse_integer_literal(ptn_ini_text(operand.data, operand.len), &value);
            ptn_string_operand_free(operand);
            if (!ok) {
                free(name);
                return 0;
            }
        }
        free(name);
    }
    *out = invert ? ~value : value;
    return 1;
}

static int ptn_ini_eval_int_expression(PtnRuntime *runtime, PtnIniText text, int64_t *out) {
    int has_operator = 0;
    for (size_t i = 0; i < text.len; i++) {
        if (text.data[i] == '&' || text.data[i] == '|' || text.data[i] == '^' || text.data[i] == '~') {
            has_operator = 1;
            break;
        }
    }
    if (!has_operator) {
        char *numeric_copy = ptn_ini_duplicate_text(ptn_ini_trim_text(text));
        char *numeric_end = NULL;
        errno = 0;
        (void)strtod(numeric_copy, &numeric_end);
        int is_plain_float = errno != ERANGE &&
            numeric_end != numeric_copy &&
            *numeric_end == '\0' &&
            strchr(numeric_copy, '.') != NULL;
        free(numeric_copy);
        if (is_plain_float) {
            return 0;
        }
        return ptn_ini_eval_int_atom(runtime, text, out);
    }

    size_t start = 0;
    char pending = '\0';
    int have_value = 0;
    int64_t result = 0;
    for (size_t i = 0; i <= text.len; i++) {
        int at_operator = i < text.len && (text.data[i] == '&' || text.data[i] == '|' || text.data[i] == '^');
        if (i != text.len && !at_operator) {
            continue;
        }
        PtnIniText atom = ptn_ini_trim_text(ptn_ini_text(text.data + start, i - start));
        int64_t value = 0;
        if (!ptn_ini_eval_int_atom(runtime, atom, &value)) {
            return 0;
        }
        if (!have_value) {
            result = value;
            have_value = 1;
        } else if (pending == '&') {
            result &= value;
        } else if (pending == '|') {
            result |= value;
        } else if (pending == '^') {
            result ^= value;
        } else {
            return 0;
        }
        if (i < text.len) {
            pending = text.data[i];
            start = i + 1;
        }
    }
    if (!have_value) {
        return 0;
    }
    *out = result;
    return 1;
}

static int ptn_ini_text_is_plain_octal_or_hex_literal(PtnIniText text) {
    text = ptn_ini_trim_text(text);
    size_t offset = 0;
    if (offset < text.len && (text.data[offset] == '+' || text.data[offset] == '-')) {
        offset++;
    }
    if (offset + 1 >= text.len || text.data[offset] != '0') {
        return 0;
    }
    if (text.data[offset + 1] == 'x' || text.data[offset + 1] == 'X') {
        if (offset + 2 >= text.len) {
            return 0;
        }
        for (size_t i = offset + 2; i < text.len; i++) {
            if (!isxdigit((unsigned char)text.data[i])) {
                return 0;
            }
        }
        return 1;
    }
    if (!isdigit((unsigned char)text.data[offset + 1])) {
        return 0;
    }
    for (size_t i = offset + 1; i < text.len; i++) {
        if (text.data[i] < '0' || text.data[i] > '7') {
            return 0;
        }
    }
    return 1;
}

static int ptn_ini_parse_float_literal(PtnIniText text, double *out) {
    text = ptn_ini_trim_text(text);
    if (text.len == 0) {
        return 0;
    }
    char *copy = ptn_ini_duplicate_text(text);
    char *end = NULL;
    errno = 0;
    double parsed = strtod(copy, &end);
    int ok = errno != ERANGE && end != copy && *end == '\0' && strchr(copy, '.') != NULL;
    if (ok) {
        *out = parsed;
    }
    free(copy);
    return ok;
}

static PtnValue ptn_ini_string_value_from_buffer(PtnStringBuffer *buffer) {
    return ptn_owned_string_len(buffer->data, buffer->len);
}

static PtnValue ptn_ini_normalized_string_value(
    PtnRuntime *runtime,
    PtnIniText text,
    int scanner_mode,
    size_t line,
    int *syntax_ok,
    int *quoted_out
) {
    PtnIniText inner;
    char quote = '\0';
    int quoted = ptn_ini_strip_outer_quotes(text, &inner, &quote);
    if (quoted_out != NULL) {
        *quoted_out = quoted;
    }
    if (quoted) {
        PtnStringBuffer buffer;
        ptn_string_buffer_init(&buffer);
        if (scanner_mode == PTN_INI_SCANNER_RAW) {
            ptn_string_buffer_append_len(&buffer, inner.data, inner.len);
        } else {
            ptn_ini_append_quoted_text(runtime, inner, quote, scanner_mode, 1, &buffer, line, syntax_ok);
            if (!*syntax_ok) {
                free(buffer.data);
                return ptn_bool(0);
            }
        }
        return ptn_ini_string_value_from_buffer(&buffer);
    }

    PtnIniText trimmed = ptn_ini_trim_text(text);
    if (scanner_mode == PTN_INI_SCANNER_RAW) {
        return ptn_owned_string_len(ptn_ini_duplicate_text(trimmed), trimmed.len);
    }

    int64_t expression = 0;
    if (
        (scanner_mode != PTN_INI_SCANNER_NORMAL || !ptn_ini_text_is_plain_octal_or_hex_literal(trimmed)) &&
        ptn_ini_eval_int_expression(runtime, trimmed, &expression)
    ) {
        char number[64];
        int written = snprintf(number, sizeof(number), "%lld", (long long)expression);
        if (written < 0 || (size_t)written >= sizeof(number)) {
            ptn_abort_out_of_memory();
        }
        return ptn_owned_string_len(ptn_duplicate_string_len(number, (size_t)written), (size_t)written);
    }

    if (scanner_mode == PTN_INI_SCANNER_NORMAL) {
        if (ptn_ini_text_ascii_case_equal(trimmed, "yes") ||
            ptn_ini_text_ascii_case_equal(trimmed, "on") ||
            ptn_ini_text_ascii_case_equal(trimmed, "true")) {
            return ptn_string("1");
        }
        if (ptn_ini_text_ascii_case_equal(trimmed, "no") ||
            ptn_ini_text_ascii_case_equal(trimmed, "off") ||
            ptn_ini_text_ascii_case_equal(trimmed, "false") ||
            ptn_ini_text_ascii_case_equal(trimmed, "none") ||
            ptn_ini_text_ascii_case_equal(trimmed, "null")) {
            return ptn_string("");
        }
    }

    PtnStringBuffer buffer;
    ptn_string_buffer_init(&buffer);
    if (!ptn_ini_expand_text(runtime, text, scanner_mode, 1, &buffer, line, syntax_ok)) {
        free(buffer.data);
        return ptn_bool(0);
    }
    return ptn_ini_string_value_from_buffer(&buffer);
}

static PtnValue ptn_ini_parse_value(
    PtnRuntime *runtime,
    PtnIniText text,
    int scanner_mode,
    size_t line,
    int *syntax_ok
) {
    int quoted = 0;
    PtnValue normalized = ptn_ini_normalized_string_value(runtime, text, scanner_mode, line, syntax_ok, &quoted);
    if (!*syntax_ok || scanner_mode != PTN_INI_SCANNER_TYPED || quoted) {
        return normalized;
    }

    PtnStringOperand operand = ptn_value_to_string_operand(normalized);
    PtnIniText as_text = ptn_ini_text(operand.data, operand.len);
    if (ptn_ini_text_ascii_case_equal(as_text, "yes") ||
        ptn_ini_text_ascii_case_equal(as_text, "on") ||
        ptn_ini_text_ascii_case_equal(as_text, "true")) {
        ptn_string_operand_free(operand);
        return ptn_bool(1);
    }
    if (ptn_ini_text_ascii_case_equal(as_text, "no") ||
        ptn_ini_text_ascii_case_equal(as_text, "off") ||
        ptn_ini_text_ascii_case_equal(as_text, "false")) {
        ptn_string_operand_free(operand);
        return ptn_bool(0);
    }
    if (ptn_ini_text_ascii_case_equal(as_text, "none") ||
        ptn_ini_text_ascii_case_equal(as_text, "null")) {
        ptn_string_operand_free(operand);
        return ptn_null();
    }
    int64_t integer = 0;
    if (ptn_ini_eval_int_expression(runtime, as_text, &integer)) {
        ptn_string_operand_free(operand);
        return ptn_int(integer);
    }
    PtnIniText trimmed = ptn_ini_trim_text(as_text);
    size_t prefix_len = 0;
    if (trimmed.len >= 3) {
        if (trimmed.data[prefix_len] == '+' || trimmed.data[prefix_len] == '-') {
            prefix_len++;
        }
        size_t digit_start = prefix_len;
        while (prefix_len < trimmed.len && isdigit((unsigned char)trimmed.data[prefix_len])) {
            prefix_len++;
        }
        if (prefix_len > digit_start &&
            prefix_len + 1 < trimmed.len &&
            trimmed.data[prefix_len] == '|' &&
            trimmed.data[prefix_len + 1] == '>') {
            int64_t prefix = 0;
            if (ptn_ini_parse_integer_literal(ptn_ini_text(trimmed.data, prefix_len), &prefix)) {
                ptn_string_operand_free(operand);
                return ptn_int(prefix);
            }
        }
    }
    double floating = 0.0;
    if (ptn_ini_parse_float_literal(as_text, &floating)) {
        ptn_string_operand_free(operand);
        return ptn_float(floating);
    }
    ptn_string_operand_free(operand);
    return normalized;
}

static char *ptn_ini_normalized_key(
    PtnRuntime *runtime,
    PtnIniText text,
    int scanner_mode,
    size_t line,
    int *syntax_ok,
    size_t *len_out
) {
    PtnIniText inner;
    char quote = '\0';
    text = ptn_ini_trim_text(text);
    if (ptn_ini_strip_outer_quotes(text, &inner, &quote)) {
        PtnStringBuffer buffer;
        ptn_string_buffer_init(&buffer);
        if (scanner_mode == PTN_INI_SCANNER_RAW) {
            ptn_string_buffer_append_len(&buffer, inner.data, inner.len);
        } else {
            ptn_ini_append_quoted_text(runtime, inner, quote, scanner_mode, 0, &buffer, line, syntax_ok);
        }
        if (!*syntax_ok) {
            free(buffer.data);
            *len_out = 0;
            return NULL;
        }
        *len_out = buffer.len;
        return buffer.data;
    }

    PtnStringBuffer buffer;
    ptn_string_buffer_init(&buffer);
    if (!ptn_ini_expand_text(runtime, text, scanner_mode, 0, &buffer, line, syntax_ok)) {
        free(buffer.data);
        *len_out = 0;
        return NULL;
    }
    *len_out = buffer.len;
    return buffer.data;
}

static PtnArray *ptn_ini_section_array(
    PtnRuntime *runtime,
    PtnValue result,
    PtnIniText section_text,
    int scanner_mode,
    size_t line,
    int *syntax_ok
) {
    size_t section_len = 0;
    char *section = ptn_ini_normalized_key(runtime, section_text, scanner_mode, line, syntax_ok, &section_len);
    if (!*syntax_ok) {
        return NULL;
    }
    PtnArrayKey section_key = ptn_ini_array_key_from_string(section, section_len, 0);
    PtnArrayEntry *entry = ptn_array_entry_for_key(result.as.array, section_key);
    if (entry != NULL && ptn_value_deref(entry->value).type == PTN_ARRAY) {
        ptn_array_key_free(section_key);
        free(section);
        return ptn_value_deref(entry->value).as.array;
    }
    PtnValue array = ptn_array_from_literal_entries(0, NULL);
    ptn_array_set_entry(result.as.array, section_key, array);
    PtnArrayKey lookup_key = ptn_ini_array_key_from_string(section, section_len, 0);
    entry = ptn_array_entry_for_key(result.as.array, lookup_key);
    ptn_array_key_free(lookup_key);
    free(section);
    return entry == NULL ? NULL : ptn_value_deref(entry->value).as.array;
}

static void ptn_ini_store_entry(
    PtnRuntime *runtime,
    PtnArray *target,
    PtnIniText key_text,
    PtnValue value,
    int scanner_mode,
    size_t line,
    int *syntax_ok
) {
    key_text = ptn_ini_trim_text(key_text);
    const char *bracket = memchr(key_text.data, '[', key_text.len);
    if (bracket == NULL) {
        size_t key_len = 0;
        char *key = ptn_ini_normalized_key(runtime, key_text, scanner_mode, line, syntax_ok, &key_len);
        if (!*syntax_ok) {
            return;
        }
        ptn_ini_set_array_value(target, key, key_len, value);
        free(key);
        return;
    }

    const char *last_bracket = NULL;
    for (size_t i = key_text.len; i > 0; i--) {
        if (key_text.data[i - 1] == ']') {
            last_bracket = key_text.data + i - 1;
            break;
        }
    }
    if (last_bracket == NULL || last_bracket < bracket) {
        size_t key_len = 0;
        char *key = ptn_ini_normalized_key(runtime, key_text, scanner_mode, line, syntax_ok, &key_len);
        if (!*syntax_ok) {
            return;
        }
        ptn_ini_set_array_value(target, key, key_len, value);
        free(key);
        return;
    }

    PtnIniText base_text = ptn_ini_trim_text(ptn_ini_text(key_text.data, (size_t)(bracket - key_text.data)));
    size_t base_len = 0;
    char *base = ptn_ini_normalized_key(runtime, base_text, scanner_mode, line, syntax_ok, &base_len);
    if (!*syntax_ok) {
        return;
    }
    PtnArrayKey base_key = ptn_ini_array_key_from_string(base, base_len, 0);
    PtnArrayEntry *entry = ptn_array_entry_for_key(target, base_key);
    if (entry == NULL || ptn_value_deref(entry->value).type != PTN_ARRAY) {
        ptn_array_set_entry(target, base_key, ptn_array_from_literal_entries(0, NULL));
        PtnArrayKey lookup_key = ptn_ini_array_key_from_string(base, base_len, 0);
        entry = ptn_array_entry_for_key(target, lookup_key);
        ptn_array_key_free(lookup_key);
    } else {
        ptn_array_key_free(base_key);
    }
    free(base);
    if (entry == NULL) {
        return;
    }

    PtnIniText offset_text = ptn_ini_trim_text(ptn_ini_text(bracket + 1, (size_t)(last_bracket - bracket - 1)));
    size_t offset_len = 0;
    char *offset = ptn_ini_normalized_key(runtime, offset_text, scanner_mode, line, syntax_ok, &offset_len);
    if (!*syntax_ok) {
        return;
    }
    ptn_ini_append_or_set_array_value(ptn_value_deref(entry->value).as.array, offset, offset_len, offset_len == 0, value);
    free(offset);
}

static int ptn_ini_scan_value_end(
    const char *data,
    size_t len,
    size_t *offset,
    size_t *line_no,
    size_t *value_end_out,
    char *unmatched_quote_out,
    int scanner_mode
) {
    char quote = '\0';
    int quote_can_open = 1;
    while (*offset < len) {
        char c = data[*offset];
        if (quote != '\0') {
            if (c == '\\' && quote == '"' && *offset + 1 < len) {
                *offset += 2;
                continue;
            }
            if (c == quote) {
                quote = '\0';
                (*offset)++;
                quote_can_open = 0;
                continue;
            }
            if (c == '\n' || c == '\r') {
                ptn_ini_advance_newline(data, len, offset, line_no);
                continue;
            }
            (*offset)++;
            continue;
        }
        if (c == '\n' || c == '\r' || c == '\0') {
            break;
        }
        if (c == ';') {
            break;
        }
        if (c == '=') {
            return 0;
        }
        if ((c == '"' || c == '\'') && (scanner_mode != PTN_INI_SCANNER_RAW || quote_can_open)) {
            if (scanner_mode == PTN_INI_SCANNER_RAW) {
                int closes_on_this_line = 0;
                for (size_t look = *offset + 1; look < len; look++) {
                    if (data[look] == '\n' || data[look] == '\r') {
                        break;
                    }
                    if (data[look] == c) {
                        closes_on_this_line = 1;
                        break;
                    }
                }
                if (!closes_on_this_line) {
                    quote_can_open = 0;
                    (*offset)++;
                    continue;
                }
            }
            quote = c;
            (*offset)++;
            continue;
        }
        if (!isspace((unsigned char)c)) {
            quote_can_open = 0;
        }
        (*offset)++;
    }
    *value_end_out = *offset;
    *unmatched_quote_out = quote;
    return 1;
}

static const char *ptn_ini_syntax_detail_for_failed_value(PtnIniText text) {
    for (size_t i = 0; i + 1 < text.len; i++) {
        if (text.data[i] != '$' || text.data[i + 1] != '{') {
            continue;
        }
        size_t depth = 1;
        int saw_fallback = 0;
        i += 2;
        while (i < text.len && depth > 0) {
            if (text.data[i] == '$' && i + 1 < text.len && text.data[i + 1] == '{') {
                depth++;
                i += 2;
                continue;
            }
            if (depth == 1 && text.data[i] == ':' && i + 1 < text.len && text.data[i + 1] == '-') {
                saw_fallback = 1;
            }
            if (text.data[i] == '}') {
                depth--;
                if (depth == 0) {
                    break;
                }
            }
            i++;
        }
        if (depth != 0) {
            return saw_fallback
                ? "unexpected TC_FALLBACK, expecting TC_VARNAME"
                : "unexpected end of file, expecting TC_FALLBACK or '}'";
        }
    }
    return "unexpected end of file";
}

static PtnValue ptn_ini_parse_contents(
    PtnRuntime *runtime,
    const char *data,
    size_t len,
    int process_sections,
    int scanner_mode,
    const char *source_name,
    size_t call_line,
    int *ok_out
) {
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    PtnArray *target = result.as.array;
    size_t offset = 0;
    size_t line_no = 1;
    *ok_out = 1;

    while (offset < len) {
        while (offset < len && (data[offset] == '\n' || data[offset] == '\r')) {
            ptn_ini_advance_newline(data, len, &offset, &line_no);
        }
        while (offset < len && isspace((unsigned char)data[offset]) && data[offset] != '\n' && data[offset] != '\r') {
            offset++;
        }
        if (offset >= len) {
            break;
        }
        if (data[offset] == ';' || data[offset] == '#') {
            ptn_ini_skip_to_next_line(data, len, &offset, &line_no);
            continue;
        }

        size_t statement_line = line_no;
        if (data[offset] == '[') {
            size_t section_start = ++offset;
            while (offset < len && data[offset] != ']' && data[offset] != '\n' && data[offset] != '\r') {
                offset++;
            }
            if (offset >= len || data[offset] != ']') {
                ptn_ini_emit_syntax_warning(runtime, source_name, statement_line, call_line, "unexpected end of section");
                *ok_out = 0;
                ptn_value_destroy(&result);
                return ptn_bool(0);
            }
            PtnIniText section_text = ptn_ini_text(data + section_start, offset - section_start);
            offset++;
            if (process_sections) {
                target = ptn_ini_section_array(runtime, result, section_text, scanner_mode, call_line, ok_out);
                if (!*ok_out || target == NULL) {
                    ptn_value_destroy(&result);
                    return ptn_bool(0);
                }
            } else {
                target = result.as.array;
            }
            ptn_ini_skip_to_next_line(data, len, &offset, &line_no);
            continue;
        }

        size_t key_start = offset;
        while (offset < len && data[offset] != '=' && data[offset] != '\n' && data[offset] != '\r') {
            offset++;
        }
        if (offset >= len || data[offset] != '=') {
            ptn_ini_skip_to_next_line(data, len, &offset, &line_no);
            continue;
        }
        PtnIniText key_text = ptn_ini_text(data + key_start, offset - key_start);
        offset++;
        while (offset < len && isspace((unsigned char)data[offset]) && data[offset] != '\n' && data[offset] != '\r') {
            offset++;
        }
        size_t value_start = offset;
        size_t value_end = offset;
        char unmatched_quote = '\0';
        if (!ptn_ini_scan_value_end(data, len, &offset, &line_no, &value_end, &unmatched_quote, scanner_mode)) {
            ptn_ini_emit_syntax_warning(runtime, source_name, statement_line, call_line, "unexpected '='");
            *ok_out = 0;
            ptn_value_destroy(&result);
            return ptn_bool(0);
        }
        if (unmatched_quote != '\0') {
            const char *detail = unmatched_quote == '"'
                ? "unexpected end of file, expecting TC_DOLLAR_CURLY or TC_QUOTED_STRING or '\"'"
                : "unexpected end of file";
            ptn_ini_emit_syntax_warning(runtime, source_name, statement_line, call_line, detail);
            *ok_out = 0;
            ptn_value_destroy(&result);
            return ptn_bool(0);
        }

        PtnIniText raw_value_text = ptn_ini_text(data + value_start, value_end - value_start);
        int only_space_value = 1;
        for (size_t i = 0; i < raw_value_text.len; i++) {
            if (!isspace((unsigned char)raw_value_text.data[i])) {
                only_space_value = 0;
                break;
            }
        }
        PtnIniText value_text = only_space_value
            ? ptn_ini_text(raw_value_text.data, 0)
            : (value_end == len ? raw_value_text : ptn_ini_trim_text(raw_value_text));
        int syntax_ok = 1;
        PtnValue value = ptn_ini_parse_value(runtime, value_text, scanner_mode, call_line, &syntax_ok);
        if (!syntax_ok || runtime->exceptions->active_exception != NULL) {
            if (!syntax_ok) {
                ptn_ini_emit_syntax_warning(
                    runtime,
                    source_name,
                    statement_line,
                    call_line,
                    ptn_ini_syntax_detail_for_failed_value(value_text)
                );
            }
            *ok_out = 0;
            ptn_value_destroy(&result);
            return ptn_bool(0);
        }
        ptn_ini_store_entry(runtime, target, key_text, value, scanner_mode, call_line, &syntax_ok);
        if (!syntax_ok) {
            ptn_ini_emit_syntax_warning(runtime, source_name, statement_line, call_line, "unexpected end of file");
            *ok_out = 0;
            ptn_value_destroy(&result);
            return ptn_bool(0);
        }
        ptn_ini_skip_to_next_line(data, len, &offset, &line_no);
    }

    return result;
}

static int ptn_ini_scanner_mode_arg(PtnRuntime *runtime, const char *function_name, size_t argc, const PtnValue *args, size_t line) {
    int64_t scanner_mode = PTN_INI_SCANNER_NORMAL;
    if (argc >= 3) {
        scanner_mode = ptn_internal_expect_integer_arg(runtime, function_name, 3, "scanner_mode", args[2], line);
        if (runtime->exceptions->active_exception != NULL) {
            return PTN_INI_SCANNER_NORMAL;
        }
    }
    if (scanner_mode != PTN_INI_SCANNER_NORMAL &&
        scanner_mode != PTN_INI_SCANNER_RAW &&
        scanner_mode != PTN_INI_SCANNER_TYPED) {
        ptn_emit_warning(&runtime->diagnostics, "Invalid scanner mode", line);
        return -1;
    }
    return (int)scanner_mode;
}

static PtnValue ptn_internal_parse_ini_string(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "parse_ini_string", 1, "ini_string", args[0], line);
    int process_sections = argc >= 2 && ptn_is_truthy(args[1]);
    int scanner_mode = ptn_ini_scanner_mode_arg(runtime, "parse_ini_string", argc, args, line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(input);
        return ptn_null();
    }
    if (scanner_mode < 0) {
        ptn_string_operand_free(input);
        return ptn_bool(0);
    }
    int ok = 1;
    PtnValue result = ptn_ini_parse_contents(
        runtime,
        input.data,
        input.len,
        process_sections,
        scanner_mode,
        "Unknown",
        line,
        &ok
    );
    ptn_string_operand_free(input);
    return result;
}

static PtnValue ptn_internal_parse_ini_file(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand filename = ptn_internal_expect_string_arg(runtime, "parse_ini_file", 1, "filename", args[0], line);
    char *path = ptn_duplicate_string_len(filename.data, filename.len);
    ptn_string_operand_free(filename);

    int process_sections = argc >= 2 && ptn_is_truthy(args[1]);
    unsigned char *data = NULL;
    size_t data_len = 0;
    char *opened_path = NULL;
    int read_result = ptn_read_file_bytes_with_search(runtime, path, 1, &data, &data_len, &opened_path);
    if (read_result <= 0) {
        char detail[192];
        int needed = snprintf(detail, sizeof(detail), "Failed to open stream: %s", strerror(errno));
        if (needed < 0 || (size_t)needed >= sizeof(detail)) {
            ptn_abort_out_of_memory();
        }
        ptn_emit_file_warning(runtime, "parse_ini_file", path, detail, line);
        free(opened_path);
        free(path);
        free(data);
        return ptn_bool(0);
    }

    int scanner_mode = ptn_ini_scanner_mode_arg(runtime, "parse_ini_file", argc, args, line);
    if (runtime->exceptions->active_exception != NULL) {
        free(opened_path);
        free(path);
        free(data);
        return ptn_null();
    }
    if (scanner_mode < 0) {
        free(opened_path);
        free(path);
        free(data);
        return ptn_bool(0);
    }

    int ok = 1;
    PtnValue result = ptn_ini_parse_contents(
        runtime,
        (const char *)data,
        data_len,
        process_sections,
        scanner_mode,
        opened_path == NULL ? path : opened_path,
        line,
        &ok
    );
    free(opened_path);
    free(path);
    free(data);
    return result;
}

static double ptn_value_to_double(PtnValue value) {
    double fast_number = 0.0;
    if (ptn_fast_scalar_double(value, &fast_number)) {
        return fast_number;
    }

    PtnNumber number = ptn_to_number(value);
    return number.floating;
}

static const char *ptn_numeric_arg_type_name(PtnValue value) {
    value = ptn_value_deref(value);
    if (value.type == PTN_OBJECT) {
        return value.as.object->class_name;
    }
    if (value.type == PTN_EXCEPTION) {
        return value.as.exception->class_name;
    }
    if (value.type == PTN_CLOSURE) {
        return "Closure";
    }
    return ptn_offset_container_type_name(value);
}

static int ptn_numeric_arg_string_to_double(PtnString string, double *out) {
    const char *data = (const char *)string.data;
    const char *limit = data + string.len;
    const char *start = data;
    while (start < limit && isspace((unsigned char)*start)) {
        start++;
    }
    if (start >= limit) {
        return 0;
    }

    const char *cursor = start;
    if (*cursor == '+' || *cursor == '-') {
        cursor++;
        if (cursor >= limit) {
            return 0;
        }
    }
    if (cursor + 1 < limit && cursor[0] == '0' && (cursor[1] == 'x' || cursor[1] == 'X')) {
        return 0;
    }
    if (!isdigit((unsigned char)*cursor) && *cursor != '.') {
        return 0;
    }
    if (*cursor == '.' && (cursor + 1 >= limit || !isdigit((unsigned char)cursor[1]))) {
        return 0;
    }

    char *end = NULL;
    double number = strtod(start, &end);
    if (end == start) {
        return 0;
    }
    while (end < limit && isspace((unsigned char)*end)) {
        end++;
    }
    if (end != limit) {
        return 0;
    }

    *out = number;
    return 1;
}

static PtnNumber ptn_internal_expect_number_arg(
    PtnRuntime *runtime,
    const char *function_name,
    size_t position,
    const char *argument_name,
    const char *expected_type,
    PtnValue value,
    size_t line
) {
    value = ptn_value_deref(value);
    switch (value.type) {
        case PTN_NULL: {
            char message[192];
            int written = snprintf(
                message,
                sizeof(message),
                "%s(): Passing null to parameter #%zu ($%s) of type %s is deprecated",
                function_name,
                position,
                argument_name,
                expected_type
            );
            if (written < 0 || (size_t)written >= sizeof(message)) {
                ptn_abort_out_of_memory();
            }
            ptn_emit_deprecation(&runtime->diagnostics, message, line);
            return ptn_number_int(0);
        }
        case PTN_BOOL:
            return ptn_number_int(value.as.boolean ? 1 : 0);
        case PTN_INT:
            return ptn_number_int(value.as.integer);
        case PTN_FLOAT:
            return ptn_number_float(value.as.floating);
        case PTN_STRING: {
            double number = 0.0;
            if (ptn_numeric_arg_string_to_double(value.as.string, &number)) {
                return ptn_string_to_number((const char *)value.as.string.data);
            }
            break;
        }
        case PTN_ARRAY:
        case PTN_OBJECT:
        case PTN_CLOSURE:
        case PTN_EXCEPTION:
        case PTN_RESOURCE:
        case PTN_REFERENCE:
            break;
    }

    char message[192];
    int written = snprintf(
        message,
        sizeof(message),
        "%s(): Argument #%zu ($%s) must be of type %s, %s given",
        function_name,
        position,
        argument_name,
        expected_type,
        ptn_numeric_arg_type_name(value)
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "TypeError", message);
    return ptn_number_int(0);
}

