static int ptn_parse_precision_operand(PtnStringOperand value, int *out) {
    char *text = ptn_duplicate_string_len(value.data, value.len);
    char *start = text;
    while (isspace((unsigned char)*start)) {
        start++;
    }
    char *end = NULL;
    errno = 0;
    long parsed = strtol(start, &end, 10);
    while (end != NULL && isspace((unsigned char)*end)) {
        end++;
    }
    int ok = errno == 0 &&
        end != start &&
        end != NULL &&
        *end == '\0' &&
        parsed >= -1 &&
        parsed <= PTN_MAX_FLOAT_FORMAT_PRECISION;
    if (ok) {
        *out = (int)parsed;
    }
    free(text);
    return ok;
}

static int ptn_precision_value_from_arg(PtnValue value, int *out) {
    PtnStringOperand operand = ptn_value_to_string_operand(value);
    int ok = ptn_parse_precision_operand(operand, out);
    ptn_string_operand_free(operand);
    return ok;
}

static int ptn_runtime_set_precision(PtnRuntime *runtime, PtnValue value) {
    int precision = 0;
    if (!ptn_precision_value_from_arg(value, &precision)) {
        return 0;
    }
    ptn_runtime_config_root(runtime)->precision = precision;
    return 1;
}

static int ptn_runtime_set_serialize_precision(PtnRuntime *runtime, PtnValue value) {
    int precision = 0;
    if (!ptn_precision_value_from_arg(value, &precision)) {
        return 0;
    }
    ptn_runtime_config_root(runtime)->serialize_precision = precision;
    return 1;
}

static int ptn_ini_set_value_type_is_allowed(PtnValue value) {
    value = ptn_value_deref(value);
    switch (value.type) {
        case PTN_NULL:
        case PTN_BOOL:
        case PTN_INT:
        case PTN_FLOAT:
        case PTN_STRING:
            return 1;
        case PTN_ARRAY:
        case PTN_OBJECT:
        case PTN_CLOSURE:
        case PTN_EXCEPTION:
        case PTN_RESOURCE:
        case PTN_REFERENCE:
            return 0;
    }
    return 0;
}

static void ptn_runtime_set_memory_limit(PtnRuntime *runtime, const char *memory_limit) {
    PtnRuntime *root = ptn_runtime_config_root(runtime);
    ptn_runtime_set_ini_string(&root->memory_limit, memory_limit);
}

static void ptn_runtime_apply_memory_limit(PtnRuntime *runtime, const char *requested, size_t line) {
    int64_t max_value = ptn_parse_ini_quantity_operand(
        runtime,
        ptn_string_operand_borrowed(ptn_runtime_max_memory_limit(runtime)),
        line
    );
    if (max_value < 0) {
        ptn_runtime_set_memory_limit(runtime, requested);
        return;
    }

    int64_t requested_value = ptn_parse_ini_quantity_operand(
        runtime,
        ptn_string_operand_borrowed(requested),
        line
    );
    if (requested_value > max_value) {
        char message[192];
        snprintf(
            message,
            sizeof(message),
            "Failed to set memory_limit to %lld bytes. Setting to max_memory_limit instead (currently: %lld bytes)",
            (long long)requested_value,
            (long long)max_value
        );
        ptn_emit_sourced_ini_warning(runtime, message, line);
        ptn_runtime_set_memory_limit(runtime, ptn_runtime_max_memory_limit(runtime));
    } else if (requested_value < 0) {
        ptn_runtime_set_memory_limit(runtime, ptn_runtime_max_memory_limit(runtime));
    } else {
        ptn_runtime_set_memory_limit(runtime, requested);
    }
}

