static int ptn_iterator_to_array_key(
    PtnRuntime *runtime,
    PtnValue key_value,
    size_t line,
    PtnArrayKey *key_out
) {
    PtnValue key = ptn_value_deref(key_value);
    if (key.type == PTN_INT || key.type == PTN_STRING) {
        *key_out = ptn_array_key_from_value(key);
        return 1;
    }
    char message[160];
    int written = snprintf(
        message,
        sizeof(message),
        "Illegal offset type %s",
        ptn_offset_container_type_name(key)
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception_at(runtime, "TypeError", message, runtime->source_path, line);
    return 0;
}

static PtnValue ptn_internal_iterator_to_array(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnValue source = ptn_value_deref(args[0]);
    int preserve_keys = argc < 2 || ptn_is_truthy(args[1]);
    if (source.type != PTN_ARRAY && !(source.type == PTN_OBJECT && ptn_value_is_unpack_traversable(source))) {
        char message[192];
        int written = snprintf(
            message,
            sizeof(message),
            "iterator_to_array(): Argument #1 ($iterator) must be of type Traversable|array, %s given",
            ptn_count_operand_type_name(source)
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception_at(runtime, "TypeError", message, runtime->source_path, line);
        return ptn_null();
    }

    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    PtnArrayIterator iterator = ptn_array_iterator_from_value(
        runtime,
        source,
        NULL,
        runtime != NULL ? runtime->source_path : NULL,
        line
    );
    while (iterator.valid) {
        if (runtime != NULL && runtime->exceptions->active_exception != NULL) {
            break;
        }
        PtnValue key_value = ptn_array_iterator_current_key(&iterator);
        PtnValue value = ptn_array_iterator_current_value(&iterator);
        PtnArrayKey target_key;
        if (preserve_keys) {
            if (!ptn_iterator_to_array_key(runtime, key_value, line, &target_key)) {
                ptn_value_destroy(&key_value);
                ptn_value_destroy(&value);
                break;
            }
        } else {
            target_key = ptn_array_int_key(result.as.array->next_auto_key);
        }
        ptn_array_set_entry(result.as.array, target_key, ptn_value_clone_deref(value));
        ptn_value_destroy(&key_value);
        ptn_value_destroy(&value);
        ptn_array_iterator_advance(&iterator);
    }
    ptn_array_iterator_destroy(&iterator);
    return runtime != NULL && runtime->exceptions->active_exception != NULL ? ptn_null() : result;
}

static PtnValue ptn_internal_error_reporting(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    int64_t previous_level = runtime->diagnostics.error_reporting;
    if (argc >= 1) {
        PtnValue error_level = ptn_value_deref(args[0]);
        if (error_level.type == PTN_NULL) {
            return ptn_int(previous_level);
        }
        if (error_level.type != PTN_INT) {
            char message[192];
            int written = snprintf(
                message,
                sizeof(message),
                "error_reporting(): Argument #1 ($error_level) must be of type ?int, %s given",
                ptn_numeric_arg_type_name(error_level)
            );
            if (written < 0 || (size_t)written >= sizeof(message)) {
                ptn_abort_out_of_memory();
            }
            ptn_throw_exception_at(runtime, "TypeError", message, runtime->source_path, line);
            return ptn_null();
        }
        runtime->diagnostics.error_reporting = ptn_normalize_error_reporting(error_level.as.integer);
    }
    return ptn_int(previous_level);
}

static PtnValue ptn_internal_get_error_handler(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    PtnRuntime *root = ptn_runtime_root(runtime);
    if (root == NULL) {
        root = runtime;
    }
    return ptn_diagnostics_current_error_handler(&root->diagnostics);
}

static PtnValue ptn_internal_set_error_handler(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)line;
    PtnRuntime *root = ptn_runtime_root(runtime);
    if (root == NULL) {
        root = runtime;
    }
    PtnDiagnosticSink *diagnostics = &root->diagnostics;
    PtnValue previous = ptn_diagnostics_current_error_handler(diagnostics);

    PtnValue callback = ptn_value_deref(args[0]);
    if (callback.type == PTN_NULL) {
        ptn_diagnostics_push_error_handler(diagnostics, 0, ptn_null(), PTN_E_ALL);
        return previous;
    }

    PtnValue checked = ptn_internal_expect_callback_arg(
        runtime,
        "set_error_handler",
        1,
        "callback",
        args[0]
    );
    if (runtime->exceptions->active_exception != NULL) {
        ptn_value_destroy(&previous);
        return ptn_null();
    }

    int64_t levels = argc >= 2 ? ptn_normalize_error_reporting(ptn_value_to_integer(args[1])) : PTN_E_ALL;
    ptn_diagnostics_push_error_handler(diagnostics, 1, checked, levels);
    ptn_value_destroy(&checked);
    return previous;
}

static PtnValue ptn_internal_restore_error_handler(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    PtnRuntime *root = ptn_runtime_root(runtime);
    if (root == NULL) {
        root = runtime;
    }
    ptn_diagnostics_restore_error_handler(&root->diagnostics);
    return ptn_bool(1);
}

static PtnValue ptn_internal_get_exception_handler(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    return ptn_exception_handlers_current(runtime->exceptions);
}

static PtnValue ptn_internal_set_exception_handler(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)line;
    PtnValue previous = ptn_exception_handlers_current(runtime->exceptions);

    PtnValue callback = ptn_value_deref(args[0]);
    if (callback.type == PTN_NULL) {
        ptn_exception_handlers_push(runtime->exceptions, 0, ptn_null());
        return previous;
    }

    PtnValue checked = ptn_internal_expect_callback_arg(
        runtime,
        "set_exception_handler",
        1,
        "callback",
        args[0]
    );
    if (runtime->exceptions->active_exception != NULL) {
        ptn_value_destroy(&previous);
        return ptn_null();
    }

    ptn_exception_handlers_push(runtime->exceptions, 1, checked);
    ptn_value_destroy(&checked);
    return previous;
}

static PtnValue ptn_internal_restore_exception_handler(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    ptn_exception_handlers_restore(runtime->exceptions);
    return ptn_bool(1);
}

static PtnValue ptn_internal_trigger_error(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand message = ptn_internal_expect_string_arg(
        runtime,
        "trigger_error",
        1,
        "message",
        args[0],
        line
    );
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(message);
        return ptn_null();
    }
    int64_t level = argc >= 2
        ? ptn_internal_expect_integer_arg(runtime, "trigger_error", 2, "error_level", args[1], line)
        : PTN_E_USER_NOTICE;
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(message);
        return ptn_null();
    }
    char *owned_message = ptn_duplicate_string_len(message.data, message.len);
    ptn_string_operand_free(message);
    switch (level) {
        case PTN_E_USER_ERROR:
            if (!ptn_diagnostics_try_error_handler(
                &runtime->diagnostics,
                PTN_E_USER_ERROR,
                owned_message,
                runtime->source_path,
                line
            )) {
                ptn_throw_exception_at(runtime, "Error", owned_message, runtime->source_path, line);
            }
            break;
        case PTN_E_USER_WARNING:
            ptn_emit_user_warning(&runtime->diagnostics, owned_message, line);
            break;
        case PTN_E_USER_NOTICE:
            ptn_emit_user_notice(&runtime->diagnostics, owned_message, line);
            break;
        case PTN_E_USER_DEPRECATED:
            ptn_emit_user_deprecation(&runtime->diagnostics, owned_message, line);
            break;
        default:
            ptn_throw_exception(
                runtime,
                "ValueError",
                "trigger_error(): Argument #2 ($error_level) must be one of E_USER_ERROR, E_USER_WARNING, E_USER_NOTICE, or E_USER_DEPRECATED"
            );
            break;
    }
    free(owned_message);
    return ptn_bool(1);
}

static PtnValue ptn_internal_user_error(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    return ptn_internal_trigger_error(runtime, argc, args, line);
}

static PtnValue ptn_internal_error_log(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand message = ptn_internal_expect_string_arg(
        runtime,
        "error_log",
        1,
        "message",
        args[0],
        line
    );
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(message);
        return ptn_null();
    }
    int64_t message_type = argc >= 2
        ? ptn_internal_expect_integer_arg(runtime, "error_log", 2, "message_type", args[1], line)
        : 0;
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(message);
        return ptn_null();
    }
    if (message_type == 3) {
        PtnStringOperand destination = argc >= 3
            ? ptn_value_to_string_operand(args[2])
            : ptn_string_operand_borrowed_len("", 0);
        if (destination.len == 0) {
            ptn_string_operand_free(destination);
            ptn_string_operand_free(message);
            ptn_throw_exception(runtime, "ValueError", "Path must not be empty");
            return ptn_null();
        }
        char *path = ptn_duplicate_string_len(destination.data, destination.len);
        ptn_string_operand_free(destination);
        FILE *stream = fopen(path, "ab");
        free(path);
        if (stream == NULL) {
            ptn_string_operand_free(message);
            return ptn_bool(0);
        }
        fwrite(message.data, 1, message.len, stream);
        fclose(stream);
        ptn_string_operand_free(message);
        return ptn_bool(1);
    }
    fwrite(message.data, 1, message.len, stderr);
    fputc('\n', stderr);
    ptn_string_operand_free(message);
    return ptn_bool(1);
}

static PtnValue ptn_internal_register_tick_function(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)line;
    PtnValue callback = ptn_internal_expect_callback_arg(
        runtime,
        "register_tick_function",
        1,
        "callback",
        args[0]
    );
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    ptn_value_destroy(&callback);
    return ptn_bool(1);
}

static PtnValue ptn_internal_register_shutdown_function(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)line;
    PtnValue callback = ptn_internal_shutdown_callback_arg(runtime, args[0]);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    ptn_runtime_register_shutdown_function(
        runtime,
        callback,
        argc > 1 ? argc - 1 : 0,
        argc > 1 ? args + 1 : NULL
    );
    ptn_value_destroy(&callback);
    return ptn_bool(1);
}

static PtnOutputBuffer *ptn_output_buffer_top(PtnRuntime *runtime) {
    PtnRuntime *root = ptn_runtime_root(runtime);
    if (root == NULL || root->output_buffers_len == 0) {
        return NULL;
    }
    return &root->output_buffers[root->output_buffers_len - 1];
}

static PtnValue ptn_internal_ob_start(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    int has_callback = 0;
    PtnValue callback = ptn_null();
    size_t chunk_size = 0;
    if (argc >= 1) {
        PtnValue resolved = ptn_value_deref(args[0]);
        if (resolved.type != PTN_NULL) {
            callback = ptn_internal_expect_callback_arg(runtime, "ob_start", 1, "callback", args[0]);
            has_callback = 1;
        }
    }
    if (argc >= 2) {
        int64_t requested_chunk_size =
            ptn_internal_expect_integer_arg(runtime, "ob_start", 2, "chunk_size", args[1], line);
        if (requested_chunk_size > 0) {
            chunk_size = (size_t)requested_chunk_size;
        }
    }
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    ptn_output_buffer_push(runtime, has_callback, callback, chunk_size);
    if (has_callback) {
        ptn_value_destroy(&callback);
    }
    return ptn_bool(1);
}

static PtnValue ptn_internal_ob_get_contents(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    PtnOutputBuffer *buffer = ptn_output_buffer_top(runtime);
    if (buffer == NULL) {
        return ptn_bool(0);
    }
    return ptn_output_buffer_contents_value(buffer);
}

static PtnValue ptn_internal_ob_get_length(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    PtnOutputBuffer *buffer = ptn_output_buffer_top(runtime);
    if (buffer == NULL) {
        return ptn_bool(0);
    }
    if (buffer->buffer.len > (size_t)INT64_MAX) {
        ptn_abort_out_of_memory();
    }
    return ptn_int((int64_t)buffer->buffer.len);
}

static PtnValue ptn_internal_ob_get_level(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    PtnRuntime *root = ptn_runtime_root(runtime);
    size_t level = root == NULL ? 0 : root->output_buffers_len;
    if (level > (size_t)INT64_MAX) {
        ptn_abort_out_of_memory();
    }
    return ptn_int((int64_t)level);
}

static PtnValue ptn_internal_ob_list_handlers(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    PtnRuntime *root = ptn_runtime_root(runtime);
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    if (root == NULL) {
        return result;
    }
    for (size_t i = 0; i < root->output_buffers_len; i++) {
        PtnOutputBuffer *buffer = &root->output_buffers[i];
        PtnValue name = buffer->has_callback
            ? ptn_owned_string(ptn_callable_output_name(buffer->callback))
            : ptn_string("default output handler");
        if (i > (size_t)INT64_MAX) {
            ptn_abort_out_of_memory();
        }
        ptn_array_set_entry(result.as.array, ptn_array_int_key((int64_t)i), name);
    }
    return result;
}

static PtnValue ptn_internal_ob_clean(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    PtnOutputBuffer *buffer = ptn_output_buffer_top(runtime);
    if (buffer == NULL) {
        return ptn_bool(0);
    }
    buffer->buffer.len = 0;
    if (buffer->buffer.data != NULL) {
        buffer->buffer.data[0] = '\0';
    }
    return ptn_bool(1);
}

static PtnValue ptn_internal_ob_end_clean(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    return ptn_bool(ptn_output_buffer_close(runtime, 0, line));
}

static PtnValue ptn_internal_ob_end_flush(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    return ptn_bool(ptn_output_buffer_close(runtime, 1, line));
}

static PtnValue ptn_internal_ob_get_clean(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    PtnOutputBuffer *buffer = ptn_output_buffer_top(runtime);
    if (buffer == NULL) {
        return ptn_bool(0);
    }
    PtnValue contents = ptn_output_buffer_contents_value(buffer);
    (void)ptn_output_buffer_close(runtime, 0, line);
    return contents;
}

static PtnValue ptn_internal_ob_get_flush(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    PtnOutputBuffer *buffer = ptn_output_buffer_top(runtime);
    if (buffer == NULL) {
        return ptn_bool(0);
    }
    PtnValue contents = ptn_output_buffer_contents_value(buffer);
    (void)ptn_output_buffer_close(runtime, 1, line);
    return contents;
}

static PtnCallFrame *ptn_current_call_frame(PtnRuntime *runtime, const char *function_name) {
    if (runtime->call_frame != NULL) {
        return runtime->call_frame;
    }
    char message[128];
    const char *format = strcmp(function_name, "func_num_args") == 0
        ? "%s() must be called from a function context"
        : "%s() cannot be called from the global scope";
    int written = snprintf(message, sizeof(message), format, function_name);
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "Error", message);
    return NULL;
}

static PtnValue ptn_call_frame_arg_value(PtnRuntime *runtime, PtnCallFrame *frame, size_t position) {
    if (position < frame->parameter_count) {
        PtnValue value;
        if (ptn_symbols_get(&runtime->symbols, frame->parameter_names[position], &value)) {
            return ptn_value_clone_deref(value);
        }
    }
    if (position < frame->argc) {
        return ptn_value_clone_deref(frame->args[position]);
    }
    return ptn_null();
}

static PtnValue ptn_internal_func_num_args(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    PtnCallFrame *frame = ptn_current_call_frame(runtime, "func_num_args");
    if (frame->argc > (size_t)INT64_MAX) {
        ptn_abort_out_of_memory();
    }
    return ptn_int((int64_t)frame->argc);
}

static PtnValue ptn_internal_func_get_arg(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)line;
    PtnCallFrame *frame = ptn_current_call_frame(runtime, "func_get_arg");
    int64_t position = ptn_value_to_integer(args[0]);
    if (position < 0) {
        ptn_throw_exception(
            runtime,
            "ValueError",
            "func_get_arg(): Argument #1 ($position) must be greater than or equal to 0"
        );
    }
    if ((uint64_t)position >= (uint64_t)frame->argc) {
        ptn_throw_exception(
            runtime,
            "ValueError",
            "func_get_arg(): Argument #1 ($position) must be less than the number of the arguments passed to the currently executed function"
        );
    }
    return ptn_call_frame_arg_value(runtime, frame, (size_t)position);
}

static PtnValue ptn_internal_func_get_args(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    PtnCallFrame *frame = ptn_current_call_frame(runtime, "func_get_args");
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    for (size_t i = 0; i < frame->argc; i++) {
        if (i > (size_t)INT64_MAX) {
            ptn_abort_out_of_memory();
        }
        ptn_array_set_entry(
            result.as.array,
            ptn_array_int_key((int64_t)i),
            ptn_call_frame_arg_value(runtime, frame, i)
        );
    }
    return result;
}

static PtnValue ptn_internal_call_user_func(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    size_t previous_call_site_line = runtime->call_site_line;
    runtime->call_site_line = line;
    PtnValue callback = ptn_internal_expect_callback_arg(runtime, "call_user_func", 1, "callback", args[0]);
    if (runtime->exceptions->active_exception != NULL) {
        runtime->call_site_line = previous_call_site_line;
        return ptn_null();
    }
    int previous_warn_by_ref_argument_mismatch = runtime->warn_by_ref_argument_mismatch;
    runtime->warn_by_ref_argument_mismatch = 1;
    PtnValue result = ptn_internal_call_user_callback(
        runtime,
        callback,
        argc - 1,
        argc > 1 ? args + 1 : NULL,
        line
    );
    runtime->warn_by_ref_argument_mismatch = previous_warn_by_ref_argument_mismatch;
    ptn_value_destroy(&callback);
    runtime->call_site_line = previous_call_site_line;
    return result;
}

static PtnValue ptn_internal_call_user_func_array(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnArray *arguments = ptn_internal_expect_array_arg(runtime, "call_user_func_array", 2, "args", args[1]);
    size_t previous_call_site_line = runtime->call_site_line;
    runtime->call_site_line = line;
    PtnValue callback = ptn_internal_expect_callback_arg(runtime, "call_user_func_array", 1, "callback", args[0]);
    if (runtime->exceptions->active_exception != NULL) {
        runtime->call_site_line = previous_call_site_line;
        return ptn_null();
    }
    PtnValue *expanded = NULL;
    if (arguments->len != 0) {
        expanded = malloc(arguments->len * sizeof(PtnValue));
        if (expanded == NULL) {
            ptn_abort_out_of_memory();
        }
    }
    for (size_t i = 0; i < arguments->len; i++) {
        expanded[i] = ptn_value_clone(arguments->entries[i].value);
    }

    int previous_warn_by_ref_argument_mismatch = runtime->warn_by_ref_argument_mismatch;
    runtime->warn_by_ref_argument_mismatch = 1;
    PtnValue result = ptn_internal_call_user_callback(runtime, callback, arguments->len, expanded, line);
    runtime->warn_by_ref_argument_mismatch = previous_warn_by_ref_argument_mismatch;
    for (size_t i = 0; i < arguments->len; i++) {
        ptn_value_destroy(&expanded[i]);
    }
    free(expanded);
    ptn_value_destroy(&callback);
    runtime->call_site_line = previous_call_site_line;
    return result;
}

static PtnValue ptn_internal_forward_static_call(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    if (runtime->current_class_name == NULL && runtime->current_called_class_name == NULL) {
        ptn_throw_exception_at(
            runtime,
            "Error",
            "Cannot call forward_static_call() when no class scope is active",
            runtime->source_path,
            line
        );
        return ptn_null();
    }

    size_t previous_call_site_line = runtime->call_site_line;
    runtime->call_site_line = line;
    PtnValue callback = ptn_internal_expect_callback_arg(runtime, "forward_static_call", 1, "callback", args[0]);
    if (runtime->exceptions->active_exception != NULL) {
        runtime->call_site_line = previous_call_site_line;
        return ptn_null();
    }

    const char *previous_forward_static_called_class_name =
        runtime->forward_static_called_class_name;
    int previous_warn_by_ref_argument_mismatch = runtime->warn_by_ref_argument_mismatch;
    const char *forward_called_class = runtime->current_called_class_name != NULL
        ? runtime->current_called_class_name
        : runtime->current_class_name;
    runtime->forward_static_called_class_name = forward_called_class;
    runtime->warn_by_ref_argument_mismatch = 1;

    PtnValue result = ptn_null();
    int ok = ptn_internal_call_callback_capturing_exception_impl(
        runtime,
        callback,
        argc - 1,
        argc > 1 ? args + 1 : NULL,
        line,
        1,
        &result
    );

    runtime->warn_by_ref_argument_mismatch = previous_warn_by_ref_argument_mismatch;
    runtime->forward_static_called_class_name = previous_forward_static_called_class_name;
    ptn_value_destroy(&callback);
    runtime->call_site_line = previous_call_site_line;
    if (!ok) {
        ptn_rethrow_exception(runtime);
    }
    return result;
}

static int ptn_spl_object_id(PtnValue value, size_t *id_out) {
    value = ptn_value_deref(value);
    switch (value.type) {
        case PTN_OBJECT:
            *id_out = value.as.object->object_id;
            return 1;
        case PTN_CLOSURE:
            *id_out = value.as.closure->object_id;
            return 1;
        case PTN_EXCEPTION:
            *id_out = value.as.exception->object_id;
            return 1;
        case PTN_NULL:
        case PTN_BOOL:
        case PTN_INT:
        case PTN_FLOAT:
        case PTN_STRING:
        case PTN_RESOURCE:
        case PTN_ARRAY:
        case PTN_REFERENCE:
            return 0;
    }
    return 0;
}

static PtnValue ptn_internal_spl_object_id(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)line;
    size_t id = 0;
    if (ptn_spl_object_id(args[0], &id)) {
        return ptn_int((int64_t)id);
    }

    PtnValue value = ptn_value_deref(args[0]);
    char message[192];
    int written = snprintf(
        message,
        sizeof(message),
        "spl_object_id(): Argument #1 ($object) must be of type object, %s given",
        ptn_offset_container_type_name(value)
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "TypeError", message);
    return ptn_null();
}

static PtnValue ptn_internal_spl_object_hash(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)line;
    size_t id = 0;
    if (!ptn_spl_object_id(args[0], &id)) {
        PtnValue value = ptn_value_deref(args[0]);
        char message[192];
        int written = snprintf(
            message,
            sizeof(message),
            "spl_object_hash(): Argument #1 ($object) must be of type object, %s given",
            ptn_offset_container_type_name(value)
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "TypeError", message);
        return ptn_null();
    }

    char buffer[33];
    int written = snprintf(buffer, sizeof(buffer), "%016llx0000000000000000", (unsigned long long)id);
    if (written < 0 || written != 32) {
        ptn_abort_out_of_memory();
    }
    return ptn_owned_string(ptn_duplicate_string(buffer));
}

static PtnValue ptn_internal_assert_options(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)line;
    int64_t option = ptn_value_to_integer(args[0]);
    PtnValue previous = ptn_null();
    switch (option) {
        case 1:
            previous = ptn_int(ptn_runtime_assert_active(runtime));
            if (argc >= 2) {
                ptn_runtime_set_assert_active(runtime, ptn_is_truthy(args[1]));
            }
            return previous;
        case 2:
            previous = ptn_runtime_assert_callback(runtime);
            if (argc >= 2) {
                ptn_runtime_set_assert_callback_value(runtime, args[1]);
            }
            return previous;
        case 3:
            previous = ptn_int(ptn_runtime_assert_bail(runtime));
            if (argc >= 2) {
                ptn_runtime_set_assert_bail(runtime, ptn_is_truthy(args[1]));
            }
            return previous;
        case 4:
            previous = ptn_int(ptn_runtime_assert_warning(runtime));
            if (argc >= 2) {
                ptn_runtime_set_assert_warning(runtime, ptn_is_truthy(args[1]));
            }
            return previous;
        case 5:
            previous = ptn_int(ptn_runtime_assert_exception(runtime));
            if (argc >= 2) {
                ptn_runtime_set_assert_exception(runtime, ptn_is_truthy(args[1]));
            }
            return previous;
        default:
            ptn_throw_exception(runtime, "ValueError", "assert_options(): Argument #1 ($option) must be an ASSERT_* constant");
            return ptn_null();
    }
}

static char *ptn_assert_invalid_callback_reason(PtnRuntime *runtime, PtnValue callback) {
    PtnValue resolved = ptn_value_deref(callback);
    if (resolved.type == PTN_STRING) {
        char *name = ptn_value_to_string(resolved);
        int needed = snprintf(
            NULL,
            0,
            "function \"%s\" not found or invalid function name",
            name
        );
        if (needed < 0) {
            ptn_abort_out_of_memory();
        }
        char *reason = malloc((size_t)needed + 1);
        if (reason == NULL) {
            ptn_abort_out_of_memory();
        }
        snprintf(
            reason,
            (size_t)needed + 1,
            "function \"%s\" not found or invalid function name",
            name
        );
        free(name);
        return reason;
    }
    if (resolved.type == PTN_ARRAY) {
        char *reason = ptn_invalid_array_callback_reason(runtime, resolved);
        return reason == NULL ? ptn_duplicate_string("not a valid method callback") : reason;
    }
    return ptn_duplicate_string("no array or string given");
}

static void ptn_assert_set_invalid_callback_exception(PtnRuntime *runtime, PtnValue callback, size_t line) {
    char *name = ptn_callable_output_name(callback);
    char *reason = ptn_assert_invalid_callback_reason(runtime, callback);
    int needed = snprintf(NULL, 0, "Invalid callback %s, %s", name, reason);
    if (needed < 0) {
        ptn_abort_out_of_memory();
    }
    char *message = malloc((size_t)needed + 1);
    if (message == NULL) {
        ptn_abort_out_of_memory();
    }
    snprintf(message, (size_t)needed + 1, "Invalid callback %s, %s", name, reason);
    free(name);
    free(reason);
    PtnValue previous = ptn_exception_previous_or_active(runtime, ptn_null());
    PtnException *exception = ptn_exception_new_owned(
        runtime,
        "Error",
        message,
        strlen(message),
        0,
        previous,
        PTN_E_ERROR,
        runtime->source_path,
        line
    );
    ptn_exception_free(runtime->exceptions->active_exception);
    runtime->exceptions->active_exception = exception;
}

static void ptn_assert_set_assertion_exception(PtnRuntime *runtime, char *message, size_t line) {
    PtnValue previous = ptn_exception_previous_or_active(runtime, ptn_null());
    PtnException *exception = ptn_exception_new_owned(
        runtime,
        "AssertionError",
        message,
        strlen(message),
        0,
        previous,
        PTN_E_ERROR,
        runtime->source_path,
        line
    );
    ptn_exception_free(runtime->exceptions->active_exception);
    runtime->exceptions->active_exception = exception;
}

static PtnValue ptn_internal_assert(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    if (ptn_runtime_current_zend_assertions(runtime) <= 0) {
        return ptn_bool(1);
    }
    if (!ptn_runtime_assert_active(runtime)) {
        return ptn_bool(1);
    }
    if (ptn_is_truthy(args[0])) {
        return ptn_bool(1);
    }

    char *message = argc >= 2 ? ptn_value_to_string(args[1]) : ptn_duplicate_string("");
    int has_callback_exception = 0;
    PtnValue callback = ptn_null();
    if (ptn_runtime_assert_callback_configured(runtime)) {
        callback = ptn_runtime_assert_callback(runtime);
        if (ptn_callable_is_valid(runtime, callback, 0)) {
            PtnValue callback_args[4] = {
                ptn_owned_string(ptn_duplicate_string(runtime->source_path == NULL ? "" : runtime->source_path)),
                ptn_int((int64_t)line),
                ptn_null(),
                ptn_owned_string(ptn_duplicate_string(message))
            };
            PtnValue callback_result = ptn_null();
            int callback_succeeded = ptn_internal_call_callback_capturing_exception(
                runtime,
                callback,
                4,
                callback_args,
                line,
                &callback_result
            );
            for (size_t i = 0; i < 4; i++) {
                ptn_value_destroy(&callback_args[i]);
            }
            ptn_value_destroy(&callback_result);
            if (!callback_succeeded) {
                has_callback_exception = 1;
            }
        } else {
            ptn_assert_set_invalid_callback_exception(runtime, callback, line);
            has_callback_exception = 1;
        }
    }

    if (ptn_runtime_assert_exception(runtime)) {
        if (argc >= 2) {
            PtnValue reason = ptn_value_deref(args[1]);
            if (
                reason.type == PTN_EXCEPTION ||
                (reason.type == PTN_OBJECT && ptn_object_is_declared_throwable(runtime, reason.as.object))
            ) {
                if (
                    runtime->trace_frame != NULL &&
                    runtime->trace_frame->function_name != NULL &&
                    ptn_exception_name_equal(runtime->trace_frame->function_name, "assert")
                ) {
                    runtime->trace_frame = runtime->trace_frame->previous;
                }
                ptn_throw_value(runtime, reason, runtime->source_path, line);
                ptn_value_destroy(&callback);
                free(message);
                return ptn_bool(0);
            }
        }
        ptn_assert_set_assertion_exception(runtime, message, line);
        if (ptn_runtime_assert_bail(runtime)) {
            ptn_value_destroy(&callback);
            ptn_emit_uncaught_exception(runtime, runtime->exceptions->active_exception);
            exit(255);
        }
        ptn_value_destroy(&callback);
        ptn_rethrow_exception(runtime);
        return ptn_bool(0);
    } else {
        if (ptn_runtime_assert_warning(runtime)) {
            size_t message_len = strlen(message);
            const char *prefix = "assert(): ";
            const char *suffix = " failed";
            size_t warning_len = strlen(prefix) + message_len + strlen(suffix);
            char *warning = malloc(warning_len + 1);
            if (warning == NULL) {
                ptn_value_destroy(&callback);
                free(message);
                ptn_abort_out_of_memory();
            }
            snprintf(warning, warning_len + 1, "%s%s%s", prefix, message, suffix);
            ptn_emit_warning(&runtime->diagnostics, warning, line);
            free(warning);
        }
        if (has_callback_exception) {
            if (ptn_runtime_assert_bail(runtime)) {
                ptn_value_destroy(&callback);
                free(message);
                ptn_emit_uncaught_exception_warning(runtime, runtime->exceptions->active_exception);
                exit(0);
            }
            ptn_value_destroy(&callback);
            free(message);
            ptn_rethrow_exception(runtime);
            return ptn_null();
        }
        if (ptn_runtime_assert_bail(runtime)) {
            ptn_value_destroy(&callback);
            free(message);
            exit(0);
        }
    }
    ptn_value_destroy(&callback);
    free(message);
    return ptn_bool(0);
}

static const char *ptn_date_weekday_short(int wday) {
    static const char *names[] = { "Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat" };
    return names[wday >= 0 && wday < 7 ? wday : 0];
}

static const char *ptn_date_weekday_long(int wday) {
    static const char *names[] = { "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday" };
    return names[wday >= 0 && wday < 7 ? wday : 0];
}

static const char *ptn_date_month_short(int mon) {
    static const char *names[] = { "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" };
    return names[mon >= 0 && mon < 12 ? mon : 0];
}

static const char *ptn_date_month_long(int mon) {
    static const char *names[] = {
        "January", "February", "March", "April", "May", "June",
        "July", "August", "September", "October", "November", "December"
    };
    return names[mon >= 0 && mon < 12 ? mon : 0];
}

static int ptn_date_is_leap_year(int year) {
    return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
}

static int ptn_date_days_in_month(int year, int month) {
    static const int days[] = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
    if (month == 2 && ptn_date_is_leap_year(year)) {
        return 29;
    }
    return month >= 1 && month <= 12 ? days[month - 1] : 31;
}

static int ptn_date_weekday_for_date(int year, int month, int day) {
    static const int offsets[] = { 0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4 };
    if (month < 3) {
        year--;
    }
    int weekday = (year + year / 4 - year / 100 + year / 400 + offsets[month - 1] + day) % 7;
    return weekday < 0 ? weekday + 7 : weekday;
}

static int ptn_date_iso_weeks_in_year(int year) {
    int jan1 = ptn_date_weekday_for_date(year, 1, 1);
    int jan1_iso = jan1 == 0 ? 7 : jan1;
    return jan1_iso == 4 || (jan1_iso == 3 && ptn_date_is_leap_year(year)) ? 53 : 52;
}

static void ptn_date_iso_week_info(const struct tm *parts, int *iso_year_out, int *iso_week_out) {
    int year = parts->tm_year + 1900;
    int iso_weekday = parts->tm_wday == 0 ? 7 : parts->tm_wday;
    int ordinal = parts->tm_yday + 1;
    int week = (ordinal - iso_weekday + 10) / 7;
    if (week < 1) {
        year--;
        week = ptn_date_iso_weeks_in_year(year);
    } else {
        int weeks_in_year = ptn_date_iso_weeks_in_year(year);
        if (week > weeks_in_year) {
            year++;
            week = 1;
        }
    }
    *iso_year_out = year;
    *iso_week_out = week;
}

static const char *ptn_date_day_suffix(int day) {
    if (day >= 11 && day <= 13) {
        return "th";
    }
    switch (day % 10) {
        case 1:
            return "st";
        case 2:
            return "nd";
        case 3:
            return "rd";
        default:
            return "th";
    }
}

static void ptn_tzset(void) {
#if defined(_WIN32)
    _tzset();
#else
    tzset();
#endif
}

static void ptn_set_timezone_env(const char *timezone) {
#if defined(_WIN32)
    size_t len = strlen(timezone) + 4;
    char *assignment = malloc(len);
    if (assignment == NULL) {
        ptn_abort_out_of_memory();
    }
    snprintf(assignment, len, "TZ=%s", timezone);
    _putenv(assignment);
    free(assignment);
#else
    setenv("TZ", timezone, 1);
#endif
    ptn_tzset();
}

static const char *ptn_current_timezone_name(void) {
    const char *timezone = getenv("TZ");
    if (timezone != NULL && timezone[0] != '\0') {
        return timezone;
    }
    timezone = getenv("PTN_DATE_TIMEZONE");
    return timezone != NULL && timezone[0] != '\0' ? timezone : "UTC";
}

static int ptn_timezone_identifier_is_known(const char *name);
static int ptn_timezone_uses_z_designator(const char *name);

static int ptn_timezone_name_is_supported(PtnStringOperand timezone) {
    if (timezone.len == 0 || memchr(timezone.data, '\0', timezone.len) != NULL) {
        return 0;
    }
    char *name = ptn_duplicate_string_len(timezone.data, timezone.len);
    int supported = ptn_timezone_identifier_is_known(name);
    free(name);
    return supported;
}

static time_t ptn_mktime_in_utc(struct tm *parts) {
    const char *old_tz = getenv("TZ");
    char *old_copy = old_tz == NULL ? NULL : ptn_duplicate_string(old_tz);
    ptn_set_timezone_env("UTC");
    time_t result = mktime(parts);
    if (old_copy == NULL) {
#if defined(_WIN32)
        _putenv("TZ=");
#else
        unsetenv("TZ");
#endif
        ptn_tzset();
    } else {
        ptn_set_timezone_env(old_copy);
        free(old_copy);
    }
    return result;
}

static int64_t ptn_date_timezone_offset(time_t timestamp) {
    struct tm utc_parts;
    struct tm *utc = gmtime(&timestamp);
    if (utc == NULL) {
        return 0;
    }
    utc_parts = *utc;
    utc_parts.tm_isdst = -1;
    time_t local_interpretation = mktime(&utc_parts);
    if (local_interpretation == (time_t)-1) {
        return 0;
    }
    return (int64_t)difftime(timestamp, local_interpretation);
}

static void ptn_date_append_offset(PtnStringBuffer *buffer, int64_t offset, int colon) {
    char sign = offset < 0 ? '-' : '+';
    int64_t absolute = offset < 0 ? -offset : offset;
    int64_t hours = absolute / 3600;
    int64_t minutes = (absolute % 3600) / 60;
    if (colon) {
        ptn_string_buffer_append_format(buffer, "%c%02lld:%02lld", sign, (long long)hours, (long long)minutes);
    } else {
        ptn_string_buffer_append_format(buffer, "%c%02lld%02lld", sign, (long long)hours, (long long)minutes);
    }
}

static int ptn_date_swatch_beats(time_t timestamp) {
    struct tm *utc = gmtime(&timestamp);
    if (utc == NULL) {
        return 0;
    }
    int seconds = utc->tm_hour * 3600 + utc->tm_min * 60 + utc->tm_sec + 3600;
    seconds %= 86400;
    if (seconds < 0) {
        seconds += 86400;
    }
    return (int)floor((double)seconds / 86.4);
}

static PtnValue ptn_format_date_value(PtnRuntime *runtime, const char *function_name, PtnStringOperand format, time_t timestamp, int use_gmt, size_t line) {
    (void)runtime;
    (void)function_name;
    (void)line;
    struct tm parts_storage;
    struct tm *parts = use_gmt ? gmtime(&timestamp) : localtime(&timestamp);
    if (parts == NULL) {
        return ptn_bool(0);
    }
    parts_storage = *parts;
    parts = &parts_storage;

    PtnStringBuffer buffer;
    ptn_string_buffer_init(&buffer);
    int year = parts->tm_year + 1900;
    int month = parts->tm_mon + 1;
    int64_t offset = use_gmt ? 0 : ptn_date_timezone_offset(timestamp);
    for (size_t i = 0; i < format.len; i++) {
        char ch = format.data[i];
        if (ch == '\\' && i + 1 < format.len) {
            i++;
            ptn_string_buffer_append_char(&buffer, format.data[i]);
            continue;
        }
        switch (ch) {
            case 'D':
                ptn_string_buffer_append(&buffer, ptn_date_weekday_short(parts->tm_wday));
                break;
            case 'l':
                ptn_string_buffer_append(&buffer, ptn_date_weekday_long(parts->tm_wday));
                break;
            case 'N':
                ptn_string_buffer_append_format(&buffer, "%d", parts->tm_wday == 0 ? 7 : parts->tm_wday);
                break;
            case 'w':
                ptn_string_buffer_append_format(&buffer, "%d", parts->tm_wday);
                break;
            case 'z':
                ptn_string_buffer_append_format(&buffer, "%d", parts->tm_yday);
                break;
            case 'W': {
                int iso_year = 0;
                int iso_week = 0;
                ptn_date_iso_week_info(parts, &iso_year, &iso_week);
                (void)iso_year;
                ptn_string_buffer_append_format(&buffer, "%02d", iso_week);
                break;
            }
            case 'o': {
                int iso_year = 0;
                int iso_week = 0;
                ptn_date_iso_week_info(parts, &iso_year, &iso_week);
                (void)iso_week;
                ptn_string_buffer_append_format(&buffer, "%04d", iso_year);
                break;
            }
            case 'c':
                ptn_string_buffer_append_format(&buffer, "%04d-%02d-%02dT%02d:%02d:%02d", year, month, parts->tm_mday, parts->tm_hour, parts->tm_min, parts->tm_sec);
                ptn_date_append_offset(&buffer, offset, 1);
                break;
            case 'r':
                ptn_string_buffer_append_format(
                    &buffer,
                    "%s, %02d %s %04d %02d:%02d:%02d ",
                    ptn_date_weekday_short(parts->tm_wday),
                    parts->tm_mday,
                    ptn_date_month_short(parts->tm_mon),
                    year,
                    parts->tm_hour,
                    parts->tm_min,
                    parts->tm_sec
                );
                ptn_date_append_offset(&buffer, offset, 0);
                break;
            case 'F':
                ptn_string_buffer_append(&buffer, ptn_date_month_long(parts->tm_mon));
                break;
            case 'M':
                ptn_string_buffer_append(&buffer, ptn_date_month_short(parts->tm_mon));
                break;
            case 'Y':
                ptn_string_buffer_append_format(&buffer, "%04d", year);
                break;
            case 'X':
                ptn_string_buffer_append_format(&buffer, "%+05d", year);
                break;
            case 'y':
                ptn_string_buffer_append_format(&buffer, "%02d", year % 100);
                break;
            case 'm':
                ptn_string_buffer_append_format(&buffer, "%02d", month);
                break;
            case 'n':
                ptn_string_buffer_append_format(&buffer, "%d", month);
                break;
            case 't':
                ptn_string_buffer_append_format(&buffer, "%d", ptn_date_days_in_month(year, month));
                break;
            case 'L':
                ptn_string_buffer_append_format(&buffer, "%d", ptn_date_is_leap_year(year));
                break;
            case 'd':
                ptn_string_buffer_append_format(&buffer, "%02d", parts->tm_mday);
                break;
            case 'j':
                ptn_string_buffer_append_format(&buffer, "%d", parts->tm_mday);
                break;
            case 'S':
                ptn_string_buffer_append(&buffer, ptn_date_day_suffix(parts->tm_mday));
                break;
            case 'a':
                ptn_string_buffer_append(&buffer, parts->tm_hour < 12 ? "am" : "pm");
                break;
            case 'A':
                ptn_string_buffer_append(&buffer, parts->tm_hour < 12 ? "AM" : "PM");
                break;
            case 'B':
                ptn_string_buffer_append_format(&buffer, "%03d", ptn_date_swatch_beats(timestamp));
                break;
            case 'g': {
                int hour = parts->tm_hour % 12;
                if (hour == 0) {
                    hour = 12;
                }
                ptn_string_buffer_append_format(&buffer, "%d", hour);
                break;
            }
            case 'G':
                ptn_string_buffer_append_format(&buffer, "%d", parts->tm_hour);
                break;
            case 'H':
                ptn_string_buffer_append_format(&buffer, "%02d", parts->tm_hour);
                break;
            case 'h': {
                int hour = parts->tm_hour % 12;
                if (hour == 0) {
                    hour = 12;
                }
                ptn_string_buffer_append_format(&buffer, "%02d", hour);
                break;
            }
            case 'i':
                ptn_string_buffer_append_format(&buffer, "%02d", parts->tm_min);
                break;
            case 's':
                ptn_string_buffer_append_format(&buffer, "%02d", parts->tm_sec);
                break;
            case 'v':
                ptn_string_buffer_append(&buffer, "000");
                break;
            case 'I':
                ptn_string_buffer_append_format(&buffer, "%d", parts->tm_isdst > 0 ? 1 : 0);
                break;
            case 'O':
                ptn_date_append_offset(&buffer, offset, 0);
                break;
            case 'P':
                ptn_date_append_offset(&buffer, offset, 1);
                break;
            case 'p':
                if (offset == 0 && ptn_timezone_uses_z_designator(use_gmt ? "UTC" : ptn_current_timezone_name())) {
                    ptn_string_buffer_append_char(&buffer, 'Z');
                } else {
                    ptn_date_append_offset(&buffer, offset, 1);
                }
                break;
            case 'T': {
                char zone[64];
                if (strftime(zone, sizeof(zone), "%Z", parts) == 0) {
                    zone[0] = '\0';
                }
                ptn_string_buffer_append(&buffer, use_gmt ? "GMT" : zone);
                break;
            }
            case 'e':
                ptn_string_buffer_append(&buffer, use_gmt ? "UTC" : ptn_current_timezone_name());
                break;
            case 'Z':
                ptn_string_buffer_append_format(&buffer, "%lld", (long long)offset);
                break;
            case 'U':
                ptn_string_buffer_append_format(&buffer, "%lld", (long long)timestamp);
                break;
            default:
                ptn_string_buffer_append_char(&buffer, ch);
                break;
        }
    }
    return ptn_owned_string_len(buffer.data, buffer.len);
}

static int ptn_timezone_offset_for_name(const char *name, time_t timestamp);
static int ptn_datetime_timestamp_dst_month(time_t timestamp);
static const char *ptn_timezone_abbreviation_for_name(const char *name, time_t timestamp);

static PtnValue ptn_format_date_value_for_timezone(
    PtnRuntime *runtime,
    const char *function_name,
    PtnStringOperand format,
    time_t timestamp,
    int microsecond,
    const char *timezone,
    size_t line
) {
    (void)runtime;
    (void)function_name;
    (void)line;
    int64_t offset = ptn_timezone_offset_for_name(timezone, timestamp);
    time_t wall_timestamp = timestamp + offset;
    struct tm parts_storage;
    struct tm *parts = gmtime(&wall_timestamp);
    if (parts == NULL) {
        return ptn_bool(0);
    }
    parts_storage = *parts;
    parts = &parts_storage;

    PtnStringBuffer buffer;
    ptn_string_buffer_init(&buffer);
    int year = parts->tm_year + 1900;
    int month = parts->tm_mon + 1;
    for (size_t i = 0; i < format.len; i++) {
        char ch = format.data[i];
        if (ch == '\\' && i + 1 < format.len) {
            i++;
            ptn_string_buffer_append_char(&buffer, format.data[i]);
            continue;
        }
        switch (ch) {
            case 'D':
                ptn_string_buffer_append(&buffer, ptn_date_weekday_short(parts->tm_wday));
                break;
            case 'l':
                ptn_string_buffer_append(&buffer, ptn_date_weekday_long(parts->tm_wday));
                break;
            case 'N':
                ptn_string_buffer_append_format(&buffer, "%d", parts->tm_wday == 0 ? 7 : parts->tm_wday);
                break;
            case 'w':
                ptn_string_buffer_append_format(&buffer, "%d", parts->tm_wday);
                break;
            case 'z':
                ptn_string_buffer_append_format(&buffer, "%d", parts->tm_yday);
                break;
            case 'W': {
                int iso_year = 0;
                int iso_week = 0;
                ptn_date_iso_week_info(parts, &iso_year, &iso_week);
                (void)iso_year;
                ptn_string_buffer_append_format(&buffer, "%02d", iso_week);
                break;
            }
            case 'o': {
                int iso_year = 0;
                int iso_week = 0;
                ptn_date_iso_week_info(parts, &iso_year, &iso_week);
                (void)iso_week;
                ptn_string_buffer_append_format(&buffer, "%04d", iso_year);
                break;
            }
            case 'c':
                ptn_string_buffer_append_format(&buffer, "%04d-%02d-%02dT%02d:%02d:%02d", year, month, parts->tm_mday, parts->tm_hour, parts->tm_min, parts->tm_sec);
                ptn_date_append_offset(&buffer, offset, 1);
                break;
            case 'r':
                ptn_string_buffer_append_format(
                    &buffer,
                    "%s, %02d %s %04d %02d:%02d:%02d ",
                    ptn_date_weekday_short(parts->tm_wday),
                    parts->tm_mday,
                    ptn_date_month_short(parts->tm_mon),
                    year,
                    parts->tm_hour,
                    parts->tm_min,
                    parts->tm_sec
                );
                ptn_date_append_offset(&buffer, offset, 0);
                break;
            case 'F':
                ptn_string_buffer_append(&buffer, ptn_date_month_long(parts->tm_mon));
                break;
            case 'M':
                ptn_string_buffer_append(&buffer, ptn_date_month_short(parts->tm_mon));
                break;
            case 'Y':
                ptn_string_buffer_append_format(&buffer, "%04d", year);
                break;
            case 'X':
                ptn_string_buffer_append_format(&buffer, "%+05d", year);
                break;
            case 'y':
                ptn_string_buffer_append_format(&buffer, "%02d", year % 100);
                break;
            case 'm':
                ptn_string_buffer_append_format(&buffer, "%02d", month);
                break;
            case 'n':
                ptn_string_buffer_append_format(&buffer, "%d", month);
                break;
            case 't':
                ptn_string_buffer_append_format(&buffer, "%d", ptn_date_days_in_month(year, month));
                break;
            case 'L':
                ptn_string_buffer_append_format(&buffer, "%d", ptn_date_is_leap_year(year));
                break;
            case 'd':
                ptn_string_buffer_append_format(&buffer, "%02d", parts->tm_mday);
                break;
            case 'j':
                ptn_string_buffer_append_format(&buffer, "%d", parts->tm_mday);
                break;
            case 'S':
                ptn_string_buffer_append(&buffer, ptn_date_day_suffix(parts->tm_mday));
                break;
            case 'a':
                ptn_string_buffer_append(&buffer, parts->tm_hour < 12 ? "am" : "pm");
                break;
            case 'A':
                ptn_string_buffer_append(&buffer, parts->tm_hour < 12 ? "AM" : "PM");
                break;
            case 'B':
                ptn_string_buffer_append_format(&buffer, "%03d", ptn_date_swatch_beats(timestamp));
                break;
            case 'g': {
                int hour = parts->tm_hour % 12;
                if (hour == 0) {
                    hour = 12;
                }
                ptn_string_buffer_append_format(&buffer, "%d", hour);
                break;
            }
            case 'G':
                ptn_string_buffer_append_format(&buffer, "%d", parts->tm_hour);
                break;
            case 'H':
                ptn_string_buffer_append_format(&buffer, "%02d", parts->tm_hour);
                break;
            case 'h': {
                int hour = parts->tm_hour % 12;
                if (hour == 0) {
                    hour = 12;
                }
                ptn_string_buffer_append_format(&buffer, "%02d", hour);
                break;
            }
            case 'i':
                ptn_string_buffer_append_format(&buffer, "%02d", parts->tm_min);
                break;
            case 's':
                ptn_string_buffer_append_format(&buffer, "%02d", parts->tm_sec);
                break;
            case 'u':
                ptn_string_buffer_append_format(&buffer, "%06d", microsecond);
                break;
            case 'v':
                ptn_string_buffer_append_format(&buffer, "%03d", microsecond / 1000);
                break;
            case 'I':
                ptn_string_buffer_append_format(&buffer, "%d", offset != 0 && ptn_datetime_timestamp_dst_month(timestamp) ? 1 : 0);
                break;
            case 'O':
                ptn_date_append_offset(&buffer, offset, 0);
                break;
            case 'P':
                ptn_date_append_offset(&buffer, offset, 1);
                break;
            case 'p':
                if (offset == 0 && ptn_timezone_uses_z_designator(timezone)) {
                    ptn_string_buffer_append_char(&buffer, 'Z');
                } else {
                    ptn_date_append_offset(&buffer, offset, 1);
                }
                break;
            case 'T':
                ptn_string_buffer_append(&buffer, ptn_timezone_abbreviation_for_name(timezone, timestamp));
                break;
            case 'e':
                ptn_string_buffer_append(&buffer, timezone);
                break;
            case 'Z':
                ptn_string_buffer_append_format(&buffer, "%lld", (long long)offset);
                break;
            case 'U':
                ptn_string_buffer_append_format(&buffer, "%lld", (long long)timestamp);
                break;
            default:
                ptn_string_buffer_append_char(&buffer, ch);
                break;
        }
    }
    return ptn_owned_string_len(buffer.data, buffer.len);
}

static time_t ptn_date_mktime_from_args(size_t argc, const PtnValue *args, int use_gmt) {
    time_t now = time(NULL);
    struct tm parts_storage;
    struct tm *current = use_gmt ? gmtime(&now) : localtime(&now);
    if (current == NULL) {
        memset(&parts_storage, 0, sizeof(parts_storage));
        parts_storage.tm_mday = 1;
        parts_storage.tm_year = 70;
    } else {
        parts_storage = *current;
    }
    if (argc >= 1) {
        parts_storage.tm_hour = (int)ptn_value_to_integer(args[0]);
    }
    if (argc >= 2) {
        parts_storage.tm_min = (int)ptn_value_to_integer(args[1]);
    }
    if (argc >= 3) {
        parts_storage.tm_sec = (int)ptn_value_to_integer(args[2]);
    }
    if (argc >= 4) {
        parts_storage.tm_mon = (int)ptn_value_to_integer(args[3]) - 1;
    }
    if (argc >= 5) {
        parts_storage.tm_mday = (int)ptn_value_to_integer(args[4]);
    }
    if (argc >= 6) {
        parts_storage.tm_year = (int)ptn_value_to_integer(args[5]) - 1900;
    }
    parts_storage.tm_isdst = -1;
    return use_gmt ? ptn_mktime_in_utc(&parts_storage) : mktime(&parts_storage);
}

static PtnValue ptn_internal_date(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand format = ptn_internal_expect_string_arg(runtime, "date", 1, "format", args[0], line);
    time_t timestamp = argc >= 2 ? (time_t)ptn_value_to_integer(args[1]) : time(NULL);
    PtnValue result = ptn_format_date_value(runtime, "date", format, timestamp, 0, line);
    ptn_string_operand_free(format);
    return result;
}

static PtnValue ptn_internal_gmdate(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand format = ptn_internal_expect_string_arg(runtime, "gmdate", 1, "format", args[0], line);
    time_t timestamp = argc >= 2 ? (time_t)ptn_value_to_integer(args[1]) : time(NULL);
    PtnValue result = ptn_format_date_value(runtime, "gmdate", format, timestamp, 1, line);
    ptn_string_operand_free(format);
    return result;
}

static PtnValue ptn_internal_strftime_named(PtnRuntime *runtime, const char *function_name, int use_gmt, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand format = ptn_internal_expect_string_arg(runtime, function_name, 1, "format", args[0], line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(format);
        return ptn_null();
    }
    time_t timestamp = argc >= 2 && ptn_value_deref(args[1]).type != PTN_NULL
        ? (time_t)ptn_value_to_integer(args[1])
        : time(NULL);
    struct tm parts_storage;
    struct tm *parts = use_gmt ? gmtime(&timestamp) : localtime(&timestamp);
    if (parts == NULL) {
        ptn_string_operand_free(format);
        return ptn_bool(0);
    }
    parts_storage = *parts;

    if (format.len == 0) {
        ptn_string_operand_free(format);
        return ptn_string("");
    }

    char *format_c = ptn_duplicate_string_len(format.data, format.len);
    if (format.len > (SIZE_MAX - 64) / 4) {
        free(format_c);
        ptn_string_operand_free(format);
        ptn_abort_out_of_memory();
    }
    size_t cap = (format.len * 4) + 64;
    if (cap < 128) {
        cap = 128;
    }
    for (;;) {
        char *output = malloc(cap);
        if (output == NULL) {
            free(format_c);
            ptn_string_operand_free(format);
            ptn_abort_out_of_memory();
        }
        size_t written = strftime(output, cap, format_c, &parts_storage);
        if (written > 0) {
            free(format_c);
            ptn_string_operand_free(format);
            return ptn_owned_string_len(output, written);
        }
        free(output);
        if (cap >= (1u << 20)) {
            free(format_c);
            ptn_string_operand_free(format);
            return ptn_string("");
        }
        cap *= 2;
    }
}

static PtnValue ptn_internal_strftime(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    return ptn_internal_strftime_named(runtime, "strftime", 0, argc, args, line);
}

static PtnValue ptn_internal_gmstrftime(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    return ptn_internal_strftime_named(runtime, "gmstrftime", 1, argc, args, line);
}

static PtnValue ptn_internal_mktime(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)line;
    return ptn_int((int64_t)ptn_date_mktime_from_args(argc, args, 0));
}

static PtnValue ptn_internal_gmmktime(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)line;
    return ptn_int((int64_t)ptn_date_mktime_from_args(argc, args, 1));
}

static PtnValue ptn_internal_time(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)argc;
    (void)args;
    (void)line;
    return ptn_int((int64_t)time(NULL));
}

static PtnValue ptn_internal_microtime(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)line;
    struct timeval now;
    if (gettimeofday(&now, NULL) != 0) {
        return ptn_bool(0);
    }
    double seconds = (double)now.tv_sec + ((double)now.tv_usec / 1000000.0);
    if (argc >= 1 && ptn_is_truthy(args[0])) {
        return ptn_float(seconds);
    }
    char buffer[64];
    int written = snprintf(buffer, sizeof(buffer), "%.6f %lld", (double)now.tv_usec / 1000000.0, (long long)now.tv_sec);
    if (written < 0 || (size_t)written >= sizeof(buffer)) {
        ptn_abort_out_of_memory();
    }
    return ptn_owned_string(ptn_duplicate_string(buffer));
}

static PtnValue ptn_internal_date_default_timezone_get(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)argc;
    (void)args;
    (void)line;
    return ptn_string(ptn_current_timezone_name());
}

static PtnValue ptn_internal_date_default_timezone_set(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand timezone = ptn_internal_expect_string_arg(runtime, "date_default_timezone_set", 1, "timezoneId", args[0], line);
    if (!ptn_timezone_name_is_supported(timezone)) {
        char *name = ptn_duplicate_string_len(timezone.data, timezone.len);
        size_t message_len = strlen(name) + 64;
        char *message = malloc(message_len);
        if (message == NULL) {
            free(name);
            ptn_abort_out_of_memory();
        }
        snprintf(message, message_len, "date_default_timezone_set(): Timezone ID '%s' is invalid", name);
        int leading_newline = runtime->diagnostics.emitted_warning;
        ptn_emit_notice_with_path(&runtime->diagnostics, message, runtime->source_path, line, leading_newline);
        runtime->diagnostics.emitted_warning = 1;
        free(message);
        free(name);
        ptn_string_operand_free(timezone);
        return ptn_bool(0);
    }
    char *name = ptn_duplicate_string_len(timezone.data, timezone.len);
    ptn_set_timezone_env(name);
    free(name);
    ptn_string_operand_free(timezone);
    return ptn_bool(1);
}

static PtnValue ptn_internal_checkdate(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)argc;
    (void)line;
    int month = (int)ptn_value_to_integer(args[0]);
    int day = (int)ptn_value_to_integer(args[1]);
    int year = (int)ptn_value_to_integer(args[2]);
    if (year < 1 || year > 32767 || month < 1 || month > 12 || day < 1) {
        return ptn_bool(0);
    }
    return ptn_bool(day <= ptn_date_days_in_month(year, month));
}

static int ptn_idate_value(char token, const struct tm *parts, time_t timestamp, int64_t offset, int *out) {
    int year = parts->tm_year + 1900;
    int month = parts->tm_mon + 1;
    switch (token) {
        case 'B':
            *out = ptn_date_swatch_beats(timestamp);
            return 1;
        case 'd':
            *out = parts->tm_mday;
            return 1;
        case 'h': {
            int hour = parts->tm_hour % 12;
            *out = hour == 0 ? 12 : hour;
            return 1;
        }
        case 'H':
            *out = parts->tm_hour;
            return 1;
        case 'i':
            *out = parts->tm_min;
            return 1;
        case 'I':
            *out = parts->tm_isdst > 0 ? 1 : 0;
            return 1;
        case 'L':
            *out = ptn_date_is_leap_year(year);
            return 1;
        case 'm':
        case 'n':
            *out = month;
            return 1;
        case 's':
            *out = parts->tm_sec;
            return 1;
        case 't':
            *out = ptn_date_days_in_month(year, month);
            return 1;
        case 'U':
            *out = (int)timestamp;
            return 1;
        case 'w':
            *out = parts->tm_wday;
            return 1;
        case 'W': {
            int iso_year = 0;
            int iso_week = 0;
            ptn_date_iso_week_info(parts, &iso_year, &iso_week);
            (void)iso_year;
            *out = iso_week;
            return 1;
        }
        case 'y':
            *out = year % 100;
            return 1;
        case 'Y':
            *out = year;
            return 1;
        case 'z':
            *out = parts->tm_yday;
            return 1;
        case 'Z':
            *out = (int)offset;
            return 1;
        default:
            return 0;
    }
}

static PtnValue ptn_internal_idate(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand format = ptn_internal_expect_string_arg(runtime, "idate", 1, "format", args[0], line);
    if (format.len != 1) {
        ptn_emit_warning(&runtime->diagnostics, "idate(): idate format is one char", line);
        ptn_string_operand_free(format);
        return ptn_bool(0);
    }
    time_t timestamp = argc >= 2 ? (time_t)ptn_value_to_integer(args[1]) : time(NULL);
    struct tm *parts = localtime(&timestamp);
    if (parts == NULL) {
        ptn_string_operand_free(format);
        return ptn_bool(0);
    }
    int value = 0;
    if (!ptn_idate_value(format.data[0], parts, timestamp, ptn_date_timezone_offset(timestamp), &value)) {
        ptn_emit_warning(&runtime->diagnostics, "idate(): Unrecognized date format token", line);
        ptn_string_operand_free(format);
        return ptn_bool(0);
    }
    ptn_string_operand_free(format);
    return ptn_int(value);
}

static PtnValue ptn_internal_getdate(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)line;
    time_t timestamp = argc >= 1 ? (time_t)ptn_value_to_integer(args[0]) : time(NULL);
    struct tm *parts = localtime(&timestamp);
    if (parts == NULL) {
        return ptn_bool(0);
    }
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    ptn_array_set_entry(result.as.array, ptn_array_string_key("seconds"), ptn_int(parts->tm_sec));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("minutes"), ptn_int(parts->tm_min));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("hours"), ptn_int(parts->tm_hour));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("mday"), ptn_int(parts->tm_mday));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("wday"), ptn_int(parts->tm_wday));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("mon"), ptn_int(parts->tm_mon + 1));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("year"), ptn_int(parts->tm_year + 1900));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("yday"), ptn_int(parts->tm_yday));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("weekday"), ptn_string(ptn_date_weekday_long(parts->tm_wday)));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("month"), ptn_string(ptn_date_month_long(parts->tm_mon)));
    ptn_array_set_entry(result.as.array, ptn_array_int_key(0), ptn_int((int64_t)timestamp));
    return result;
}

static PtnValue ptn_internal_localtime(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)line;
    time_t timestamp = argc >= 1 ? (time_t)ptn_value_to_integer(args[0]) : time(NULL);
    int associative = argc >= 2 && ptn_is_truthy(args[1]);
    struct tm *parts = localtime(&timestamp);
    if (parts == NULL) {
        return ptn_bool(0);
    }
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    const char *keys[] = { "tm_sec", "tm_min", "tm_hour", "tm_mday", "tm_mon", "tm_year", "tm_wday", "tm_yday", "tm_isdst" };
    int values[] = {
        parts->tm_sec, parts->tm_min, parts->tm_hour, parts->tm_mday, parts->tm_mon,
        parts->tm_year, parts->tm_wday, parts->tm_yday, parts->tm_isdst
    };
    for (int i = 0; i < 9; i++) {
        ptn_array_set_entry(
            result.as.array,
            associative ? ptn_array_string_key(keys[i]) : ptn_array_int_key(i),
            ptn_int(values[i])
        );
    }
    return result;
}

